30	/**
31	 * GAME_MOD_SYNC handler — reconcile a game server's installed mods to the desired
32	 * state recorded in `ServerMod` rows:
33	 *   - status INSTALLING → fetch + install the mod, then INSTALLED (or FAILED)
34	 *   - status REMOVING   → remove the mod, then delete the row (or FAILED)
35	 *
36	 * Wire into worker/index.ts handlers:  GAME_MOD_SYNC: gameModSync,
37	 *
38	 * THREE PATHS, mirroring game-config's honesty guard so we never tell a customer a
39	 * mod is installed when nothing was written to their server:
40	 *  - SANDBOX: simulate (flip INSTALLING→INSTALLED, REMOVING→REMOVED). Dev only.
41	 *  - REAL (ENABLE_REAL_GAMEMODS=1, not sandbox): install/remove over SSH via the
42	 *    per-source adapter. Where an adapter isn't implemented yet, the mod is marked
43	 *    FAILED with a clear reason — never silently "INSTALLED".
44	 *  - Neither (production, flag off): mark the queued changes FAILED with a plain
45	 *    message. A change we did NOT apply is a failure and must say so.
46	 */
47	
48	const REAL_ENABLED = !SANDBOX && process.env.ENABLE_REAL_GAMEMODS === "1";
49	
50	async function notify(userId: string, title: string, body?: string, href?: string) {
51	  try {
52	    await db.notification.create({ data: { userId, title, body, href } });
53	  } catch (e) {
54	    console.error("[game-mods] notify failed", e);
55	  }
56	}
