58	export async function gameModSync(job: Job): Promise<void> {
59	  const serverId = job.serverId;
60	  if (!serverId) throw new Error("game mod sync: job has no serverId");
61	
62	  const server = await db.server.findUnique({
63	    where: { id: serverId },
64	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
65	  });
66	  if (!server) throw new Error(`Server ${serverId} not found`);
67	
68	  const pending = await db.serverMod.findMany({
69	    where: { serverId, status: { in: ["INSTALLING", "REMOVING"] } },
70	    include: { mod: true },
71	  });
72	  if (pending.length === 0) return;
73	
74	  const installedNames: string[] = [];
75	  const removedNames: string[] = [];
76	  const failedNames: string[] = [];
77	
78	  for (const sm of pending) {
79	    const removing = sm.status === "REMOVING";
80	    try {
81	      if (SANDBOX) {
82	        // Dev simulation — no VM mutation.
83	        if (removing) {
84	          await db.serverMod.delete({ where: { id: sm.id } });
85	          removedNames.push(sm.mod.name);
86	        } else {
87	          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
88	          installedNames.push(sm.mod.name);
89	        }
90	        continue;
91	      }
92	
93	      if (!REAL_ENABLED) {
94	        // Honest failure: nothing was applied. Do NOT report success.
95	        await db.serverMod.update({
96	          where: { id: sm.id },
97	          data: {
98	            status: "FAILED",
99	            error:
100	              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
101	          },
102	        });
103	        failedNames.push(sm.mod.name);
104	        continue;
105	      }
106	
107	      // REAL path — install/remove over SSH via the per-source adapter.
108	      const modRow: ModRowFull = {
109	        gameFamily: sm.mod.gameFamily,
110	        source: sm.mod.source,
111	        sourceId: sm.mod.sourceId,
112	        slug: sm.mod.slug,
113	        name: sm.mod.name,
114	        url: sm.mod.url,
115	        variant: server.gameVariant ?? null,
116	        appliesTo: sm.mod.appliesToVariant ?? null,
117	      };
118	      const extra = EXTRA_SOURCE_SYNC[sm.mod.source];
119	      const result =
120	        sm.mod.source === "steam_workshop"
121	          ? await workshopSync(server, sm.mod.gameFamily, serverId)
122	          : extra
123	          ? await extra(server, modRow, removing, serverId)
124	          : removing
125	          ? await removeModReal(server, modRow)
126	          : await installModReal(server, modRow);
127	
128	      if (result.ok) {
129	        if (removing) {
130	          await db.serverMod.delete({ where: { id: sm.id } });
131	          removedNames.push(sm.mod.name);
132	        } else {
133	          await db.serverMod.update({
134	            where: { id: sm.id },
135	            data: { status: "INSTALLED", version: result.version ?? null, error: null },
136	          });
137	          installedNames.push(sm.mod.name);
138	        }
139	      } else {
140	        await db.serverMod.update({
141	          where: { id: sm.id },
142	          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
143	        });
144	        failedNames.push(sm.mod.name);
145	      }
146	    } catch (e) {
147	      const msg = e instanceof Error ? e.message : String(e);
148	      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
149	      await db.serverMod.update({
150	        where: { id: sm.id },
151	        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
152	        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
153	      });
154	      failedNames.push(sm.mod.name);
155	    }
156	  }
157	
158	  // One summary notification for the batch.
159	  const parts: string[] = [];
160	  if (installedNames.length) parts.push(`installed ${installedNames.join(", ")}`);
161	  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
162	  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
163	  const anyOk = installedNames.length > 0 || removedNames.length > 0;
164	  const allFailed = !anyOk && failedNames.length > 0;
165	
166	  await notify(
167	    server.userId,
168	    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
169	    parts.length ? `${parts.join("; ")}.` : "No changes were made.",
170	    `/dashboard/servers/${server.id}?tab=mods`
171	  );
172	}
