214	/** PascalCase a mod name for an Oxide/Carbon .cs filename (class-name convention). */
215	function pascal(name: string): string {
216	  const p = name.replace(/[^a-zA-Z0-9]+/g, " ").trim().split(/\s+/).map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
217	  return p || "Plugin";
218	}
219	
220	/** Deterministic on-disk target for a mod, or null if its source isn't installable. */
221	function planTarget(mod: ModRow): { kind: "jar" | "cs" | "zip" | "dll"; file?: string; folder?: string } | null {
222	  // TShock only loads TOP-LEVEL *.dll files from a plugin directory (TSAPI's
223	  // ServerApi.LoadPlugins: `GetFiles("*.dll")`, no recursion), so the
224	  // zip-into-a-subfolder shape the generic github case below uses would never
225	  // load. One .dll, deterministic name, so uninstall is a plain rm.
226	  if (mod.gameFamily === "terraria") {
227	    return mod.source === "github" ? { kind: "dll", file: `nxeon-${mod.slug}.dll` } : null;
228	  }
229	  switch (mod.source) {
230	    case "modrinth":
231	    case "spigotmc":
232	      return { kind: "jar", file: `nxeon-${mod.slug}.jar` };
233	    case "umod":
234	      return { kind: "cs", file: `${pascal(mod.name)}.cs` };
235	    case "thunderstore":
236	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
237	    case "github":
238	      // Same "zip-of-a-folder" shape as thunderstore — a reasonable generic
239	      // default for a GitHub release asset, but untested against a real CS2
240	      // plugin's actual archive layout (addons/ layout vs. a bare .dll/.so vs.
241	      // a source tarball all differ per repo). Harmless today: the only
242	      // github-sourced family in INSTALLABLE_FAMILIES is terraria, which
243	      // returns its own "dll" target above before reaching this switch; for
244	      // every other github family (cs2) modDirShell returns null first and
245	      // this never actually runs an install. Revisit this specific shape when
246	      // another family is wired up.
247	      return { kind: "zip", folder: `nxeon-${mod.slug}` };
248	    default:
249	      return null; // nexus / curseforge / codefling / hangar — manual
250	  }
251	}
