253	/** Resolve a direct download URL from the source's API (worker-side). */
254	async function resolveUrl(mod: ModRowFull): Promise<string | null> {
255	  const id = mod.sourceId ?? "";
256	  try {
257	    switch (mod.source) {
258	      case "umod":
259	        return `https://umod.org/plugins/${id}.cs`;
260	      case "spigotmc":
261	        return `https://api.spiget.org/v2/resources/${id}/download`;
262	      case "modrinth": {
263	        const loader = modrinthLoader(mod);
264	        const q = loader ? `?loaders=["${loader}"]` : "";
265	        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
266	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
267	        });
268	        if (!res.ok) return null;
269	        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
270	        const v = versions[0];
271	        if (!v) return null;
272	        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
273	      }
274	      case "thunderstore": {
275	        const [author, ...rest] = id.split("-");
276	        if (!rest.length) return null;
277	        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
278	          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
279	        });
280	        if (!res.ok) return null;
281	        const pkg = (await res.json()) as { latest?: { download_url?: string } };
282	        return pkg.latest?.download_url ?? null;
283	      }
284	      case "github": {
285	        // id is "owner/repo" (scripts/import-github-catalog.ts's sourceId
286	        // convention, matching prisma/seed-gamemods.ts's pre-existing CS2
287	        // rows). Resolved fresh at install time, same as modrinth above —
288	        // nothing about the release is cached on the GameMod row, so a mod
289	        // author cutting a new release just works with no re-import needed.
290	        const headers: Record<string, string> = { "User-Agent": "Nxeon/1.0 (mod-manager)", Accept: "application/vnd.github+json" };
291	        if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
292	        const res = await fetch(`https://api.github.com/repos/${id}/releases/latest`, { headers });
293	        if (!res.ok) return null; // no releases yet, repo renamed/gone, or rate-limited
294	        const release = (await res.json()) as { assets?: Array<{ browser_download_url: string; name: string }> };
295	        const assets = release.assets ?? [];
296	        if (assets.length === 0) return null;
297	        // TShock plugin: exactly one .dll asset, or nothing. A release that
298	        // ships several (a plugin plus its own dependency, e.g. SFactions +
299	        // Abilities.dll) needs them side by side in the SAME directory TSAPI's
300	        // assembly resolver searches, which a one-file install can't promise —
301	        // so it's refused up front rather than half-installed.
302	        if (mod.gameFamily === "terraria") {
303	          const dlls = assets.filter((a) => /\.dll$/i.test(a.name));
304	          return dlls.length === 1 ? dlls[0].browser_download_url : null;
305	        }
306	        // Prefer a real packaged archive over a loose source-only asset when both exist.
307	        const archive = assets.find((a) => /\.(zip|tar\.gz|tgz)$/i.test(a.name));
308	        return (archive ?? assets[0]).browser_download_url;
309	      }
310	      default:
311	        return null;
312	    }
313	  } catch (e) {
314	    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
315	    return null;
316	  }
317	}
