329	/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
330	/* The shared set in lib/mod-install-support.ts is what the PANEL uses to decide
331	   whether to draw an Install button at all. If this switch ever grows a case
332	   that isn't in that set the button never appears, and if the set grows a
333	   family this switch doesn't handle the button appears and fails — which is the
334	   bug that module was written to end. Fail loudly here rather than let them
335	   drift apart silently. */
336	function modDirShell(family: string, variant: string | null): string | null {
337	  if (!INSTALLABLE_FAMILIES.has(family)) return null;
338	  switch (family) {
339	    case "minecraft": {
340	      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
341	      const sub = modded ? "mods" : "plugins";
342	      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
343	    }
344	    case "rust":
345	      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
346	    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
347	    // BepInEx installed, since lloesche/valheim-server's own real directory is
348	    // lowercase `bepinex` (confirmed against its README). Use the documented,
349	    // fixed path directly instead of searching for it: `/config` is the
350	    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
351	    // itself watches `/config/bepinex/plugins` for user-added plugins and
352	    // copies them into the real BepInEx plugin dir on boot — this is the
353	    // customer-facing "drop mods here" folder by design, not an internal path.
354	    case "valheim":
355	      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
356	    // Read off the LIVE container (mount + `-additionalplugins` flag), never
357	    // assumed — see terrariaPluginDirShell. A server provisioned before the
358	    // plugin mount existed resolves to nothing and gets an honest NODIR.
359	    case "terraria":
360	      return terrariaPluginDirShell();
361	    default:
362	      return null;
363	  }
364	}
