368	async function installModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
369	  const target = planTarget(mod);
370	  if (!target) {
371	    return { ok: false, error: `Auto-install isn't available for ${mod.source} mods yet — install manually${mod.url ? ` from ${mod.url}` : ""}.` };
372	  }
373	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
374	  if (!dirShell) {
375	    return { ok: false, error: `Auto-install isn't wired for this game yet.` };
376	  }
377	  if (!RESOLVABLE_SOURCES.has(mod.source)) {
378	    return { ok: false, error: `We can't fetch downloads from ${mod.source} — install this one by hand in Files.` };
379	  }
380	  const url = await resolveUrl(mod);
381	  if (!url) {
382	    return {
383	      ok: false,
384	      error:
385	        mod.gameFamily === "terraria"
386	          ? "Couldn't find a single .dll in this plugin's latest GitHub release (it may have moved or changed format) — install it by hand in Files."
387	          : "Could not resolve a download for this mod (it may have moved).",
388	    };
389	  }
390	  if (mod.gameFamily === "terraria") return installTerrariaPlugin(server, target.file!, url);
391	
392	  let cmd: string;
393	  if (target.kind === "zip") {
394	    cmd =
395	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
396	      `tmp=$(mktemp -d); if curl -fsSL --max-time 180 -o "$tmp/m.zip" '${shq(url)}'; then ` +
397	      `rm -rf "$dir/${target.folder}"; mkdir -p "$dir/${target.folder}"; ` +
398	      `unzip -oq "$tmp/m.zip" -d "$dir/${target.folder}" && echo OK || echo UNZIP; rm -rf "$tmp"; else echo FAIL; fi`;
399	  } else {
400	    cmd =
401	      `dir=$( ${dirShell} ); if [ -z "$dir" ]; then echo NODIR; exit 0; fi; ` +
402	      `if curl -fsSL --max-time 180 -o "$dir/${target.file}" '${shq(url)}'; then echo OK; else echo FAIL; fi`;
403	  }
404	
405	  const out = await withSsh(server, (conn) => execRemote(conn, cmd));
406	  const s = out.stdout.trim();
407	  if (s.endsWith("OK")) return { ok: true };
408	  if (s.includes("NODIR")) return { ok: false, error: "Couldn't find the game's mod folder — is the server fully set up?" };
409	  if (s.includes("UNZIP")) return { ok: false, error: "Downloaded the mod but couldn't unpack it (unzip missing?)." };
410	  return { ok: false, error: "Download failed on the server." };
411	}
