413	async function removeModReal(server: SshServer, mod: ModRowFull): Promise<ModResult> {
414	  const target = planTarget(mod);
415	  const dirShell = modDirShell(mod.gameFamily, mod.variant);
416	  if (!target || !dirShell) return { ok: true }; // nothing we placed → nothing to remove
417	  if (mod.gameFamily === "terraria") return removeTerrariaPlugin(server, target.file!);
418	  const rm =
419	    target.kind === "zip"
420	      ? `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -rf "$dir/${target.folder}"; echo OK`
421	      : `dir=$( ${dirShell} ); [ -n "$dir" ] && rm -f "$dir/${target.file}"; echo OK`;
422	  await withSsh(server, (conn) => execRemote(conn, rm));
423	  return { ok: true };
424	}
