426	// ===========================================================================
427	// Terraria (TShock) — place a plugin .dll, restart, PROVE it loaded, or undo.
428	//
429	// Every other file-drop family above ends at "the file is in the folder".
430	// That is not enough here, for two reasons verified against a real running
431	// `ryshe/terraria` container (TShock 6.1.0.0 / TSAPI 2.1 / Terraria 1.4.5.6,
432	// 2026-09-30 — see docs/DOCUMENTATION.md's entry of that date):
433	//
434	//  1. TShock only loads plugins at startup. A file dropped into a running
435	//     server does nothing until the next restart, so "installed" without a
436	//     restart would be a claim nothing had checked yet.
437	//  2. A plugin that fails to load or throws in Initialize() does not just
438	//     skip itself: TSAPI logs "Startup aborted due to an exception in the
439	//     Server API initialization" and stops initializing plugins — observed
440	//     live, the world still comes up and logs "Server started", so the port
441	//     answers while TShock's own protections/commands may never have been
442	//     wired up. A catalogue entry built for another TShock version (or one
443	//     that hardcodes a path this image doesn't have — also observed live)
444	//     would otherwise sit there as a time bomb for the customer's next
445	//     restart.
446	//
447	// So an install here = download → check it's a PE file → restart the game's
448	// own systemd unit → read the new run's log → INSTALLED only if TShock logged
449	// a NEW "Plugin X vY (by Z) initiated." line, nothing aborted startup, TSAPI
450	// reported no unhandled exception from that same plugin, and the same
451	// container run is still up 20s after "Server started" (a plugin that shuts
452	// the server down on its own — observed live — would otherwise pass once
453	// systemd's Restart=always brings it back for a moment); anything else
454	// is rolled back (file removed or the previous version restored, server
455	// restarted again) and reported FAILED with TShock's own reason. The scripts
456	// and the marker parsing live in lib/terraria-plugins.ts (pure, unit-tested);
457	// this file only ships them to the VM and waits.
458	//
459	// WHERE the file goes: TERRARIA_PLUGIN_MOUNT, a separate host folder TShock
460	// is told to load from with TSAPI's own `-additionalplugins` flag (confirmed
461	// present in this build's TerrariaServer.dll) — never /tshock/ServerPlugins,
462	// which holds TShock's own core. lib/terraria-plugins.ts has the live test
463	// behind that choice.
464	//
465	// The whole sequence runs as ONE detached script on the VM (`runDetached`),
466	// polled over short SSH sessions, so a dropped SSH connection mid-restart
467	// can't kill it halfway between "file placed" and "verified or rolled back".
468	// ===========================================================================
469	
470	const sleepMs = (ms: number) => new Promise((r) => setTimeout(r, ms));
471	
472	/**
473	 * Run `script` on the VM fully detached (setsid+nohup, output to a log file)
474	 * and poll that log over fresh short SSH sessions until it prints NXTP:END.
475	 * A dropped connection (seen live on a real node during this work: ECONNRESET
476	 * mid-command) then only costs one poll instead of killing the script halfway.
477	 * `tag` must be unique per attempt; re-sending the same tag never starts a
478	 * second copy.
479	 */
480	async function runDetached(server: SshServer, tag: string, script: string, timeoutMs: number): Promise<string> {
481	  const dir = "/root/.nxeon-jobs";
482	  const b64 = Buffer.from(script, "utf8").toString("base64");
483	  const start =
484	    `mkdir -p ${dir} && if [ -e ${dir}/${tag}.log ]; then echo NXSTARTED; else ` +
485	    `echo '${b64}' | base64 -d > ${dir}/${tag}.sh && : > ${dir}/${tag}.log && ` +
486	    `(setsid nohup sh ${dir}/${tag}.sh > ${dir}/${tag}.log 2>&1 < /dev/null &) && echo NXSTARTED; fi`;
487	  // Five tries over ~50s: during this work a real node answered a VM's SSH
488	  // port from a DIFFERENT host in bursts of tens of seconds (auth rejected,
489	  // nothing run). Safe to repeat — the tag guard above makes a start that
490	  // succeeded but lost its reply a no-op the second time.
491	  let started = false;
492	  for (let attempt = 0; attempt < 5 && !started; attempt++) {
493	    try {
494	      const r = await withSsh(server, (c) => execRemote(c, start));
495	      started = /NXSTARTED/.test(r.stdout);
496	    } catch (e) {
497	      if (attempt === 4) throw e;
498	      await sleepMs(5000 * (attempt + 1));
499	    }
500	  }
501	  if (!started) throw new Error("could not start the plugin change on the server");
502	
503	  const deadline = Date.now() + timeoutMs;
504	  while (Date.now() < deadline) {
505	    await sleepMs(5000);
506	    try {
507	      const r = await withSsh(server, (c) => execRemote(c, `cat ${dir}/${tag}.log 2>/dev/null`));
508	      if (r.stdout.includes("NXTP:END")) {
509	        await withSsh(server, (c) => execRemote(c, `rm -f ${dir}/${tag}.sh ${dir}/${tag}.log`)).catch(() => {});
510	        return r.stdout;
511	      }
512	    } catch {
513	      /* transient SSH failure — keep polling until the deadline */
514	    }
515	  }
516	  throw new Error("timed out waiting for the server to restart with the plugin change");
517	}
