519	async function installTerrariaPlugin(server: SshServer, file: string, url: string): Promise<ModResult> {
520	  const tag = `tplugin-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
521	  const out = await runDetached(server, tag, terrariaInstallScript(file, url), TERRARIA_JOB_TIMEOUT_MS);
522	  return parseTerrariaInstall(out);
523	}
