531	// --- SSH transport (root@VM, password from the same source as the file manager) ---
532	
533	type ModRowFull = ModRow & { variant: string | null; appliesTo: string | null };
534	
535	function withSsh<T>(server: SshServer, fn: (conn: Client) => Promise<T>): Promise<T> {
536	  return new Promise((resolve, reject) => {
537	    const t = connectionTarget(server as any);
538	    if (!t) return reject(new Error("server is not reachable yet"));
539	    const password = serverRootPassword(server as any);
540	    if (!password) return reject(new Error("server has no root password set"));
541	    const conn = new Client();
542	    let settled = false;
543	    const finish = (err: Error | null, val?: T) => {
544	      if (settled) return;
545	      settled = true;
546	      try { conn.end(); } catch { /* best-effort */ }
547	      err ? reject(err) : resolve(val as T);
548	    };
549	    conn.on("ready", () => {
550	      fn(conn).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
551	    });
552	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
553	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
554	  });
555	}
556	
557	function execRemote(conn: Client, cmd: string, timeoutMs: number = EXEC_TIMEOUT_MS): Promise<{ code: number; stdout: string; stderr: string }> {
558	  return new Promise((resolve, reject) => {
559	    conn.exec(cmd, (err, stream: ClientChannel) => {
560	      if (err) return reject(err);
561	      let stdout = "";
562	      let stderr = "";
563	      const timer = setTimeout(() => { try { stream.close(); } catch { /* ignore */ } }, timeoutMs);
564	      stream
565	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, stdout, stderr }); })
566	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
567	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
568	    });
569	  });
570	}
