679	function withSftp<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
680	  return new Promise((resolve, reject) => {
681	    const t = connectionTarget(server as any);
682	    if (!t) return reject(new Error("server is not reachable yet"));
683	    const password = serverRootPassword(server as any);
684	    if (!password) return reject(new Error("server has no root password set"));
685	    const conn = new Client();
686	    let settled = false;
687	    const finish = (err: Error | null, val?: T) => {
688	      if (settled) return;
689	      settled = true;
690	      try { conn.end(); } catch { /* best-effort */ }
691	      err ? reject(err) : resolve(val as T);
692	    };
693	    conn.on("ready", () => {
694	      conn.sftp((err, sftp) => {
695	        if (err) return finish(err);
696	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
697	      });
698	    });
699	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
700	    conn.connect({ host: t.host, port: t.port, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
701	  });
702	}
