710	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
711	  return new Promise((resolve, reject) => {
712	    sftp.writeFile(path, content, { encoding: "utf8" }, (err) => (err ? reject(err) : resolve()));
713	  });
714	}
