725	async function readEnvMap(conn: Client, container: string): Promise<Map<string, string> | null> {
726	  const inspect = await execRemote(conn, `docker inspect ${container} --format '{{json .Config.Env}}'`);
727	  if (inspect.code !== 0) return null;
728	  try {
729	    const arr: string[] = JSON.parse(inspect.stdout.trim());
730	    const m = new Map<string, string>();
731	    for (const e of arr) {
732	      const i = e.indexOf("=");
733	      if (i >= 0) m.set(e.slice(0, i), e.slice(i + 1));
734	    }
735	    m.delete("PATH");
736	    return m;
737	  } catch {
738	    return null;
739	  }
740	}
