748	async function resolveUnit(conn: Client, family: string): Promise<string | null> {
749	  const hints = controlSpec(family)?.serviceHints ?? [];
750	  if (!hints.length) return null;
751	  const probe = hints.map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`).join(" ");
752	  const { stdout } = await execRemote(conn, probe);
753	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.endsWith(".service"));
754	  return hit ?? null;
755	}
