960	/** Update `Key=Value` lines in a PZ-style ini, preserving everything else;
961	 *  append missing keys. Same shape as worker/game-config.ts's
962	 *  `updateKeyValue` for server.properties — kept as its own copy since that
963	 *  function isn't exported and this file deliberately doesn't import
964	 *  low-level helpers from game-config.ts (see the container-recreate
965	 *  section's comment above). */
966	function updateIniKeyValue(content: string, updates: Record<string, string>): string {
967	  const lines = content.split(/\r?\n/);
968	  const seen = new Set<string>();
969	  for (let i = 0; i < lines.length; i++) {
970	    const t = lines[i].trim();
971	    if (!t || t.startsWith("#")) continue;
972	    const eq = lines[i].indexOf("=");
973	    if (eq < 0) continue;
974	    const key = lines[i].slice(0, eq).trim();
975	    if (Object.prototype.hasOwnProperty.call(updates, key)) {
976	      lines[i] = `${key}=${updates[key]}`;
977	      seen.add(key);
978	    }
979	  }
980	  for (const k of Object.keys(updates)) {

981	    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
982	  }
983	  return lines.join("\n");
984	}
