986	/**
987	 * Project Zomboid needs BOTH the numeric Workshop id (`WorkshopItems=`) AND
988	 * the mod's own internal string id from its `mod.info` file (`Mods=`) — two
989	 * different values, confirmed against PZwiki. The Workshop API never exposes
990	 * the second one; the only way to learn it is to look inside the mod's own
991	 * files. We do that with a single, throwaway `steamcmd workshop_download_item`
992	 * run INSIDE the customer's own container (Valve's own tool, on their own
993	 * VM — not a Nxeon download/mirror), read `mod.info`, then delete what we
994	 * fetched immediately — the dedicated server re-fetches its own real copy on
995	 * boot via `WorkshopItems=`, so nothing is kept or served from here. The
996	 * result is cached onto the `GameMod` row so this only ever runs once per
997	 * mod, for any server.
998	 */
999	async function resolvePzModStringId(conn: Client, sourceId: string): Promise<string | null> {
1000	  const tmp = `/tmp/nxw-${sourceId.replace(/[^0-9]/g, "")}`;
1001	  const cmd =
1002	    `docker exec projectzomboid steamcmd +login anonymous +force_install_dir '${shq(tmp)}' +workshop_download_item ${PZ_APPID} ${shq(sourceId)} +quit >/dev/null 2>&1; ` +
1003	    `docker exec projectzomboid sh -c "find '${shq(tmp)}' -iname mod.info 2>/dev/null | head -5 | xargs -r cat" 2>/dev/null; ` +
1004	    `docker exec projectzomboid rm -rf '${shq(tmp)}' >/dev/null 2>&1`;
1005	  const { stdout } = await execRemote(conn, cmd);
1006	  const ids = [...stdout.matchAll(/^\s*id\s*=\s*(.+?)\s*$/gim)].map((m) => m[1].trim()).filter(Boolean);
1007	  return ids.length ? ids.join(";") : null;
1008	}
