1172	async function patchEmpyrionScenario(conn: Client, sftp: SFTPWrapper, root: string, scenarioName: string | null): Promise<ModResult> {
1173	  const found = await execRemote(conn, `find '${shq(root)}' -maxdepth 8 -type f -iname 'dedicated.yaml' 2>/dev/null | head -1`);
1174	  const path = found.stdout.trim();
1175	  if (!path) return { ok: false, error: "Could not locate dedicated.yaml on this server — nothing was changed." };
1176	  const existing = await sftpRead(sftp, path);
1177	  if (existing == null) return { ok: false, error: "dedicated.yaml disappeared — nothing was changed." };
1178	  if (!/^\s*CustomScenario\s*:/m.test(existing)) {
1179	    return { ok: false, error: "Could not find a CustomScenario key in dedicated.yaml — set it manually to activate this scenario." };
1180	  }
1181	  const line = scenarioName ? `    CustomScenario: '${scenarioName}'` : `    CustomScenario: ''`;
1182	  const updated = existing.replace(/^\s*CustomScenario\s*:.*$/m, line);
1183	  await sftpWrite(sftp, path, updated);
1184	  return { ok: true };
1185	}
