1306	/** Python run ON THE VM (python3 ships with every Nxeon Ubuntu template):
1307	 *  reads modinfo.json out of mod zips — Vintage Story's own manifest — so
1308	 *  dependencies come from the mod itself, not a guess. VS parses that file
1309	 *  leniently (case-insensitive keys, comments allowed), so this does too. */
1310	const VS_MODINFO_PY = String.raw`
1311	import sys, json, zipfile, re, os
1312	def load(t):
1313	    try: return json.loads(t)
1314	    except Exception:
1315	        t = re.sub(r'/\*.*?\*/', '', t, flags=re.S)
1316	        t = re.sub(r'(^|[^:"])//[^\n]*', r'\1', t)
1317	        t = re.sub(r',\s*([}\]])', r'\1', t)
1318	        return json.loads(t)
1319	def info_zip(p):
1320	    try:
1321	        with zipfile.ZipFile(p) as z:
1322	            ns = sorted([n for n in z.namelist() if n.lower().rsplit('/',1)[-1] == 'modinfo.json'], key=lambda n: n.count('/'))
1323	            if not ns: return None
1324	            d = load(z.read(ns[0]).decode('utf-8-sig'))
1325	    except Exception:
1326	        return None
1327	    d = {str(k).lower(): v for k, v in d.items()}
1328	    mid = str(d.get('modid') or '').strip().lower() or re.sub(r'[^a-z0-9]', '', str(d.get('name') or '').lower())
1329	    deps = d.get('dependencies') or {}
1330	    return {'modid': mid, 'version': str(d.get('version') or ''), 'deps': {str(k).lower(): str(v) for k, v in deps.items()}}
1331	if sys.argv[1] == 'one':
1332	    print(json.dumps(info_zip(sys.argv[2])))
1333	else:
1334	    ids = []
1335	    for f in sorted(os.listdir(sys.argv[2])):
1336	        if f.lower().endswith('.zip'):
1337	            i = info_zip(os.path.join(sys.argv[2], f))
1338	            if i and i['modid']: ids.append(i['modid'])
1339	    print(json.dumps(ids))
1340	`;
