1370	/** Download one ModDB file onto the VM (into `tmpDir`), returning its path. */
1371	async function vsDownload(conn: Client, tmpDir: string, rel: VsRelease, name: string): Promise<string | null> {
1372	  const ext = vsFileExt(rel.filename);
1373	  if (!ext) return null;
1374	  const dest = `${tmpDir}/${name}.${ext}`;
1375	  // The ModDB's own CDN links carry the original filename, spaces included,
1376	  // in a `?dl=` query ("…zip?dl=ExpandedFoods 2.0.0-dev.15.zip") — curl
1377	  // rejects a raw space outright, so normalize through the WHATWG URL parser
1378	  // (percent-encodes it) and refuse anything that isn't a plain https URL.
1379	  let url: string;
1380	  try {
1381	    const u = new URL(rel.mainfile);
1382	    if (u.protocol !== "https:") return null;
1383	    url = u.toString();
1384	  } catch {
1385	    return null;
1386	  }
1387	  const r = await execRemote(conn, `curl -fsSL --max-time 180 -o '${shq(dest)}' '${shq(url)}' && echo NXOK`);
1388	  return /NXOK/.test(r.stdout) ? dest : null;
1389	}
