1391	async function vintageStorySync(server: SshServer, mod: ModRowFull, removing: boolean): Promise<ModResult> {
1392	  if (mod.gameFamily !== "vintagestory") return { ok: false, error: "This mod source only serves Vintage Story." };
1393	  const safeSlug = mod.slug.replace(/[^a-z0-9_-]/gi, "");
1394	  if (!safeSlug) return { ok: false, error: "This catalogue entry has no usable identifier." };
1395	
1396	  return withSsh(server, async (conn) => {
1397	    const dirCheck = await execRemote(conn, `[ -d '${VS_MODS}' ] && echo YES`);
1398	    if (dirCheck.stdout.trim() !== "YES") {
1399	      return { ok: false, error: "Couldn't find this server's Mods folder — is the server fully set up?" };
1400	    }
1401	
1402	    if (removing) {
1403	      await execRemote(conn, `rm -f '${VS_MODS}'/nxeon-${safeSlug}.zip '${VS_MODS}'/nxeon-${safeSlug}.dll '${VS_MODS}'/nxeon-${safeSlug}.cs`);
1404	      await restartGame(conn, "vintagestory", "vintagestory");
1405	      return { ok: true };
1406	    }
1407	
1408	    const gameVersion = await vsGameVersion(conn);
1409	    if (!gameVersion) return { ok: false, error: "Couldn't read this server's Vintage Story version — start it once, then try again." };
1410	    const detail = await fetchVsMod(mod.sourceId ?? mod.slug);
1411	    if (!detail) return { ok: false, error: "Couldn't reach this mod on the Vintage Story ModDB (it may have been removed)." };
1412	    const rel = pickVsRelease(detail.releases, gameVersion);
1413	    if (!rel) {
1414	      return { ok: false, error: `${detail.name} has no release for Vintage Story ${gameVersion} yet — nothing was installed.` };
1415	    }
1416	
1417	    const tmpRes = await execRemote(conn, "mktemp -d");
1418	    const tmp = tmpRes.stdout.trim();
1419	    if (!tmp.startsWith("/tmp/")) return { ok: false, error: "Couldn't prepare a download folder on the server." };
1420	    try {
1421	      const mainPath = await vsDownload(conn, tmp, rel, `nxeon-${safeSlug}`);
1422	      if (!mainPath) return { ok: false, error: "Download from the Vintage Story ModDB failed on the server." };
1423	
1424	      // Dependencies, read from each mod's own modinfo.json, resolved against
1425	      // what's already in the Mods folder, fetched from the ModDB by modid.
1426	      // Bounded (depth + count) so a malformed or circular manifest can't loop.
1427	      const present = await vsInstalledModIds(conn);
1428	      const staged: string[] = [mainPath];
1429	      const queue: { path: string; depth: number }[] = [{ path: mainPath, depth: 0 }];
1430	      const seen = new Set<string>();
1431	      const missing: string[] = [];
1432	      let mainModId: string | null = null;
1433	      while (queue.length) {
1434	        const { path, depth } = queue.shift()!;
1435	        if (!path.endsWith(".zip")) continue; // .dll/.cs code mods declare deps in code attributes, not modinfo.json
1436	        const info = await vsInspect(conn, path);
1437	        if (!info) continue;
1438	        if (path === mainPath) mainModId = info.modid;
1439	        seen.add(info.modid);
1440	        for (const dep of Object.keys(info.deps)) {
1441	          if (VS_BUILTIN_MODIDS.has(dep) || present.has(dep) || seen.has(dep)) continue;
1442	          seen.add(dep);
1443	          if (depth >= 3 || staged.length >= 12) { missing.push(dep); continue; }
1444	          const d = await fetchVsMod(dep);
1445	          const dRel = d ? pickVsRelease(d.releases, gameVersion) : null;
1446	          const dPath = dRel ? await vsDownload(conn, tmp, dRel, `nxeon-dep-${dep.replace(/[^a-z0-9_-]/g, "")}`) : null;
1447	          if (!dPath) { missing.push(dep); continue; }
1448	          staged.push(dPath);
1449	          queue.push({ path: dPath, depth: depth + 1 });
1450	        }
1451	      }
1452	      if (missing.length) {
1453	        return {
1454	          ok: false,
1455	          error: `${detail.name} needs ${missing.join(", ")}, which couldn't be found on the ModDB for Vintage Story ${gameVersion} — nothing was installed.`,
1456	        };
1457	      }
1458	
1459	      // Everything resolved: move into place (deterministic names so removal
1460	      // is a plain rm), owned like the folder the game itself created.
1461	      const moves = staged.map((p) => `mv -f '${shq(p)}' '${VS_MODS}/' && chown --reference='${VS_MODS}' '${VS_MODS}/${shq(p.split("/").pop()!)}'`).join(" && ");
1462	      const mv = await execRemote(conn, `${moves} && echo NXOK`);
1463	      if (!/NXOK/.test(mv.stdout)) return { ok: false, error: "Couldn't move the downloaded mod into the Mods folder." };
1464	
1465	      // Restart and read the fresh log: VS archives server-main.log and starts
1466	      // a new file on every boot, so wait for a NEW file (different inode) that
1467	      // has reached its mod list, then check this mod is in it.
1468	      const ino = (await execRemote(conn, `stat -c %i '${VS_LOG}' 2>/dev/null`)).stdout.trim();
1469	      if (!(await restartGame(conn, "vintagestory", "vintagestory"))) {
1470	        return { ok: false, error: "The mod was placed, but the server didn't restart — restart it from the dashboard to load it." };
1471	      }
1472	      const mainInfo = mainModId;
1473	      const probe = await execRemote(
1474	        conn,
1475	        `for i in $(seq 1 60); do n=$(stat -c %i '${VS_LOG}' 2>/dev/null); ` +
1476	          `if [ -n "$n" ] && [ "$n" != '${shq(ino)}' ] && grep -q 'Mods, sorted by dependency' '${VS_LOG}'; then grep -m1 'Mods, sorted by dependency' '${VS_LOG}'; exit 0; fi; sleep 2; done; echo NXTIMEOUT`
1477	      );
1478	      const line = probe.stdout.trim();
1479	      if (mainInfo && line && !/NXTIMEOUT/.test(line)) {
1480	        const loaded = line.replace(/^.*Mods, sorted by dependency:\s*/, "").split(/,\s*/).map((s) => s.trim().toLowerCase());
1481	        if (!loaded.includes(mainInfo)) {
1482	          return { ok: false, error: `The server restarted but did not load ${detail.name} — check the server log for the reason.` };
1483	        }
1484	      }
1485	      return { ok: true, version: rel.modversion };
1486	    } finally {
1487	      await execRemote(conn, `rm -rf '${shq(tmp)}'`);
1488	    }
1489	  });
1490	}
