1492	// --- Container recreate that reproduces the RUNNING container ---------------
1493	//
1494	// The older per-family env writers above (ark/dst/squad/soulmask) each carry
1495	// a hand-copied `runFlags` string that has to be kept in sync with the
1496	// family's OsTemplate setupScript by hand. For the families added in this
1497	// pass the flags are instead READ BACK from the live container (`docker
1498	// inspect`): its real port bindings, bind mounts, stop timeout, hostname and
1499	// any entrypoint/command override — so a setupScript change, or a customer
1500	// setting applied at provision time, can't be silently dropped by a mod
1501	// install. Anything this can't faithfully reproduce (a multi-part entrypoint
1502	// override) is refused rather than approximated.
1503	
1504	type InspectJson = {
1505	  Config?: { Image?: string; Hostname?: string; StopTimeout?: number | null; Entrypoint?: string[] | null; Cmd?: string[] | null };
1506	  HostConfig?: { Binds?: string[] | null; PortBindings?: Record<string, { HostIp?: string; HostPort?: string }[] | null> | null };
1507	};
1508	
1509	async function inspectRunSpec(conn: Client, container: string): Promise<{ flags: string; image: string } | { error: string }> {
1510	  const r = await execRemote(conn, `docker inspect ${container} --format '{{json .}}'`);
1511	  if (r.code !== 0) return { error: `Could not find the "${container}" container — is the server fully set up?` };
1512	  let j: InspectJson;
1513	  try {
1514	    j = JSON.parse(r.stdout.trim());
1515	  } catch {
1516	    return { error: "Could not read the game container's configuration." };
1517	  }
1518	  const image = j.Config?.Image;
1519	  if (!image || !/^[\w./:@-]+$/.test(image)) return { error: "Could not determine the game container's image." };
1520	
1521	  const flags: string[] = [];
1522	  for (const [cport, binds] of Object.entries(j.HostConfig?.PortBindings ?? {})) {
1523	    if (!/^\d+\/(tcp|udp)$/.test(cport)) continue;
1524	    for (const b of binds ?? []) {
1525	      const hp = b.HostPort ?? "";
1526	      if (!/^\d+$/.test(hp)) continue;
1527	      const ip = b.HostIp && /^[\d.]+$/.test(b.HostIp) && b.HostIp !== "0.0.0.0" ? `${b.HostIp}:` : "";
1528	      flags.push(`-p ${ip}${hp}:${cport}`);
1529	    }
1530	  }
1531	  for (const bind of j.HostConfig?.Binds ?? []) flags.push(`-v '${shq(bind)}'`);
1532	  if (typeof j.Config?.StopTimeout === "number") flags.push(`--stop-timeout ${j.Config.StopTimeout}`);
1533	  if (j.Config?.Hostname === container) flags.push(`--hostname ${container}`);
1534	
1535	  const imgRes = await execRemote(conn, `docker image inspect '${shq(image)}' --format '{{json .Config}}'`);
1536	  let img: { Entrypoint?: string[] | null; Cmd?: string[] | null } = {};
1537	  try {
1538	    img = JSON.parse(imgRes.stdout.trim());
1539	  } catch {
1540	    /* image metadata unavailable — treat as no override information */
1541	  }
1542	  const same = (a: unknown, b: unknown) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
1543	  if (!same(j.Config?.Entrypoint, img.Entrypoint)) {
1544	    const ep = j.Config?.Entrypoint ?? [];
1545	    if (ep.length !== 1) return { error: "This server's container uses a custom entrypoint that can't be safely reproduced — nothing was changed." };
1546	    flags.push(`--entrypoint '${shq(ep[0])}'`);
1547	  }
1548	  const args = !same(j.Config?.Cmd, img.Cmd) && j.Config?.Cmd?.length ? j.Config.Cmd.map((a) => `'${shq(a)}'`).join(" ") : "";
1549	  return { flags: flags.join(" "), image: args ? `${image} ${args}` : image };
1550	}
