1552	/** Set (or clear, when `value` is "") one env var on a family's container and
1553	 *  recreate it with everything else exactly as it was. */
1554	async function setContainerEnv(
1555	  server: SshServer,
1556	  family: string,
1557	  container: string,
1558	  key: string,
1559	  value: string
1560	): Promise<ModResult> {
1561	  return withSftp(server, async (conn, sftp) => {
1562	    const envMap = await readEnvMap(conn, container);
1563	    if (!envMap) return { ok: false, error: `Could not find the "${container}" container — is the server fully set up?` };
1564	    const spec = await inspectRunSpec(conn, container);
1565	    if ("error" in spec) return { ok: false, error: spec.error };
1566	    if (value) envMap.set(key, value);
1567	    else envMap.delete(key);
