1575	// --- Killing Floor 2 — Steam Workshop, config-write -------------------------
1576	//
1577	// `[OnlineSubsystemSteamworks.KFWorkshopSteamworks] ServerSubscribedWorkshopItems=<id>`
1578	// in KFGame/Config/LinuxServer-KFEngine.ini is KF2's own dedicated-server
1579	// Workshop subscription list: the server downloads each item from Steam
1580	// itself at startup (Tripwire's documented mechanism). Nxeon only writes ids.
1581	//
1582	// VERIFIED LIVE 2026-09-30 on a real container of the production image
1583	// (rouhim/killing-floor-2-server): with two ids written the server logged
1584	// "NetComeGo: Downloading item 675314991" / "…1130264785" and populated
1585	// KFGame/Cache/<id>/. That same run is why this edits the ini directly
1586	// rather than going through the image's own KF2_SERVER_SUBSCRIBED_WORKSHOP_ITEMS
1587	// env var: the image's envini step only ever appends lines, so after removing
1588	// one of the two items and recreating, the removed id was still subscribed
1589	// and the kept one was listed twice. The edit happens with the server STOPPED
1590	// (UE3 rewrites its ini on shutdown), and the env var is cleared if an
1591	// earlier build of this installer ever set it.
1592	const KF2_INI = "/opt/kf2/data/KFGame/Config/LinuxServer-KFEngine.ini";
1593	
1594	async function applyKf2Workshop(server: SshServer, ids: string[]): Promise<ModResult> {
1595	  const clean = ids.filter(isWorkshopId);
1596	  const envSet = await withSsh(server, async (conn) => {
1597	    const env = await readEnvMap(conn, "kf2");
1598	    return !!env?.get(KF2_WORKSHOP_ENV);
1599	  });
1600	  const edited: ModResult = await withSftp(server, async (conn, sftp) => {
1601	    const unit = await resolveUnit(conn, "kf2");
1602	    const stop = await execRemote(conn, unit ? `systemctl stop '${shq(unit)}'` : "docker stop kf2");
1603	    if (stop.code !== 0) return { ok: false, error: "Could not stop the server to update its Workshop list." };
1604	    const current = await sftpRead(sftp, KF2_INI);
1605	    if (current == null) {
1606	      await execRemote(conn, unit ? `systemctl start '${shq(unit)}'` : "docker start kf2");
1607	      return { ok: false, error: "Couldn't find this server's LinuxServer-KFEngine.ini — start it once, then try again." };
1608	    }
1609	    await sftpWrite(sftp, KF2_INI, updateKf2Ini(current, clean));
1610	    if (!envSet) {
1611	      const start = await execRemote(conn, unit ? `systemctl start '${shq(unit)}'` : "docker start kf2");
1612	      if (start.code !== 0) return { ok: false, error: "The Workshop list was updated, but the server didn't start again — start it from the dashboard." };
1613	    }
1614	    return { ok: true };
1615	  });
1616	  if (!edited.ok || !envSet) return edited;
1617	  return setContainerEnv(server, "kf2", "kf2", KF2_WORKSHOP_ENV, "");
1618	}
