1620	// --- Steam Workshop: fetch one item with the game container's OWN steamcmd ---
1621	//
1622	// For families whose dedicated server does not download Workshop content by
1623	// itself, the item is fetched the way the existing L4D2/Empyrion/PZ paths do
1624	// it: Valve's own `steamcmd`, run INSIDE the customer's own game container
1625	// (every image below ships one), anonymously, into a staging folder on one
1626	// of the container's bind mounts so the host can see the result. Nothing is
1627	// downloaded to, or served from, Nxeon's own infrastructure. Anonymous
1628	// workshop_download_item was confirmed to work for each of these appids by a
1629	// real run on a test VM (2026-09-30): 602960 (Barotrauma), 1169040
1630	// (Necesse), 4000 (Garry's Mod), 440900 (Conan), 544550 (Stationeers).
1631	
1632	async function fetchWorkshopItem(
1633	  conn: Client,
1634	  o: { container: string; user?: string; steamcmd: string; appid: number; id: string; stageInContainer: string; stageOnHost: string }
1635	): Promise<{ hostPath: string } | { error: string }> {
1636	  if (!isWorkshopId(o.id)) return { error: "Not a valid Steam Workshop id." };
1637	  await execRemote(conn, `mkdir -p '${shq(o.stageOnHost)}' && chmod 777 '${shq(o.stageOnHost)}'`);
1638	  const run = await execRemote(
1639	    conn,
1640	    `docker exec ${o.user ? `-u ${o.user} ` : ""}${o.container} ${o.steamcmd} +force_install_dir '${shq(o.stageInContainer)}' ` +
1641	      `+login anonymous +workshop_download_item ${o.appid} ${o.id} +quit 2>&1 | tr -d '\\r' | grep -E 'Success\\. Downloaded item|ERROR' | tail -2`,
1642	    // A large Workshop item (content packs run to hundreds of MB) can outlast
1643	    // the 200s default meant for small single-file downloads.
1644	    15 * 60_000
1645	  );
1646	  const hostPath = `${o.stageOnHost}/steamapps/workshop/content/${o.appid}/${o.id}`;
1647	  const exists = await execRemote(conn, `[ -d '${shq(hostPath)}' ] && [ -n "$(ls -A '${shq(hostPath)}')" ] && echo YES`);
1648	  if (exists.stdout.trim() !== "YES") {
1649	    const why = run.stdout.trim().split(/\r?\n/).pop() ?? "";
1650	    return { error: `Steam Workshop item ${o.id} could not be downloaded${/ERROR/.test(why) ? ` (${why.replace(/^.*ERROR!?\s*/, "")})` : ""} — it may be private, removed, or not for this game.` };
1651	  }
1652	  return { hostPath };
1653	}
