1655	// --- Garry's Mod — Steam Workshop addons, extracted into garrysmod/addons ---
1656	//
1657	// ghcr.io/ich777/steamcmd:garrysmod (github.com/ich777/docker-steamcmd-server,
1658	// `garrysmod` branch): serverfiles at /serverdata/serverfiles (= host
1659	// /opt/gmod), steamcmd at /serverdata/steamcmd/steamcmd.sh (inside the
1660	// container only), server runs as user `steam`.
1661	//
1662	// VERIFIED LIVE 2026-09-30 on a real test server — including one wrong turn
1663	// worth recording: a dedicated server does NOT mount a packed `.gma` dropped
1664	// into garrysmod/addons (ULib/ULX placed that way never ran — no data/ulib or
1665	// data/ulx appeared). Each addon is therefore unpacked with gmad_linux —
1666	// Facepunch's own addon tool, which ships in the server install at
1667	// bin/gmad_linux — into its own addons/nxw-<id>/ folder, the "legacy addon"
1668	// layout the server does load. `resource.AddWorkshop` (Garry's Mod's
1669	// documented API) then makes joining clients fetch the same addon from Steam.
1670	// `+host_workshop_collection` was considered and rejected: it only takes a
1671	// COLLECTION id, and the catalogue is individual addons.
1672	const GMOD_ROOT = "/opt/gmod/garrysmod";
1673	const GMOD_HOST = "/opt/gmod";
1674	const GMOD_CONTAINER = "/serverdata/serverfiles";
1675	
1676	async function applyGmodWorkshop(server: SshServer, ids: string[]): Promise<ModResult> {
1677	  const wanted = ids.filter(isWorkshopId);
1678	  return withSftp(server, async (conn, sftp) => {
1679	    const root = await execRemote(conn, `[ -d '${GMOD_ROOT}' ] && [ -x '${GMOD_HOST}/bin/gmad_linux' ] && echo YES`);
1680	    if (root.stdout.trim() !== "YES") return { ok: false, error: "Couldn't find this server's garrysmod folder — is the server fully set up?" };
1681	    await execRemote(conn, `mkdir -p '${GMOD_ROOT}/addons' '${GMOD_ROOT}/lua/autorun/server'`);
1682	    for (const id of wanted) {
1683	      const have = await execRemote(conn, `[ -d '${GMOD_ROOT}/addons/nxw-${id}' ] && [ -n "$(ls -A '${GMOD_ROOT}/addons/nxw-${id}')" ] && echo YES`);
1684	      if (have.stdout.trim() === "YES") continue;
1685	      const got = await fetchWorkshopItem(conn, {
1686	        container: "gmod",
1687	        user: "steam",
1688	        steamcmd: "/serverdata/steamcmd/steamcmd.sh",
1689	        appid: WORKSHOP_APPID.gmod,
1690	        id,
1691	        stageInContainer: `${GMOD_CONTAINER}/.nxw-workshop`,
1692	        stageOnHost: `${GMOD_HOST}/.nxw-workshop`,
1693	      });
1694	      if ("error" in got) return { ok: false, error: got.error };
1695	      // Current uploads arrive as a plain .gma; older ones as an
1696	      // LZMA-compressed `*_legacy.bin` of the same .gma — unpack that with xz.
1697	      const gma = `${GMOD_HOST}/.nxw-workshop/nxw-${id}.gma`;
1698	      const prep = await execRemote(
1699	        conn,
1700	        `d='${shq(got.hostPath)}'; out='${gma}'; ` +
1701	          `g=$(find "$d" -maxdepth 2 -type f -iname '*.gma' | head -1); b=$(find "$d" -maxdepth 2 -type f -iname '*.bin' | head -1); ` +
1702	          `if [ -n "$g" ]; then cp -f "$g" "$out"; elif [ -n "$b" ]; then xz --format=lzma -dc "$b" > "$out" || rm -f "$out"; fi; ` +
1703	          `[ -s "$out" ] && head -c 4 "$out" | grep -q GMAD && chmod 666 "$out" && echo NXOK || echo NXBAD`
1704	      );
1705	      if (!/NXOK/.test(prep.stdout)) return { ok: false, error: `Steam Workshop item ${id} downloaded, but it isn't a Garry's Mod addon file.` };
1706	      const dest = `${GMOD_ROOT}/addons/nxw-${id}`;
1707	      const extract = await execRemote(
1708	        conn,
1709	        `rm -rf '${dest}'; docker exec -u steam gmod ${GMOD_CONTAINER}/bin/gmad_linux extract ` +
1710	          `-file '${GMOD_CONTAINER}/.nxw-workshop/nxw-${id}.gma' -out '${GMOD_CONTAINER}/garrysmod/addons/nxw-${id}' >/dev/null 2>&1; ` +
1711	          `[ -d '${dest}' ] && [ -n "$(ls -A '${dest}')" ] && echo NXOK || { rm -rf '${dest}'; echo NXBAD; }`
1712	      );
1713	      if (!/NXOK/.test(extract.stdout)) return { ok: false, error: `Couldn't unpack Steam Workshop addon ${id} on the server.` };
1714	    }
1715	    // Drop addons that are no longer wanted (and any packed .gma an earlier
1716	    // build of this installer may have left behind).
1717	    const present = await execRemote(conn, `ls '${GMOD_ROOT}/addons/' 2>/dev/null | sed -n 's/^nxw-\\([0-9]*\\)\\(\\.gma\\)\\{0,1\\}$/\\1/p' | sort -u`);
1718	    for (const id of present.stdout.split(/\r?\n/).map((x) => x.trim()).filter(Boolean)) {
1719	      if (!wanted.includes(id)) await execRemote(conn, `rm -rf '${GMOD_ROOT}/addons/nxw-${id}' '${GMOD_ROOT}/addons/nxw-${id}.gma'`);
1720	    }
1721	    await execRemote(conn, `rm -f '${GMOD_ROOT}'/addons/nxw-*.gma`);
1722	    await sftpWrite(sftp, `${GMOD_ROOT}/lua/autorun/server/nxeon_workshop.lua`, gmodWorkshopLua(wanted));
1723	    await execRemote(conn, `rm -rf '${GMOD_HOST}/.nxw-workshop'; chown -R --reference='${GMOD_ROOT}' '${GMOD_ROOT}/addons' '${GMOD_ROOT}/lua/autorun/server' 2>/dev/null; true`);
1724	    if (!(await restartGame(conn, "gmod", "gmod"))) {
1725	      return { ok: false, error: "The addon was placed, but the server didn't restart — restart it from the dashboard to load it." };
1726	    }
1727	    return { ok: true };
1728	  });
1729	}
