1832	async function ficsitMod(ref: string): Promise<{ name: string; versions: FicsitVersion[] } | null> {
1833	  const query = `query($ref: ModReference!) { getModByReference(modReference: $ref) { name versions(filter: { limit: 60, order_by: created_at, order: desc }) { version stability game_version targets { targetName link size } dependencies { mod_reference condition optional } } } }`;
1834	  try {
1835	    const res = await fetch(`${FICSIT_API}/v2/query`, {
1836	      method: "POST",
1837	      headers: { "Content-Type": "application/json", "User-Agent": "Nxeon/1.0 (mod-manager)" },
1838	      body: JSON.stringify({ query, variables: { ref } }),
1839	    });
1840	    if (!res.ok) return null;
1841	    const body = (await res.json()) as { data?: { getModByReference?: { name: string; versions: FicsitVersion[] } | null } };
1842	    return body.data?.getModByReference ?? null;
1843	  } catch (e) {
1844	    console.error(`[game-mods] ficsit lookup ${ref} failed`, e);
1845	    return null;
1846	  }
