      await keyClient.connect({
        host: target.host,
        port: target.port,
        username: "root",
        privateKey,
        readyTimeout: CONNECT_TIMEOUT_MS,
      });
      connected = true;
    } catch (e) {
      if (!password) throw e;
    }
    if (connected) {
      try {
        return await fn(keyClient);
      } finally {
        try {
          await keyClient.end();
        } catch {
          /* best-effort close */
        }
      }
    }
  }

