/**
 * Pure (no I/O, no Prisma) helpers for worker/game-mods.ts's 2026-09-30
 * family-coverage pass. Kept in their own module so test/*.test.ts can
 * exercise the exact code the worker runs without opening a database
 * connection or an SSH session — every function here is what decides WHAT
 * gets written to a customer's server, so it is the part worth pinning down
 * with tests.
 */

// ---------------------------------------------------------------------------
// Vintage Story — ModDB release selection
// ---------------------------------------------------------------------------

/** The subset of a ModDB `/api/mod/{id}` release we use (real field names,
 *  read live from mods.vintagestory.at 2026-09-30). */
export type VsRelease = {
  mainfile: string;
  filename: string;
  modidstr: string;
  modversion: string;
  tags: string[];
  created: string;
};

/**
 * Pick the release to install for a server running `gameVersion` (e.g.
 * "1.22.7"). The ModDB tags every release with the game versions its author
 * says it supports:
 *
 *  1. a release tagged with this EXACT version wins;
 *  2. otherwise the newest release tagged for the same major.minor line
 *     ("1.22.x") — authors routinely lag a patch release or two behind, and
 *     the game itself only enforces modinfo's `game` dependency as a MINIMUM
 *     version, so a 1.22.6 build is what players of 1.22.7 actually run. The
 *     installer then confirms from the server's own log that the mod really
 *     loaded, so a genuinely incompatible pick is reported as a failure
 *     rather than trusted;
 *  3. never a release for a different minor line (1.21 content on 1.22 is
 *     a different API) — no match means nothing is installed, and the caller
 *     says so.
 *
 * Within a tier it prefers stable releases (a `modversion` without a
 * pre-release suffix like "2.0.0-pre.8"), newest first.
 */
export function pickVsRelease(releases: VsRelease[], gameVersion: string): VsRelease | null {
  const v = gameVersion.replace(/^v/i, "").trim();
  const mm = /^(\d+\.\d+)\./.exec(v)?.[1] ?? null;
  const newestFirst = (rs: VsRelease[]) =>
    rs.filter((r) => !!r.mainfile && Array.isArray(r.tags)).sort((a, b) => (a.created < b.created ? 1 : a.created > b.created ? -1 : 0));
  const prefer = (rs: VsRelease[]) => rs.find((r) => !/-/.test(r.modversion)) ?? rs[0] ?? null;
  const exact = newestFirst(releases.filter((r) => r.tags?.includes(v)));
  if (exact.length) return prefer(exact);
  if (!mm) return null;
  const sameLine = newestFirst(releases.filter((r) => r.tags?.some((t) => t.startsWith(`${mm}.`) && !/-/.test(t))));
  return prefer(sameLine);
}

