/**
 * Path safety for the mod installer. Every path that reaches a customer's
 * server — an entry inside a downloaded archive, a filename an upstream API
 * hands us, a path inside a Modrinth modpack index — goes through here first.
 *
 * The rule is an ALLOWLIST, not a blocklist: a segment is accepted only if it
 * is made of characters that are inert in a shell (even though we quote
 * everything anyway), cannot be an option (`-rf`), cannot climb (`..`), and
 * cannot be absolute. Anything else rejects the WHOLE package rather than
 * being "cleaned" — a silently renamed file is a file the mod can't find, and
 * an archive that ships `../../etc/cron.d/x` is not a mod we want anyway.
 */

/** One path segment: no leading dash/dot-dot, printable, shell-inert set. */
const SEGMENT = /^[A-Za-z0-9_+@\[\]()][A-Za-z0-9 ._+@\[\]()~#&=!,-]{0,254}$/;
const MAX_REL_LEN = 1024;

export function isSafeSegment(s: string): boolean {
  if (!s || s === "." || s === "..") return false;
  if (s.endsWith(" ") || s.endsWith(".")) return false; // ambiguous on Windows-built archives, and never needed
  return SEGMENT.test(s);
}

/**
 * Normalize an archive entry name to safe relative segments, or null when it
 * must be refused. Accepts Windows separators (many mod zips are built on
 * Windows) and a leading "./"; refuses absolute paths, drive letters, `..`,
 * NUL, empty middle segments and anything outside the segment allowlist.
 */
export function normalizeRel(name: string): string[] | null {
  if (typeof name !== "string" || name.length === 0 || name.length > MAX_REL_LEN) return null;
  if (name.includes("\0")) return null;
  let n = name.replace(/\\/g, "/");
  if (n.startsWith("/") || /^[A-Za-z]:/.test(n)) return null;
  while (n.startsWith("./")) n = n.slice(2);
  if (n.endsWith("/")) n = n.slice(0, -1);
  if (!n) return null;
  const parts = n.split("/");
  for (const p of parts) if (!isSafeSegment(p)) return null;
  return parts;
}

/** An absolute guest path we generated ourselves (base dirs). */
export function isSafeAbs(p: string): boolean {
  if (!p.startsWith("/") || p.length > 2048) return false;
  if (p === "/") return false;
  const parts = p.slice(1).split("/");
  return parts.every(isSafeSegment);
}

/** Join safe relative segments under an absolute base, re-checking containment. */
export function joinUnder(base: string, rel: string[] | string): string {
  if (!isSafeAbs(base)) throw new Error(`unsafe base path: ${base}`);
  const segs = typeof rel === "string" ? normalizeRel(rel) : rel;
  if (!segs || segs.length === 0 || !segs.every(isSafeSegment)) throw new Error("unsafe relative path");
  const out = `${base.replace(/\/+$/, "")}/${segs.join("/")}`;
  if (!out.startsWith(base.replace(/\/+$/, "") + "/")) throw new Error("path escapes its base");
  return out;
}

/** True when `p` is `dir` itself or inside it (both absolute, normalized). */
export function isWithin(dir: string, p: string): boolean {
  const d = dir.replace(/\/+$/, "");
  return p === d || p.startsWith(d + "/");
}

