/**
 * Minimal, defensive archive readers for mod packages (ZIP and tar/tar.gz).
 *
 * Written here rather than pulled from npm because the parts that matter —
 * what we REFUSE — are the whole point, and they are small enough to read in
 * one sitting:
 *
 *  - path traversal / zip-slip: every entry name goes through
 *    lib/mods/paths.ts `normalizeRel` (no `..`, no absolute, no drive letters,
 *    shell-inert characters only). One bad entry rejects the archive.
 *  - symlinks and hard links: rejected outright (a ZIP entry whose Unix mode
 *    says S_IFLNK, a tar typeflag 1/2). A link inside a mod is how an archive
 *    that looks harmless writes outside its folder on the second extraction.
 *  - zip bombs: entry-count cap, per-entry and total uncompressed caps, and
 *    a compression-ratio cap; zlib is also told the maximum output size so a
 *    lying header cannot make it allocate more.
 *  - integrity: CRC-32 of every ZIP entry is checked against its header.
 *  - encrypted entries, ZIP64 and compression methods other than
 *    store/deflate are refused rather than half-supported. Real mod packages
 *    (Modrinth jars/zips/mrpacks, Thunderstore packages, uMod, GitHub
 *    release zips, Factorio mods) are all plain deflate ZIPs under 4 GB.
 *
 * Nothing here touches the filesystem: it turns bytes into a list of
 * {path segments, data} that the caller places through a GuestFs.
 */
import { crc32, gunzipSync, inflateRawSync } from "node:zlib";
import { normalizeRel } from "./paths";

export type ArchiveEntry = { path: string[]; dir: boolean; data: Buffer };

export type ArchiveLimits = {
  maxEntries: number;
  maxEntryBytes: number;
  maxTotalBytes: number;
  /** uncompressed/compressed ratio above which an entry > 1 MB is refused */
  maxRatio: number;
};

export const DEFAULT_LIMITS: ArchiveLimits = {
  maxEntries: 20_000,
  maxEntryBytes: 256 * 1024 * 1024,
  maxTotalBytes: 768 * 1024 * 1024,
  maxRatio: 250,
};

export class ArchiveError extends Error {}

const u16 = (b: Buffer, o: number) => b.readUInt16LE(o);
const u32 = (b: Buffer, o: number) => b.readUInt32LE(o);

export function isZip(buf: Buffer): boolean {
  return buf.length >= 4 && u32(buf, 0) === 0x04034b50;
}
export function isGzip(buf: Buffer): boolean {
  return buf.length >= 2 && buf[0] === 0x1f && buf[1] === 0x8b;
}

/** Read every entry of a ZIP. Throws ArchiveError on anything unsafe or malformed. */
export function readZip(buf: Buffer, limits: ArchiveLimits = DEFAULT_LIMITS): ArchiveEntry[] {
  // End of central directory: last 22..65557 bytes.
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
    if (u32(buf, i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new ArchiveError("not a ZIP archive (no end-of-central-directory record)");
  const total = u16(buf, eocd + 10);
  const cdSize = u32(buf, eocd + 12);
  const cdOff = u32(buf, eocd + 16);
  if (total === 0xffff || cdOff === 0xffffffff || cdSize === 0xffffffff) throw new ArchiveError("ZIP64 archives are not supported");
  if (total > limits.maxEntries) throw new ArchiveError(`archive has too many entries (${total})`);
  if (cdOff + cdSize > buf.length) throw new ArchiveError("truncated ZIP central directory");

  const out: ArchiveEntry[] = [];
  const seen = new Set<string>();
  let sum = 0;
  let p = cdOff;
  for (let n = 0; n < total; n++) {
    if (p + 46 > buf.length || u32(buf, p) !== 0x02014b50) throw new ArchiveError("corrupt ZIP central directory");
    const madeBy = u16(buf, p + 4);
    const flags = u16(buf, p + 8);
    const method = u16(buf, p + 10);
    const crc = u32(buf, p + 16);
    const csize = u32(buf, p + 20);
    const usize = u32(buf, p + 24);
    const nlen = u16(buf, p + 28);
    const xlen = u16(buf, p + 30);
    const clen = u16(buf, p + 32);
    const ext = u32(buf, p + 38);
    const lho = u32(buf, p + 42);
    const rawName = buf.subarray(p + 46, p + 46 + nlen).toString((flags & 0x800) ? "utf8" : "latin1");
    p += 46 + nlen + xlen + clen;

    if (flags & 0x1) throw new ArchiveError(`encrypted entry: ${rawName}`);
    if (csize === 0xffffffff || usize === 0xffffffff || lho === 0xffffffff) throw new ArchiveError("ZIP64 entries are not supported");
    const hostOs = madeBy >> 8;
    const unixMode = (ext >>> 16) & 0xffff;
    if (hostOs === 3 && (unixMode & 0o170000) === 0o120000) throw new ArchiveError(`symlink in archive: ${rawName}`);

    const isDir = rawName.endsWith("/") || rawName.endsWith("\\");
    const segs = normalizeRel(rawName);
    if (!segs) {
      // A bare "/" or "./" directory record is harmless noise; anything else is refused.
      if (isDir && /^[./\\]*$/.test(rawName)) continue;
      throw new ArchiveError(`unsafe path in archive: ${JSON.stringify(rawName).slice(0, 120)}`);
    }
    const key = segs.join("/");
    if (isDir) { out.push({ path: segs, dir: true, data: Buffer.alloc(0) }); continue; }
    if (seen.has(key)) throw new ArchiveError(`duplicate entry: ${key}`);
    seen.add(key);

    if (usize > limits.maxEntryBytes) throw new ArchiveError(`entry too large: ${key}`);
    sum += usize;
    if (sum > limits.maxTotalBytes) throw new ArchiveError("archive expands beyond the size limit");
    if (usize > 1024 * 1024 && csize > 0 && usize / csize > limits.maxRatio) throw new ArchiveError(`suspicious compression ratio: ${key}`);

    if (lho + 30 > buf.length || u32(buf, lho) !== 0x04034b50) throw new ArchiveError(`corrupt local header: ${key}`);
    const dataStart = lho + 30 + u16(buf, lho + 26) + u16(buf, lho + 28);
    if (dataStart + csize > buf.length) throw new ArchiveError(`truncated entry: ${key}`);
    const comp = buf.subarray(dataStart, dataStart + csize);
    let data: Buffer;
    if (method === 0) {
      if (csize !== usize) throw new ArchiveError(`bad stored entry size: ${key}`);
      data = Buffer.from(comp);
    } else if (method === 8) {
      try {
        data = usize === 0 ? Buffer.alloc(0) : inflateRawSync(comp, { maxOutputLength: usize });
      } catch {
        throw new ArchiveError(`could not inflate: ${key}`);
      }
    } else {
      throw new ArchiveError(`unsupported compression method ${method}: ${key}`);
    }
    if (data.length !== usize) throw new ArchiveError(`size mismatch: ${key}`);
    if ((crc32(data) >>> 0) !== crc) throw new ArchiveError(`CRC mismatch: ${key}`);
    out.push({ path: segs, dir: false, data });
  }
  return out;
}

/** Read a tar (optionally gzip-compressed). Regular files and dirs only. */
export function readTar(input: Buffer, limits: ArchiveLimits = DEFAULT_LIMITS): ArchiveEntry[] {
  let buf = input;
  if (isGzip(input)) {
    try {
      buf = gunzipSync(input, { maxOutputLength: limits.maxTotalBytes + 1024 * 1024 });
    } catch {
      throw new ArchiveError("could not decompress gzip (corrupt or larger than the size limit)");
    }
  }
  const out: ArchiveEntry[] = [];
  const seen = new Set<string>();
  let off = 0;
  let sum = 0;
  let longName: string | null = null;
  let paxPath: string | null = null;
  const str = (o: number, l: number) => {
    const s = buf.subarray(o, o + l);
    const z = s.indexOf(0);
    return (z >= 0 ? s.subarray(0, z) : s).toString("utf8");
  };
  while (off + 512 <= buf.length) {
    const hdr = buf.subarray(off, off + 512);
    if (hdr.every((b) => b === 0)) break;
    const sizeField = str(off + 124, 12).trim();
    const size = parseInt(sizeField || "0", 8);
    if (!Number.isFinite(size) || size < 0) throw new ArchiveError("corrupt tar header");
    const type = String.fromCharCode(buf[off + 156] || 48);
    const prefix = str(off + 345, 155);
    let name = longName ?? paxPath ?? (prefix ? `${prefix}/${str(off, 100)}` : str(off, 100));
    const dataStart = off + 512;
    const next = dataStart + Math.ceil(size / 512) * 512;
    if (dataStart + size > buf.length) throw new ArchiveError("truncated tar entry");
    const data = buf.subarray(dataStart, dataStart + size);
    off = next;

    if (type === "L") { longName = data.toString("utf8").replace(/\0+$/, ""); continue; }
    if (type === "x") {
      const m = /(?:^|\n)\d+ path=([^\n]*)\n/.exec(data.toString("utf8"));
      paxPath = m ? m[1] : null;
      continue;
    }
    if (type === "g") continue; // global pax header: metadata only
    longName = null;
    paxPath = null;
    if (type === "1" || type === "2") throw new ArchiveError(`link in archive: ${name}`);
    if (type !== "0" && type !== "\0" && type !== "5" && type !== "7") throw new ArchiveError(`unsupported tar entry type '${type}': ${name}`);
    const isDir = type === "5" || name.endsWith("/");
    const segs = normalizeRel(name);
    if (!segs) {
      if (isDir && /^[./]*$/.test(name)) continue;
      throw new ArchiveError(`unsafe path in archive: ${JSON.stringify(name).slice(0, 120)}`);
    }
    if (isDir) { out.push({ path: segs, dir: true, data: Buffer.alloc(0) }); continue; }
    const key = segs.join("/");
    if (seen.has(key)) throw new ArchiveError(`duplicate entry: ${key}`);
    seen.add(key);
    if (out.length >= limits.maxEntries) throw new ArchiveError("archive has too many entries");
    if (size > limits.maxEntryBytes) throw new ArchiveError(`entry too large: ${key}`);
    sum += size;
    if (sum > limits.maxTotalBytes) throw new ArchiveError("archive expands beyond the size limit");
    name = key;
    out.push({ path: segs, dir: false, data: Buffer.from(data) });
  }
  return out;
}

/** Read whichever archive format the bytes are. */
export function readArchive(buf: Buffer, limits: ArchiveLimits = DEFAULT_LIMITS): ArchiveEntry[] {
  if (isZip(buf)) return readZip(buf, limits);
  return readTar(buf, limits);
}

/** Files only, as "a/b/c" → data. */
export function fileMap(entries: ArchiveEntry[]): Map<string, Buffer> {
  const m = new Map<string, Buffer>();
  for (const e of entries) if (!e.dir) m.set(e.path.join("/"), e.data);
  return m;
}

