/**
 * NX Labs local mirror lookup.
 *
 * The mirror itself (ingestion, storage, eviction, licence gating) belongs to
 * the catalogue side (K2's `ModVersion.mirrorState/mirrorPath/mirrorSha256`
 * columns under NXLABS_MIRROR_DIR). This module only READS it, and does so
 * defensively so it works before and after that schema lands:
 *
 *  - raw SQL against "ModVersion" guarded by `to_regclass` — no Prisma model
 *    import, so this compiles and runs on a database that doesn't have the
 *    table yet (it simply finds nothing);
 *  - the stored relative path must stay inside NXLABS_MIRROR_DIR;
 *  - the mirrored bytes are re-hashed here and must match BOTH the mirror's own
 *    sha256 and every hash the upstream API published for the file. A copy
 *    that fails any check is ignored and the engine falls back to upstream.
 */
import { promises as fsp } from "node:fs";
import path from "node:path";
import { hashAll, type Hashes } from "./safe-fetch";
import type { RemoteFile } from "./types";

export type MirrorLookup = (file: RemoteFile) => Promise<Buffer | null>;

type Row = { mirrorPath: string | null; mirrorSha256: string | null };

export function mirrorPathInside(dir: string, rel: string): string | null {
  if (!dir || !rel || rel.includes("\0") || path.isAbsolute(rel)) return null;
  const root = path.resolve(dir);
  const full = path.resolve(root, rel);
  return full.startsWith(root + path.sep) ? full : null;
}

export function matchesAll(bytes: Buffer, expect: Hashes, mirrorSha256: string | null): boolean {
  const h = hashAll(bytes);
  if (mirrorSha256 && mirrorSha256.toLowerCase() !== h.sha256) return false;
  for (const k of ["sha1", "sha256", "sha512"] as const) {
    const want = expect[k];
    if (want && want.toLowerCase() !== h[k]) return false;
  }
  // Refuse a mirror hit we cannot verify against anything at all.
  return !!(mirrorSha256 || expect.sha1 || expect.sha256 || expect.sha512);
}

/** The production lookup. `query` is injected so this module never imports Prisma itself. */
export function dbMirrorLookup(query: (sql: string, ...args: unknown[]) => Promise<unknown>): MirrorLookup {
  let tableKnown: boolean | null = null;
  return async (file) => {
    const dir = process.env.NXLABS_MIRROR_DIR;
    const key = file.mirrorKey;
    if (!dir || !key || !key.versionId) return null;
    try {
      if (tableKnown === null) {
        const r = (await query(`SELECT to_regclass('"ModVersion"') IS NOT NULL AS ok`)) as { ok: boolean }[];
        tableKnown = !!r?.[0]?.ok;
      }
      if (!tableKnown) return null;
      const rows = (await query(
        `SELECT mv."mirrorPath", mv."mirrorSha256" FROM "ModVersion" mv JOIN "GameMod" g ON g.id = mv."gameModId"
          WHERE g.source = $1 AND mv."versionId" = $2 AND mv."mirrorState" = 'OK' LIMIT 1`,
        key.source,
        key.versionId,
      )) as Row[];
      const row = rows?.[0];
      if (!row?.mirrorPath) return null;
      const full = mirrorPathInside(dir, row.mirrorPath);
      if (!full) return null;
      const st = await fsp.lstat(full).catch(() => null);
      if (!st || !st.isFile() || st.size > 1024 * 1024 * 1024) return null;
      const bytes = await fsp.readFile(full);
      return matchesAll(bytes, file.hashes, row.mirrorSha256) ? bytes : null;
    } catch (e) {
      console.error("[mods] mirror lookup failed — falling back to upstream", e instanceof Error ? e.message : e);
      return null;
    }
  };
}

