/**
 * The install engine every lib/mods/installers/* family shares.
 *
 * It owns everything that must be the same for every game: the per-server
 * state file on the guest, dependency reference counting, conflict
 * detection, backups, staged writes with rollback, idempotent re-runs, and
 * enable/disable/update/uninstall. Installers only answer "where", "which
 * build" and "which files".
 *
 * STATE lives ON THE GUEST at /root/.nxeon-mods/state.json, not in our DB:
 * it is the record of which files Nxeon itself put on that disk, so it has to
 * travel with the disk (a restored backup, a customer who deleted things by
 * hand). The DB's ServerMod row stays the customer-facing desired state; the
 * worker reconciles the two. Nothing outside the state file is ever deleted.
 *
 * Concurrency: the worker never runs two jobs for the same server at once
 * (worker/index.ts lock key = serverId) and the portal refuses to queue a
 * second while one is in flight, so the state file has a single writer.
 */
import { createHash } from "node:crypto";
import type { GuestFs } from "./guest-fs";
import { isWithin } from "./paths";
import { FetchError, type Fetcher } from "./safe-fetch";
import type { MirrorLookup } from "./mirror";
import type { CatalogFacts, FamilyInstaller, InstallerCtx, Layout, OpResult, PlacedFile, ResolvedPackage, ServerFacts } from "./types";

export const STATE_DIR = "/root/.nxeon-mods";
export const STATE_PATH = `${STATE_DIR}/state.json`;
const BACKUP_DIR = `${STATE_DIR}/backups`;
const DISABLED_DIR = `${STATE_DIR}/disabled`;
const KEEP_BACKUPS = 5;
/** Ceiling on what one operation may download in total (all packages). */
export const MAX_OP_BYTES = 512 * 1024 * 1024;
/** Ceiling on a single downloaded file. */
export const MAX_FILE_BYTES = 256 * 1024 * 1024;

export type FileRec = { path: string; sha256: string; size: number };
export type PkgState = {
  key: string;
  name: string;
  version: string;
  versionId: string | null;
  files: FileRec[];
  /** GameMod ids that need this package (directly, or as a dependency). */
  roots: string[];
  requires: string[];
  incompatible: { key: string; name: string }[];
  disabled: boolean;
  installedAt: string;
  updatedAt: string;
};
export type GuestState = {
  v: 1;
  family: string;
  packages: Record<string, PkgState>;
  /** GameMod id → the package key it installed as. */
  roots: Record<string, { key: string; name: string }>;
};

export function emptyState(family: string): GuestState {
  return { v: 1, family, packages: {}, roots: {} };
}

export async function loadState(fs: GuestFs, family: string): Promise<GuestState> {
  const raw = await fs.readFile(STATE_PATH, 8 * 1024 * 1024);
  if (!raw) return emptyState(family);
  try {
    const s = JSON.parse(raw.toString("utf8")) as GuestState;
    if (s && s.v === 1 && s.packages && s.roots) return s;
  } catch {
    /* fall through */
  }
  throw new Error("This server's mod state file (/root/.nxeon-mods/state.json) is unreadable — nothing was changed. Contact support.");
}

async function saveState(fs: GuestFs, s: GuestState): Promise<void> {
  const tmp = `${STATE_PATH}.nxeon-part`;
  await fs.writeFile(tmp, Buffer.from(JSON.stringify(s, null, 2) + "\n"));
  await fs.rename(tmp, STATE_PATH);
}

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const stamp = (d: Date) => d.toISOString().replace(/[:.]/g, "-");
const safeKey = (k: string) => k.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 120);

/** Which package (other than `exceptKey`) claims `path`. */
export function ownerOf(s: GuestState, path: string, exceptKey?: string): PkgState | null {
  for (const p of Object.values(s.packages)) {
    if (p.key === exceptKey) continue;
    if (p.files.some((f) => f.path === path)) return p;
  }
  return null;
}

export type EngineDeps = {
  fs: GuestFs;
  fetcher: Fetcher;
  mirror?: MirrorLookup | null;
  now?: () => Date;
  /** Progress callback (job step text + percent). */
  progress?: (step: string, pct: number) => void | Promise<void>;
};

async function download(pkg: ResolvedPackage, deps: EngineDeps): Promise<{ bytes: Buffer; from: "mirror" | "upstream" | "prefetched" }> {
  if (pkg.prefetched) return { bytes: pkg.prefetched, from: "prefetched" };
  if (deps.mirror) {
    const hit = await deps.mirror(pkg.file);
    if (hit) return { bytes: hit, from: "mirror" };
  }
  if (pkg.file.size != null && pkg.file.size > MAX_FILE_BYTES) {
    throw new FetchError(`${pkg.name} is ${Math.round(pkg.file.size / 1048576)} MB — over the ${MAX_FILE_BYTES / 1048576} MB one-click limit`, "size");
  }
  const r = await deps.fetcher(pkg.file.url, {
    maxBytes: MAX_FILE_BYTES,
    timeoutMs: 180_000,
    expect: pkg.file.hashes,
    headers: pkg.file.headers,
  });
  return { bytes: r.bytes, from: "upstream" };
}

async function detectOrFail(installer: FamilyInstaller, fs: GuestFs, server: ServerFacts, mod: CatalogFacts | null): Promise<Layout> {
  const det = await installer.detect(fs, server, mod);
  if ("error" in det) throw new UserFacing(det.error);
  return det;
}

/** An error whose message is safe and meant for the customer. */
export class UserFacing extends Error {}

function failure(e: unknown): { ok: false; error: string } {
  if (e instanceof UserFacing) return { ok: false, error: e.message };
  if (e instanceof FetchError) return { ok: false, error: `Download refused: ${e.message}.` };
  const m = e instanceof Error ? e.message : String(e);
  return { ok: false, error: m.length > 300 ? m.slice(0, 300) + "…" : m };
}

async function pruneBackups(fs: GuestFs) {
  const names = (await fs.list(BACKUP_DIR)).filter((n) => /^\d{4}-/.test(n)).sort();
  for (const n of names.slice(0, Math.max(0, names.length - KEEP_BACKUPS))) await fs.remove(`${BACKUP_DIR}/${n}`);
}

/** Copy `paths` (those that exist) into a fresh backup folder. Returns path→backup copy. */
async function backup(fs: GuestFs, label: string, paths: string[], now: Date): Promise<Map<string, string>> {
  const out = new Map<string, string>();
  if (paths.length === 0) return out;
  const dir = `${BACKUP_DIR}/${stamp(now)}-${safeKey(label)}`;
  for (const p of paths) {
    const st = await fs.stat(p);
    if (!st || st.type !== "file") continue;
    const dest = `${dir}${p}`;
    await fs.copy(p, dest);
    out.set(p, dest);
  }
  if (await fs.stat(STATE_PATH)) await fs.copy(STATE_PATH, `${dir}/state.json`);
  await pruneBackups(fs);
  return out;
}

type Write = { pkg: ResolvedPackage; files: PlacedFile[]; prev: PkgState | null };

/**
 * Install (or update) a catalogue mod and its required dependencies.
 * Idempotent: running it again with nothing new upstream changes nothing.
 */
export async function installOrUpdate(
  installer: FamilyInstaller,
  mod: CatalogFacts,
  server: ServerFacts,
  deps: EngineDeps,
  mode: "install" | "update" = "install",
): Promise<OpResult> {
  const fs = deps.fs;
  const now = (deps.now ?? (() => new Date()))();
  try {
    await deps.progress?.("Checking your server", 5);
    const layout = await detectOrFail(installer, fs, server, mod);
    const state = await loadState(fs, server.family);
    const ctx: InstallerCtx = { server, layout, fetcher: deps.fetcher };

    await deps.progress?.(`Resolving ${mod.name} and its dependencies`, 15);
    const res = await installer.resolve(mod, ctx);
    if ("error" in res) return { ok: false, error: res.error };
    const pkgs = res.packages;
    const rootPkg = pkgs[pkgs.length - 1];
    if (!rootPkg || !rootPkg.root) return { ok: false, error: "Resolver returned no package for this mod." };

    // A disabled mod is enabled again, not reinstalled behind the customer's back.
    const prevRoot = state.roots[mod.id];
    if (prevRoot && state.packages[prevRoot.key]?.disabled && mode === "install") {
      return { ok: false, error: `${mod.name} is installed but disabled — enable it instead.` };
    }

    // ── declared incompatibilities, both directions ─────────────────────────
    const incoming = new Set(pkgs.map((p) => p.key));
    for (const p of pkgs) {
      for (const bad of p.incompatible) {
        const have = state.packages[bad.key];
        if (have && !have.disabled && !incoming.has(bad.key)) {
          return { ok: false, error: `${p.name} is incompatible with ${have.name}, which is installed — remove ${have.name} first.` };
        }
      }
    }
    for (const have of Object.values(state.packages)) {
      if (have.disabled) continue;
      const clash = have.incompatible.find((b) => incoming.has(b.key));
      if (clash) return { ok: false, error: `${have.name} (installed) declares it is incompatible with ${clash.name} — nothing was installed.` };
    }

    // ── download + place, nothing written yet ───────────────────────────────
    const writes: Write[] = [];
    const notes = [...res.notes];
    let total = 0;
    let i = 0;
    for (const pkg of pkgs) {
      i++;
      const prev = state.packages[pkg.key] ?? null;
      if (prev && prev.version === pkg.version && (await filesIntact(fs, prev))) continue; // already there — idempotent
      await deps.progress?.(`Downloading ${pkg.name} ${pkg.version}`, 15 + Math.round((60 * i) / pkgs.length));
      const dl = await download(pkg, deps);
      total += dl.bytes.length;
      if (total > MAX_OP_BYTES) return { ok: false, error: `This install would download more than ${MAX_OP_BYTES / 1048576} MB — too large for one click.` };
      const placed = await installer.place(pkg, dl.bytes, ctx);
      if ("error" in placed) return { ok: false, error: placed.error };
      if (placed.length === 0) return { ok: false, error: `${pkg.name} ${pkg.version} contains nothing this server can load.` };
      for (const f of placed) {
        if (!isWithin(layout.base, f.path)) return { ok: false, error: `${pkg.name} tried to write outside the game folder — refused.` };
      }
      if (dl.from === "mirror") notes.push(`${pkg.name} came from the NX Labs mirror (checksum verified).`);
      writes.push({ pkg, files: placed, prev });
    }

    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));

    // ── conflicts against files we don't own ───────────────────────────────
    const overwrite: string[] = [];
    for (const w of writes) {
      const prevPaths = new Set(w.prev?.files.map((f) => f.path) ?? []);
      for (const f of w.files) {
        const other = ownerOf(state, f.path, w.pkg.key);
        if (other) {
          const rec = other.files.find((x) => x.path === f.path)!;
          if (rec.sha256 === sha256(f.data)) continue; // byte-identical shared file — fine
          return { ok: false, error: `${w.pkg.name} would overwrite ${f.path}, which belongs to ${other.name} — nothing was changed.` };
        }
        if (prevPaths.has(f.path) || legacy.includes(f.path)) { overwrite.push(f.path); continue; }
        const st = await fs.stat(f.path);
        if (!st) continue;
        if (st.type === "dir") return { ok: false, error: `${f.path} already exists as a folder — nothing was changed.` };
        if (f.overwrite === "backup") { overwrite.push(f.path); continue; }
        const cur = await fs.readFile(f.path);
        if (cur && sha256(cur) === sha256(f.data)) continue; // same file already there (installed by hand) — adopt it
        return {
          ok: false,
          error: `${f.path} already exists and wasn't installed by Nxeon (added by hand?). Remove or rename it in Files, then try again — nothing was changed.`,
        };
      }
    }

    // Files of the previous version that the new version no longer ships.
    const stale: string[] = [];
    for (const w of writes) {
      if (!w.prev) continue;
      const keep = new Set(w.files.map((f) => f.path));
      for (const f of w.prev.files) if (!keep.has(f.path) && !ownerOf(state, f.path, w.pkg.key)) stale.push(f.path);
    }

    // Nothing to do at all → idempotent success, no restart needed.
    const allEnabled = enabledSet(state);
    if (writes.length === 0 && legacy.length === 0) {
      addRoots(state, pkgs, mod);
      await saveState(fs, state);
      return { ok: true, version: rootPkg.version, restartRequired: false, changed: [], notes: [...notes, `${mod.name} ${rootPkg.version} is already installed and up to date.`] };
    }

    // ── backup, then staged write ───────────────────────────────────────────
    await deps.progress?.("Backing up files that will change", 80);
    const existingLegacy: string[] = [];
    for (const p of legacy) if (await fs.stat(p)) existingLegacy.push(p);
    const backups = await backup(fs, mod.slug, [...overwrite, ...stale, ...existingLegacy], now);

    await deps.progress?.("Writing files to your server", 88);
    const written: string[] = [];
    const created: string[] = [];
    try {
      for (const w of writes) {
        for (const f of w.files) {
          const existed = !!(await fs.stat(f.path));
          const part = `${f.path}.nxeon-part`;
          await fs.writeFile(part, f.data);
          await fs.rename(part, f.path);
          written.push(f.path);
          if (!existed) created.push(f.path);
        }
      }
      for (const p of stale) await fs.remove(p);
      for (const p of existingLegacy) if (!written.includes(p)) await fs.remove(p);

      // State: record exactly what we wrote.
      for (const w of writes) {
        const prev = w.prev;
        state.packages[w.pkg.key] = {
          key: w.pkg.key,
          name: w.pkg.name,
          version: w.pkg.version,
          versionId: w.pkg.versionId ?? null,
          files: w.files.map((f) => ({ path: f.path, sha256: sha256(f.data), size: f.data.length })),
          roots: prev?.roots ?? [],
          requires: w.pkg.requires,
          incompatible: w.pkg.incompatible,
          disabled: false,
          installedAt: prev?.installedAt ?? now.toISOString(),
          updatedAt: now.toISOString(),
        };
      }
      addRoots(state, pkgs, mod);

      if (installer.configure) {
        const edits = await installer.configure(fs, layout, enabledList(state), allList(state));
        for (const e of edits) {
          if (!isWithin(layout.base, e.path)) continue;
          if (!backups.has(e.path) && (await fs.stat(e.path))) await backup(fs, `${mod.slug}-config`, [e.path], now);
          await fs.writeFile(`${e.path}.nxeon-part`, e.data);
          await fs.rename(`${e.path}.nxeon-part`, e.path);
        }
      }
      await saveState(fs, state);
    } catch (e) {
      // Roll back: new files out, overwritten files back from the backup.
      for (const p of created) await fs.remove(p).catch(() => {});
      for (const [orig, copy] of backups) await fs.copy(copy, orig).catch(() => {});
      for (const w of writes) for (const f of w.files) await fs.remove(`${f.path}.nxeon-part`).catch(() => {});
      const why = failure(e).error;
      return { ok: false, error: `Writing to your server failed and the change was rolled back: ${why}` };
    }
    await fs.chownLike(layout.base, [...new Set(written.map((p) => p.split("/").slice(0, -1).join("/")))].filter((d) => isWithin(layout.base, d)));

    const changed = writes.map((w) =>
      w.prev ? `updated ${w.pkg.name} ${w.prev.version} → ${w.pkg.version}` : `${w.pkg.root ? "installed" : "added dependency"} ${w.pkg.name} ${w.pkg.version}`,
    );
    if (existingLegacy.length) changed.push(`replaced ${existingLegacy.length} file(s) from the older Nxeon installer`);
    void allEnabled;
    return { ok: true, version: rootPkg.version, restartRequired: installer.restartRequired, changed, notes };
  } catch (e) {
    return failure(e);
  }
}

async function filesIntact(fs: GuestFs, p: PkgState): Promise<boolean> {
  if (p.disabled) return true;
  for (const f of p.files) {
    const st = await fs.stat(f.path);
    if (!st || st.type !== "file" || st.size !== f.size) return false;
  }
  return p.files.length > 0;
}

function addRoots(state: GuestState, pkgs: ResolvedPackage[], mod: CatalogFacts) {
  const root = pkgs[pkgs.length - 1];
  state.roots[mod.id] = { key: root.key, name: mod.name };
  for (const p of pkgs) {
    const st = state.packages[p.key];
    if (st && !st.roots.includes(mod.id)) st.roots.push(mod.id);
  }
}

function enabledSet(s: GuestState) {
  return new Set(Object.values(s.packages).filter((p) => !p.disabled).map((p) => p.key));
}
function enabledList(s: GuestState) {
  return Object.values(s.packages).filter((p) => !p.disabled).map((p) => ({ key: p.key, name: p.name, version: p.version }));
}
function allList(s: GuestState) {
  return Object.values(s.packages).map((p) => ({ key: p.key, name: p.name }));
}

/** Remove a catalogue mod; dependencies go only when nothing else needs them. */
export async function uninstall(installer: FamilyInstaller, mod: CatalogFacts, server: ServerFacts, deps: EngineDeps): Promise<OpResult> {
  const fs = deps.fs;
  try {
    await deps.progress?.("Checking your server", 10);
    const layout = await detectOrFail(installer, fs, server, mod);
    const state = await loadState(fs, server.family);
    const legacy = (installer.legacyPaths?.(mod, layout) ?? []).filter((p) => isWithin(layout.base, p));
    const removed: string[] = [];

    for (const p of legacy) {
      if (await fs.stat(p)) {
        await fs.remove(p);
        removed.push(p);
      }
    }
    if (!state.roots[mod.id]) {
      return {
        ok: true,
        restartRequired: removed.length > 0 && installer.restartRequired,
        changed: removed.length ? [`removed ${mod.name}`] : [],
        notes: removed.length ? [] : [`${mod.name} wasn't on the server (nothing to remove).`],
      };
    }

    // Is this mod's package something ANOTHER installed mod needs?
    const rootKey = state.roots[mod.id].key;
    const blockers = Object.entries(state.roots)
      .filter(([id, r]) => id !== mod.id && r.key !== rootKey && state.packages[r.key]?.requires.includes(rootKey))
      .map(([, r]) => r.name);
    if (blockers.length) return { ok: false, error: `${blockers.join(", ")} need${blockers.length === 1 ? "s" : ""} ${mod.name} — remove ${blockers.length === 1 ? "it" : "them"} first.` };

    await deps.progress?.(`Removing ${mod.name}`, 50);
    delete state.roots[mod.id];
    const gone: string[] = [];
    for (const p of Object.values(state.packages)) {
      p.roots = p.roots.filter((r) => r !== mod.id);
      // A package another mod still installed as its own root stays.
      const stillRoot = Object.values(state.roots).some((r) => r.key === p.key);
      if (p.roots.length === 0 && !stillRoot) gone.push(p.key);
    }
    for (const key of gone) {
      const p = state.packages[key];
      delete state.packages[key];
      for (const f of p.files) {
        if (ownerOf(state, f.path)) continue; // shared identical file still needed
        const at = p.disabled ? disabledPath(p.key, f.path) : f.path;
        await fs.remove(at);
      }
      if (p.disabled) await fs.remove(`${DISABLED_DIR}/${safeKey(p.key)}`);
      await removeEmptyParents(fs, p.files.map((f) => f.path), layout);
      removed.push(p.name);
    }
    if (installer.configure) {
      for (const e of await installer.configure(fs, layout, enabledList(state), allList(state))) {
        if (!isWithin(layout.base, e.path)) continue;
        await fs.writeFile(`${e.path}.nxeon-part`, e.data);
        await fs.rename(`${e.path}.nxeon-part`, e.path);
      }
    }
    await saveState(fs, state);
    return { ok: true, restartRequired: installer.restartRequired, changed: [`removed ${gone.map((k) => k.split(":").slice(1).join(":") || k).length} package(s) for ${mod.name}`], notes: [] };
  } catch (e) {
    return failure(e);
  }
}

/** Remove now-empty directories we created, never above the layout's named dirs. */
async function removeEmptyParents(fs: GuestFs, files: string[], layout: Layout) {
  const stops = new Set([layout.base, ...Object.values(layout.dirs)]);
  const dirs = new Set<string>();
  for (const f of files) {
    let d = f.split("/").slice(0, -1).join("/");
    while (d && !stops.has(d) && isWithin(layout.base, d)) {
      dirs.add(d);
      d = d.split("/").slice(0, -1).join("/");
    }
  }
  for (const d of [...dirs].sort((a, b) => b.length - a.length)) {
    if ((await fs.list(d)).length === 0) await fs.remove(d);
  }
}

function disabledPath(key: string, p: string) {
  return `${DISABLED_DIR}/${safeKey(key)}${p}`;
}

/** Disable (move aside / native flag) or re-enable an installed mod. */
export async function setDisabled(installer: FamilyInstaller, mod: CatalogFacts, server: ServerFacts, deps: EngineDeps, disabled: boolean): Promise<OpResult> {
  const fs = deps.fs;
  try {
    const layout = await detectOrFail(installer, fs, server, mod);
    const state = await loadState(fs, server.family);
    const r = state.roots[mod.id];
    const p = r ? state.packages[r.key] : null;
    if (!p) return { ok: false, error: `${mod.name} isn't installed by Nxeon on this server, so it can't be ${disabled ? "disabled" : "enabled"} here.` };
    if (p.disabled === disabled) return { ok: true, restartRequired: false, changed: [], notes: [`${mod.name} is already ${disabled ? "disabled" : "enabled"}.`] };

    if (disabled) {
      const needers = Object.entries(state.roots)
        .filter(([id, rr]) => id !== mod.id && rr.key !== p.key && !state.packages[rr.key]?.disabled && state.packages[rr.key]?.requires.includes(p.key))
        .map(([, rr]) => rr.name);
      if (needers.length) return { ok: false, error: `${needers.join(", ")} need${needers.length === 1 ? "s" : ""} ${mod.name} — disable ${needers.length === 1 ? "it" : "them"} first.` };
    } else {
      for (const f of p.files) {
        if (installer.nativeToggle) break;
        if (await fs.stat(f.path)) return { ok: false, error: `${f.path} already exists again (put back by hand?) — nothing was changed.` };
      }
    }

    if (!installer.nativeToggle) {
      for (const f of p.files) {
        if (disabled) await fs.rename(f.path, disabledPath(p.key, f.path));
        else await fs.rename(disabledPath(p.key, f.path), f.path);
      }
      if (!disabled) await fs.remove(`${DISABLED_DIR}/${safeKey(p.key)}`);
      else await removeEmptyParents(fs, p.files.map((f) => f.path), layout);
    }
    p.disabled = disabled;
    p.updatedAt = (deps.now ?? (() => new Date()))().toISOString();
    if (installer.configure) {
      for (const e of await installer.configure(fs, layout, enabledList(state), allList(state))) {
        if (!isWithin(layout.base, e.path)) continue;
        await fs.writeFile(`${e.path}.nxeon-part`, e.data);
        await fs.rename(`${e.path}.nxeon-part`, e.path);
      }
    }
    await saveState(fs, state);
    return { ok: true, version: p.version, restartRequired: installer.restartRequired, changed: [`${disabled ? "disabled" : "enabled"} ${mod.name}`], notes: [] };
  } catch (e) {
    return failure(e);
  }
}

/**
 * Dry run for the portal's dependency preview: resolve against what the DB
 * knows about the server (no guest access), report what WOULD be installed.
 */
export async function previewResolve(
  installer: FamilyInstaller,
  mod: CatalogFacts,
  server: ServerFacts,
  fetcher: Fetcher,
  layoutGuess: Layout,
): Promise<{ ok: true; packages: { name: string; version: string; root: boolean; size: number | null }[]; notes: string[]; restartRequired: boolean } | { ok: false; error: string }> {
  try {
    const res = await installer.resolve(mod, { server, layout: layoutGuess, fetcher });
    if ("error" in res) return { ok: false, error: res.error };
    return {
      ok: true,
      packages: res.packages.map((p) => ({ name: p.name, version: p.version, root: p.root, size: p.file.size })),
      notes: res.notes,
      restartRequired: installer.restartRequired,
    };
  } catch (e) {
    return failure(e);
  }
}

