/**
 * Minecraft: Java Edition — plugins, mods, datapacks and Modrinth modpacks.
 *
 * Server layout (itzg/minecraft-server, prisma/catalog.ts): `/opt/mc` on the
 * VM is the container's `/data`. Variant = itzg `TYPE` (worker/game-variant.ts):
 *
 *   paper / purpur / spigot / bukkit / folia  → plugin jars in /opt/mc/plugins
 *   fabric / quilt / forge / neoforge          → mod jars in    /opt/mc/mods
 *   any variant, vanilla included              → datapack zips in /opt/mc/<level-name>/datapacks
 *   modpack (.mrpack)                          → its server-side files + server overrides,
 *                                                only when loader + MC version match exactly
 *
 * Sources: Modrinth (versions filtered by loader AND game version, sha1+sha512
 * verified, required dependencies walked, `incompatible` honoured), Hangar
 * (sha256 verified, required plugin dependencies by name) and SpigotMC via
 * Spiget (Spigot-hosted files only; external links and premium resources are
 * refused — Spiget publishes no checksum, which the result says).
 *
 * Restart: Paper/Spigot/Fabric/Forge all load jars at startup only.
 */
import { readZip, fileMap, ArchiveError } from "../archive";
import { fetchJson, MOD_HOSTS, validateUrl } from "../safe-fetch";
import { joinUnder, normalizeRel, safeFileName } from "../paths";
import type { CatalogFacts, Compat, FamilyInstaller, InstallerCtx, Layout, PlacedFile, Resolution, ResolvedPackage, ServerFacts } from "../types";
import type { GuestFs } from "../guest-fs";

const MODRINTH = "https://api.modrinth.com/v2";
const PLUGIN_VARIANTS = ["paper", "purpur", "spigot", "bukkit", "folia"];
const MOD_VARIANTS = ["fabric", "quilt", "forge", "neoforge"];

/** Which Modrinth loader tags a server variant can actually load, best first. */
export function acceptedLoaders(variant: string | null): string[] {
  switch ((variant ?? "vanilla").toLowerCase()) {
    case "paper": return ["paper", "spigot", "bukkit"];
    case "purpur": return ["purpur", "paper", "spigot", "bukkit"];
    case "spigot": return ["spigot", "bukkit"];
    case "bukkit": return ["bukkit"];
    case "folia": return ["folia"];
    case "fabric": return ["fabric"];
    case "quilt": return ["quilt", "fabric"];
    case "forge": return ["forge"];
    case "neoforge": return ["neoforge"];
    default: return [];
  }
}

export function isPluginVariant(v: string | null) { return PLUGIN_VARIANTS.includes((v ?? "").toLowerCase()); }
export function isModVariant(v: string | null) { return MOD_VARIANTS.includes((v ?? "").toLowerCase()); }

const CLIENT_ONLY_CATEGORIES = ["resource packs", "shaders", "resourcepack", "shader"];

export function mcCompat(mod: CatalogFacts, server: ServerFacts): Compat {
  const cat = mod.category.toLowerCase();
  if (CLIENT_ONLY_CATEGORIES.includes(cat)) return { verdict: "unsupported", detail: "Resource packs and shaders run on players' own game, not on the server." };
  if (mod.serverSide === "unsupported") return { verdict: "unsupported", detail: "This is a client-side mod — it does nothing on a server." };
  const variant = (server.variant ?? "vanilla").toLowerCase();
  const loaders = mod.loaders.map((l) => l.toLowerCase());
  const accepted = acceptedLoaders(variant);
  const isPack = cat === "modpacks";
  const isDatapack = cat === "datapacks" || (loaders.length > 0 && loaders.every((l) => l === "datapack"));
  if (mod.appliesToVariant && mod.appliesToVariant !== variant && !accepted.includes(mod.appliesToVariant)) {
    return { verdict: "mismatch", detail: `Needs a ${mod.appliesToVariant} server — yours runs ${variant}. Change the server type in Settings.` };
  }
  if (!isDatapack && !isPack && loaders.length) {
    const ok = loaders.some((l) => accepted.includes(l)) || (loaders.includes("datapack"));
    if (!ok) {
      const want = loaders.filter((l) => [...PLUGIN_VARIANTS, ...MOD_VARIANTS].includes(l)).slice(0, 3).join(" / ") || loaders.slice(0, 3).join(" / ");
      return { verdict: "mismatch", detail: `Built for ${want} — your server runs ${variant}. Change the server type in Settings to use it.` };
    }
  }
  if (isPack && loaders.length && !loaders.some((l) => l === variant || accepted.includes(l))) {
    return { verdict: "mismatch", detail: `This modpack is built for ${loaders.slice(0, 2).join(" / ")} — your server runs ${variant}.` };
  }
  if (variant === "vanilla" && !isDatapack && !loaders.includes("datapack")) {
    return { verdict: "mismatch", detail: "Vanilla servers can only load datapacks. Switch to Paper (plugins) or Fabric/Forge (mods) in Settings." };
  }
  const gv = server.pinnedVersion;
  if (!mod.gameVersions.length) return { verdict: "unknown", reason: "no-list", detail: "The source doesn't publish a supported-version list — we check at install time." };
  if (!gv) return { verdict: "unknown", reason: "server-unpinned", detail: "Your server isn't pinned to a version; we'll read the real version at install time." };
  if (mod.gameVersions.includes(gv)) return { verdict: "ok", detail: `Supports ${gv} on ${variant}.` };
  return { verdict: "mismatch", detail: `No build listed for ${gv} — the source lists ${newest(mod.gameVersions) ?? "other versions"}.` };
}

function newest(vs: string[]): string | null {
  const rel = vs.filter((v) => /^\d+(\.\d+)+$/.test(v));
  return rel.sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).pop() ?? null;
}

// ─── detect ──────────────────────────────────────────────────────────────────

const ROOT_CANDIDATES = ["/opt/mc", "/opt/minecraft", "/srv/minecraft", "/root/minecraft"];

export function parseProperties(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of text.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#")) continue;
    const i = t.indexOf("=");
    if (i > 0) out[t.slice(0, i).trim()] = t.slice(i + 1).trim();
  }
  return out;
}

export function versionFromLog(log: string): string | null {
  const m = /Starting minecraft server version ([0-9][0-9A-Za-z.\-+ ]*?)\s*$/m.exec(log);
  return m ? m[1].trim() : null;
}

async function detect(fs: GuestFs, server: ServerFacts): Promise<Layout | { error: string }> {
  let base: string | null = null;
  for (const c of ROOT_CANDIDATES) {
    if ((await fs.stat(`${c}/server.properties`))?.type === "file") { base = c; break; }
  }
  if (!base) return { error: "Couldn't find this server's Minecraft folder (no server.properties yet) — start the server once, then try again." };
  const props = parseProperties((await fs.readFile(`${base}/server.properties`, 1024 * 1024))?.toString("utf8") ?? "");
  const levelSegs = normalizeRel(props["level-name"] || "world");
  if (!levelSegs) return { error: "This server's level-name isn't a folder name we can safely write into." };
  let gameVersion = server.pinnedVersion;
  if (!gameVersion) {
    const log = await fs.readFile(`${base}/logs/latest.log`, 32 * 1024 * 1024);
    gameVersion = log ? versionFromLog(log.toString("utf8")) : null;
  }
  return {
    base,
    dirs: { plugins: `${base}/plugins`, mods: `${base}/mods`, datapacks: joinUnder(base, [...levelSegs, "datapacks"]), root: base },
    gameVersion,
    flavour: (server.variant ?? "vanilla").toLowerCase(),
  };
}

// ─── Modrinth ────────────────────────────────────────────────────────────────

type MrFile = { url: string; filename: string; primary: boolean; size: number; hashes: { sha1?: string; sha512?: string } };
type MrVersion = {
  id: string;
  project_id: string;
  name: string;
  version_number: string;
  version_type: "release" | "beta" | "alpha";
  loaders: string[];
  game_versions: string[];
  files: MrFile[];
  dependencies: { version_id: string | null; project_id: string | null; file_name?: string | null; dependency_type: "required" | "optional" | "incompatible" | "embedded" }[];
};
type MrProject = { id: string; slug: string; title: string; project_type: string; server_side: string; client_side: string };

const enc = (v: unknown) => encodeURIComponent(JSON.stringify(v));

/** Newest release first; beta/alpha only when nothing stable matches. */
export function pickModrinthVersion(versions: MrVersion[], loaders: string[], gameVersion: string | null): MrVersion | null {
  const ok = versions.filter((v) => (!loaders.length || v.loaders.some((l) => loaders.includes(l))) && (!gameVersion || v.game_versions.includes(gameVersion)) && v.files.length > 0);
  const rank = (v: MrVersion) => (v.version_type === "release" ? 0 : v.version_type === "beta" ? 1 : 2);
  // Modrinth already returns newest first; keep that order within a rank.
  return ok.map((v, i) => ({ v, i })).sort((a, b) => rank(a.v) - rank(b.v) || a.i - b.i)[0]?.v ?? null;
}

function placementFor(v: MrVersion, project: MrProject, variant: string): string {
  if (project.project_type === "modpack") return "mrpack";
  if (project.project_type === "datapack" || (v.loaders.length === 1 && v.loaders[0] === "datapack")) return "datapack";
  if (isPluginVariant(variant)) return "plugin-jar";
  if (isModVariant(variant)) return v.loaders.includes("datapack") && !v.loaders.some((l) => acceptedLoaders(variant).includes(l)) ? "datapack" : "mod-jar";
  return "datapack";
}

async function resolveModrinth(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
  const gv = ctx.layout.gameVersion;
  const notes: string[] = [];
  const out = new Map<string, ResolvedPackage>();
  const order: string[] = [];
  const seen = new Set<string>();

  const visit = async (projectId: string, pinnedVersionId: string | null, depth: number, isRoot: boolean): Promise<string | null> => {
    if (seen.has(projectId)) return null;
    seen.add(projectId);
    if (out.size >= 40) return "This mod pulls in more than 40 dependencies — too many to install in one click.";
    let project: MrProject;
    try {
      project = await fetchJson<MrProject>(ctx.fetcher, `${MODRINTH}/project/${encodeURIComponent(projectId)}`);
    } catch {
      return isRoot ? `Couldn't find ${mod.name} on Modrinth (it may have been removed).` : `A required dependency (${projectId}) couldn't be found on Modrinth.`;
    }
    if (project.server_side === "unsupported") {
      if (isRoot) return `${project.title} is client-side only — it does nothing on a server.`;
      notes.push(`Skipped ${project.title}: client-side only.`);
      return null;
    }
    const isPack = project.project_type === "modpack";
    const isDp = project.project_type === "datapack";
    const loaders = isPack ? [] : isDp ? ["datapack"] : [...acceptedLoaders(variant), "datapack"];
    if (!isPack && !isDp && acceptedLoaders(variant).length === 0) {
      // Vanilla: datapack builds only.
      loaders.splice(0, loaders.length, "datapack");
    }
    if (!gv && !isDp) return `Couldn't tell which Minecraft version this server runs — pin a version in Settings (or start the server once), then try again.`;

    let v: MrVersion | null = null;
    if (pinnedVersionId) {
      try {
        const pv = await fetchJson<MrVersion>(ctx.fetcher, `${MODRINTH}/version/${encodeURIComponent(pinnedVersionId)}`);
        v = pickModrinthVersion([pv], isPack ? [] : loaders, gv);
      } catch { /* fall back to the newest compatible below */ }
    }
    if (!v) {
      const q = `${MODRINTH}/project/${encodeURIComponent(project.id)}/version?${loaders.length ? `loaders=${enc(loaders)}&` : ""}${gv ? `game_versions=${enc([gv])}` : ""}`;
      let versions: MrVersion[] = [];
      try {
        versions = await fetchJson<MrVersion[]>(ctx.fetcher, q);
      } catch {
        return `Modrinth didn't answer for ${project.title} — try again in a minute.`;
      }
      v = pickModrinthVersion(versions, isPack ? [] : loaders, gv);
    }
    if (!v) {
      const what = isPack ? "" : ` on ${variant}`;
      return isRoot
        ? `${project.title} has no build for Minecraft ${gv ?? "(unknown)"}${what} — nothing was installed.`
        : `${mod.name} needs ${project.title}, which has no build for Minecraft ${gv ?? "(unknown)"}${what} — nothing was installed.`;
    }
    if (isPack && !isRoot) return `${mod.name} depends on a modpack (${project.title}), which can't be installed as a dependency.`;

    const placement = placementFor(v, project, variant);
    if (placement === "datapack" && !isDp && !v.loaders.includes("datapack") && !isRoot) {
      notes.push(`Skipped ${project.title}: no ${variant} build.`);
      return null;
    }
    const file = v.files.find((f) => f.primary) ?? v.files[0];
    const key = `modrinth:${project.id}`;
    const requires: string[] = [];
    const incompatible: { key: string; name: string }[] = [];
    if (depth < 6) {
      for (const d of v.dependencies) {
        if (!d.project_id && d.version_id) {
          try {
            const dv = await fetchJson<MrVersion>(ctx.fetcher, `${MODRINTH}/version/${encodeURIComponent(d.version_id)}`);
            d.project_id = dv.project_id;
          } catch { /* unresolvable; handled below */ }
        }
        if (!d.project_id) {
          if (d.dependency_type === "required") return `${project.title} requires a dependency Modrinth can't identify — nothing was installed.`;
          continue;
        }
        if (d.dependency_type === "incompatible") incompatible.push({ key: `modrinth:${d.project_id}`, name: d.project_id });
        if (d.dependency_type !== "required") continue;
        const err = await visit(d.project_id, d.version_id, depth + 1, false);
        if (err) return err;
        if (out.has(`modrinth:${d.project_id}`)) requires.push(`modrinth:${d.project_id}`);
      }
    }
    out.set(key, {
      key,
      name: project.title,
      version: v.version_number,
      versionId: v.id,
      file: { url: file.url, filename: file.filename, size: file.size ?? null, hashes: { sha1: file.hashes.sha1, sha512: file.hashes.sha512 }, mirrorKey: { source: "modrinth", projectId: project.id, versionId: v.id } },
      placement,
      requires,
      incompatible,
      root: isRoot,
    });
    order.push(key);
    return null;
  };

  const err = await visit(mod.sourceId || mod.slug, null, 0, true);
  if (err) return { error: err };
  // `order` is post-order: dependencies before dependents, root last.
  const root = order[order.length - 1];
  const packages = order.filter((k) => k !== root).map((k) => out.get(k)!).concat(out.get(root)!);
  return { packages, notes };
}

// ─── Hangar ──────────────────────────────────────────────────────────────────

type HangarVersion = {
  name: string;
  channel?: { name: string };
  downloads: Record<string, { fileInfo?: { name: string; sizeBytes: number; sha256Hash: string } | null; externalUrl?: string | null; downloadUrl?: string | null }>;
  pluginDependencies?: Record<string, { name: string; required: boolean; externalUrl?: string | null }[]>;
  platformDependencies?: Record<string, string[]>;
};

async function resolveHangar(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
  const variant = (ctx.server.variant ?? "").toLowerCase();
  if (!isPluginVariant(variant) || variant === "spigot" || variant === "bukkit") return { error: "Hangar plugins need a Paper-based server (Paper, Purpur or Folia)." };
  const platform = variant === "folia" ? "PAPER" : "PAPER";
  const gv = ctx.layout.gameVersion;
  const out: ResolvedPackage[] = [];
  const seen = new Set<string>();
  const visit = async (slug: string, isRoot: boolean, depth: number): Promise<string | null> => {
    if (seen.has(slug.toLowerCase())) return null;
    seen.add(slug.toLowerCase());
    if (seen.size > 25) return "Too many dependencies to install in one click.";
    let page: { result: HangarVersion[] };
    try {
      page = await fetchJson(ctx.fetcher, `https://hangar.papermc.io/api/v1/projects/${encodeURIComponent(slug)}/versions?limit=25&offset=0&platform=${platform}${gv ? `&platformVersion=${encodeURIComponent(gv)}` : ""}`);
    } catch {
      return isRoot ? `Couldn't find ${mod.name} on Hangar.` : `Required plugin ${slug} isn't on Hangar — nothing was installed.`;
    }
    const v = (page.result ?? []).find((x) => (x.channel?.name ?? "Release").toLowerCase() === "release") ?? page.result?.[0];
    const dl = v?.downloads?.[platform];
    if (!v || !dl) return `${isRoot ? mod.name : slug} has no Paper build${gv ? ` for ${gv}` : ""} on Hangar.`;
    if (!dl.fileInfo || !dl.downloadUrl) return `${isRoot ? mod.name : slug} is only linked externally from Hangar — download it from its own site and upload it in Files.`;
    const requires: string[] = [];
    if (depth < 5) {
      for (const d of v.pluginDependencies?.[platform] ?? []) {
        if (!d.required) continue;
        if (d.externalUrl) return `${isRoot ? mod.name : slug} requires ${d.name}, which isn't hosted on Hangar — install it by hand first.`;
        const e = await visit(d.name, false, depth + 1);
        if (e) return e;
        requires.push(`hangar:${d.name.toLowerCase()}`);
      }
    }
    out.push({
      key: `hangar:${slug.toLowerCase()}`,
      name: isRoot ? mod.name : slug,
      version: v.name,
      versionId: v.name,
      file: { url: dl.downloadUrl, filename: dl.fileInfo.name, size: dl.fileInfo.sizeBytes, hashes: { sha256: dl.fileInfo.sha256Hash }, mirrorKey: { source: "hangar", projectId: slug, versionId: v.name } },
      placement: "plugin-jar",
      requires,
      incompatible: [],
      root: isRoot,
    });
    return null;
  };
  const err = await visit(mod.sourceId || mod.slug, true, 0);
  if (err) return { error: err };
  return { packages: out, notes: [] };
}

// ─── SpigotMC (Spiget) ───────────────────────────────────────────────────────

type SpigetResource = { id: number; name: string; external?: boolean; premium?: boolean; file?: { type?: string; size?: number; sizeUnit?: string; externalUrl?: string }; version?: { id: number } };

async function resolveSpigot(mod: CatalogFacts, ctx: InstallerCtx): Promise<Resolution | { error: string }> {
  const variant = (ctx.server.variant ?? "").toLowerCase();
  if (!isPluginVariant(variant) || variant === "folia") return { error: "SpigotMC plugins need a Paper, Purpur or Spigot server." };
  const id = (mod.sourceId ?? "").trim();
  if (!/^\d{1,9}$/.test(id)) return { error: "This SpigotMC entry has no valid resource id." };
  let r: SpigetResource;
  try {
    r = await fetchJson<SpigetResource>(ctx.fetcher, `https://api.spiget.org/v2/resources/${id}`);
  } catch {
    return { error: `Couldn't look up ${mod.name} on SpigotMC.` };
  }
  if (r.premium) return { error: `${mod.name} is a paid SpigotMC resource — buy it there and upload the jar in Files.` };
  if (r.external || (r.file?.type && r.file.type !== ".jar")) return { error: `${mod.name} is hosted outside SpigotMC — download it from its own page and upload the jar in Files.` };
  return {
    packages: [{
      key: `spigotmc:${id}`,
      name: mod.name,
      version: String(r.version?.id ?? "latest"),
      versionId: r.version?.id ? String(r.version.id) : null,
      file: { url: `https://api.spiget.org/v2/resources/${id}/download`, filename: `nxeon-${mod.slug}.jar`, size: null, hashes: {}, mirrorKey: { source: "spigotmc", projectId: id, versionId: r.version?.id ? String(r.version.id) : null } },
      placement: "plugin-jar",
      requires: [],
      incompatible: [],
      root: true,
    }],
    notes: ["SpigotMC doesn't publish checksums, so this download is size-capped and type-checked but can't be hash-verified."],
  };
}

// ─── placement ───────────────────────────────────────────────────────────────

const MRPACK_DL_HOSTS = ["cdn.modrinth.com", "github.com", "raw.githubusercontent.com", "gitlab.com", "objects.githubusercontent.com", "release-assets.githubusercontent.com"];
const MAX_PACK_FILES = 600;
const MAX_PACK_BYTES = 400 * 1024 * 1024;

type MrIndex = {
  formatVersion: number;
  game: string;
  name?: string;
  files: { path: string; hashes: { sha1?: string; sha512?: string }; env?: { client?: string; server?: string }; downloads: string[]; fileSize?: number }[];
  dependencies: Record<string, string>;
};

const LOADER_DEP: Record<string, string> = { fabric: "fabric-loader", quilt: "quilt-loader", forge: "forge", neoforge: "neoforge" };

/** Check a modpack's declared loader + MC version against the server. */
export function checkMrpackDeps(deps: Record<string, string>, variant: string, gameVersion: string | null): string | null {
  const mc = deps["minecraft"];
  const loader = Object.entries(LOADER_DEP).find(([, k]) => k in deps)?.[0] ?? null;
  if (!loader) return "This modpack doesn't declare a mod loader we can run (Fabric, Quilt, Forge or NeoForge).";
  if (loader !== variant && !(variant === "quilt" && loader === "fabric")) {
    return `This modpack is built for ${loader} ${deps[LOADER_DEP[loader]] ?? ""} on Minecraft ${mc} — switch your server type to ${loader} and its version to ${mc} in Settings, then install it.`.replace(/\s+/g, " ");
  }
  if (mc && gameVersion && mc !== gameVersion) return `This modpack needs Minecraft ${mc}; your server runs ${gameVersion}. Change the version in Settings first.`;
  if (mc && !gameVersion) return `This modpack needs Minecraft ${mc}; pin your server to ${mc} in Settings first.`;
  return null;
}

async function placeMrpack(pkg: ResolvedPackage, bytes: Buffer, ctx: InstallerCtx): Promise<PlacedFile[] | { error: string }> {
  const entries = fileMap(readZip(bytes));
  const idxRaw = entries.get("modrinth.index.json");
  if (!idxRaw) return { error: "This modpack file has no modrinth.index.json." };
  let idx: MrIndex;
  try {
    idx = JSON.parse(idxRaw.toString("utf8"));
  } catch {
    return { error: "This modpack's index isn't valid JSON." };
  }
  if (idx.formatVersion !== 1 || idx.game !== "minecraft") return { error: "Unsupported modpack format." };
  const variant = (ctx.server.variant ?? "vanilla").toLowerCase();
  const depErr = checkMrpackDeps(idx.dependencies ?? {}, variant, ctx.layout.gameVersion);
  if (depErr) return { error: depErr };
  const base = ctx.layout.base;
  const files = (idx.files ?? []).filter((f) => (f.env?.server ?? "required") !== "unsupported");
  if (files.length > MAX_PACK_FILES) return { error: `This modpack has ${files.length} server files — more than one click can safely handle.` };
  const declared = files.reduce((s, f) => s + (f.fileSize ?? 0), 0);
  if (declared > MAX_PACK_BYTES) return { error: `This modpack is ${Math.round(declared / 1048576)} MB of server files — over the ${MAX_PACK_BYTES / 1048576} MB one-click limit.` };

  const out: PlacedFile[] = [];
  const seen = new Set<string>();
  for (const f of files) {
    const segs = normalizeRel(f.path);
    if (!segs) return { error: `This modpack lists an unsafe path (${String(f.path).slice(0, 80)}) — refused.` };
    if (!f.hashes?.sha1 && !f.hashes?.sha512) return { error: `This modpack lists ${f.path} without a checksum — refused.` };
    const url = (f.downloads ?? []).find((u) => {
      try { validateUrl(u, MRPACK_DL_HOSTS); return true; } catch { return false; }
    });
    if (!url) return { error: `${f.path} in this modpack is only available from a host we don't download from.` };
    const r = await ctx.fetcher(url, { maxBytes: 128 * 1024 * 1024, expect: { sha1: f.hashes.sha1, sha512: f.hashes.sha512 }, allow: MRPACK_DL_HOSTS });
    const path = joinUnder(base, segs);
    seen.add(path);
    out.push({ path, data: r.bytes });
  }
  // overrides/ then server-overrides/ (the latter wins), per the .mrpack spec.
  for (const prefix of ["overrides/", "server-overrides/"]) {
    for (const [name, data] of entries) {
      if (!name.startsWith(prefix)) continue;
      const rel = name.slice(prefix.length);
      if (!rel) continue;
      const path = joinUnder(base, rel);
      const i = out.findIndex((x) => x.path === path);
      const pf: PlacedFile = { path, data, overwrite: "backup" };
      if (i >= 0) out[i] = pf; else out.push(pf);
    }
  }
  void pkg;
  return out;
}

export function placeJarOrDatapack(pkg: ResolvedPackage, bytes: Buffer, layout: Layout): PlacedFile[] | { error: string } {
  if (pkg.placement === "datapack") {
    const name = safeFileName(pkg.file.filename, [".zip"]);
    if (!name) return { error: `${pkg.name}'s file isn't a datapack .zip.` };
    try { readZip(bytes); } catch (e) { return { error: `${pkg.name}'s datapack is not a valid zip: ${(e as Error).message}` }; }
    return [{ path: joinUnder(layout.dirs.datapacks, name), data: bytes }];
  }
  const name = safeFileName(pkg.file.filename, [".jar"]);
  if (!name) return { error: `${pkg.name}'s download isn't a .jar file — refused.` };
  // A jar is a zip; anything else (an HTML error page, an installer) is refused here.
  try {
    readZip(bytes, { maxEntries: 60_000, maxEntryBytes: 256 * 1024 * 1024, maxTotalBytes: 1024 * 1024 * 1024, maxRatio: 1000 });
  } catch (e) {
    return { error: `${pkg.name}'s download isn't a valid jar (${e instanceof ArchiveError ? e.message : "unreadable"}) — refused.` };
  }
  const dir = pkg.placement === "plugin-jar" ? layout.dirs.plugins : layout.dirs.mods;
  return [{ path: joinUnder(dir, name), data: bytes }];
}

export const minecraftInstaller: FamilyInstaller = {
  family: "minecraft",
  sources: ["modrinth", "hangar", "spigotmc"],
  mechanism: "Plugin jars into plugins/ (Paper/Purpur/Spigot), mod jars into mods/ (Fabric/Quilt/Forge/NeoForge), datapacks into the world's datapacks/, Modrinth modpacks file-by-file with checksums.",
  restartRequired: true,
  compat: mcCompat,
  detect: (fs, server) => detect(fs, server),
  async resolve(mod, ctx) {
    if (mod.source === "modrinth") return resolveModrinth(mod, ctx);
    if (mod.source === "hangar") return resolveHangar(mod, ctx);
    if (mod.source === "spigotmc") return resolveSpigot(mod, ctx);
    return { error: `Minecraft one-click install doesn't support ${mod.source} yet.` };
  },
  async place(pkg, bytes, ctx) {
    if (pkg.placement === "mrpack") {
      try {
        return await placeMrpack(pkg, bytes, ctx);
      } catch (e) {
        return { error: `Couldn't unpack this modpack: ${(e as Error).message}` };
      }
    }
    return placeJarOrDatapack(pkg, bytes, ctx.layout);
  },
  legacyPaths(mod, layout) {
    // worker/game-mods.ts's pre-engine installer wrote nxeon-<slug>.jar into plugins/ or mods/.
    const n = `nxeon-${mod.slug}.jar`;
    if (!/^[a-z0-9][a-z0-9._-]*$/i.test(mod.slug)) return [];
    return [`${layout.dirs.plugins}/${n}`, `${layout.dirs.mods}/${n}`];
  },
};

export { MOD_HOSTS };

