/**
 * Valheim — BepInEx plugins from Thunderstore.
 *
 * Server: lloesche/valheim-server (prisma/catalog.ts), `-v /opt/valheim/config:/config`.
 * With the BepInEx server type (`BEPINEX=true`, worker/game-config.ts) the image
 * itself copies /config/bepinex/plugins into its BepInEx install on every
 * start — that folder is the documented drop point, and the only one this
 * installer writes to. BepInEx loads plugin DLLs recursively, so each package
 * gets its own `<Namespace>-<Name>` folder (the r2modman/Thunderstore
 * convention), which is also what makes uninstall exact.
 *
 * Package layout (Thunderstore's documented structure): manifest.json,
 * icon.png, README.md at the root, and the payload either at the root, under
 * `plugins/`, or under `BepInEx/plugins/`. Everything that isn't plugin
 * payload is handled explicitly:
 *   - `config/` defaults are skipped (BepInEx writes a config on first run);
 *   - `patchers/`, `core/`, `monomod/` need BepInEx's preloader folders, which
 *     this server type doesn't sync from /config — such packages are refused
 *     with that reason rather than installed half-working;
 *   - BepInExPack (the loader itself) is never installed: the server image
 *     provides BepInEx.
 *
 * Dependencies come from the package's own declared list (exact versions, as
 * the author pinned them). Thunderstore publishes no file checksum in its API,
 * so downloads are size-capped, zip-validated and recorded with our own sha256.
 */
import { readZip, ArchiveError } from "../archive";
import { fetchJson } from "../safe-fetch";
import { joinUnder, isSafeSegment } from "../paths";
import type { CatalogFacts, Compat, FamilyInstaller, InstallerCtx, PlacedFile, ResolvedPackage, ServerFacts } from "../types";

const TS = "https://thunderstore.io/api/experimental/package";
const VALHEIM_PLUGINS = "/opt/valheim/config/bepinex/plugins";

type TsVersion = { namespace: string; name: string; version_number: string; full_name: string; download_url: string; dependencies: string[]; file_size?: number; is_active?: boolean };
type TsPackage = { namespace: string; name: string; full_name: string; is_deprecated?: boolean; latest: TsVersion };

/** "Author-Name-1.2.3" → parts. Names may contain dashes? Thunderstore forbids them in name/namespace. */
export function parseDepString(s: string): { namespace: string; name: string; version: string } | null {
  const m = /^([A-Za-z0-9_]+)-([A-Za-z0-9_]+)-(\d+\.\d+\.\d+)$/.exec(s.trim());
  return m ? { namespace: m[1], name: m[2], version: m[3] } : null;
}

export function isLoaderPack(namespace: string, name: string): boolean {
  return /bepinexpack/i.test(name) || (namespace === "denikson" && /bepinex/i.test(name));
}

/**
 * Map a Thunderstore package's files to BepInEx plugin files under
 * `<pluginsDir>/<folder>/`. Pure; exported for the fixture tests.
 */
export function bepinexPlacement(entries: { path: string[]; dir: boolean; data: Buffer }[], pluginsDir: string, folder: string): PlacedFile[] | { error: string } {
  if (!isSafeSegment(folder)) return { error: "unsafe package folder name" };
  const META = new Set(["manifest.json", "icon.png", "readme.md", "changelog.md", "license", "license.md", "license.txt"]);
  const out: PlacedFile[] = [];
  for (const e of entries) {
    if (e.dir) continue;
    let segs = e.path;
    const lower = segs.map((s) => s.toLowerCase());
    if (segs.length === 1 && META.has(lower[0])) continue;
    if (lower[0] === "bepinex") { segs = segs.slice(1); lower.shift(); }
    const top = lower[0];
    if (["patchers", "core", "monomod"].includes(top)) {
      return { error: `this package needs BepInEx ${top}/ files, which this server type can't load from the plugins folder` };
    }
    if (top === "config") continue; // defaults: BepInEx generates the real config on first run
    if (top === "plugins") segs = segs.slice(1);
    if (segs.length === 0) continue;
    out.push({ path: joinUnder(pluginsDir, [folder, ...segs]), data: e.data });
  }
  return out;
}

export const valheimInstaller: FamilyInstaller = {
  family: "valheim",
  sources: ["thunderstore"],
  mechanism: "BepInEx plugins from Thunderstore into /opt/valheim/config/bepinex/plugins/<Author-Name>/ (the image syncs them into BepInEx on start).",
  restartRequired: true,

  compat(_mod: CatalogFacts, server: ServerFacts): Compat {
    if ((server.variant ?? "vanilla") !== "bepinex") {
      return { verdict: "mismatch", detail: "Mods need the BepInEx server type — switch it in Settings (your world is kept)." };
    }
    return { verdict: "unknown", reason: "no-list", detail: "Thunderstore doesn't publish a game-version list; mods load against the current Valheim build." };
  },

  async detect(fs, server) {
    if ((server.variant ?? "vanilla") !== "bepinex") return { error: "Mods need the BepInEx server type. Switch to it in Settings (your world is kept), then install." };
    if ((await fs.stat("/opt/valheim/config"))?.type !== "dir") return { error: "Couldn't find this server's Valheim config folder — is the server fully set up?" };
    await fs.mkdirp(VALHEIM_PLUGINS);
    return { base: "/opt/valheim/config", dirs: { plugins: VALHEIM_PLUGINS }, gameVersion: null };
  },

  async resolve(mod, ctx: InstallerCtx) {
    const id = (mod.sourceId ?? "").trim();
    const [ns, ...rest] = id.split("-");
    if (!ns || rest.length !== 1) return { error: "This Thunderstore entry has no valid Author-Name id." };
    const notes: string[] = [];
    const order: ResolvedPackage[] = [];
    const seen = new Set<string>();
    const visit = async (namespace: string, name: string, version: string | null, isRoot: boolean, depth: number): Promise<string | null> => {
      const k = `${namespace}-${name}`.toLowerCase();
      if (seen.has(k)) return null;
      seen.add(k);
      if (isLoaderPack(namespace, name)) {
        notes.push("BepInEx itself is provided by your server — not installed separately.");
        return null;
      }
      if (seen.size > 40) return "This mod pulls in more than 40 dependencies — too many for one click.";
      let v: TsVersion;
      try {
        if (version) v = await fetchJson<TsVersion>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/${encodeURIComponent(version)}/`);
        else {
          const p = await fetchJson<TsPackage>(ctx.fetcher, `${TS}/${encodeURIComponent(namespace)}/${encodeURIComponent(name)}/`);
          if (p.is_deprecated && isRoot) notes.push(`${p.full_name} is marked deprecated by its author.`);
          v = p.latest;
        }
      } catch {
        return isRoot ? `Couldn't find ${mod.name} on Thunderstore (it may have been removed).` : `${mod.name} needs ${namespace}-${name}${version ? ` ${version}` : ""}, which couldn't be found on Thunderstore.`;
      }
      const requires: string[] = [];
      if (depth < 6) {
        for (const d of v.dependencies ?? []) {
          const dep = parseDepString(d);
          if (!dep) return `${v.full_name} declares a dependency we can't parse (${d}).`;
          const e = await visit(dep.namespace, dep.name, dep.version, false, depth + 1);
          if (e) return e;
          if (!isLoaderPack(dep.namespace, dep.name)) requires.push(`thunderstore:${dep.namespace}-${dep.name}`);
        }
      }
      order.push({
        key: `thunderstore:${v.namespace}-${v.name}`,
        name: isRoot ? mod.name : `${v.namespace}-${v.name}`,
        version: v.version_number,
        versionId: v.full_name,
        file: { url: v.download_url, filename: `${v.full_name}.zip`, size: v.file_size ?? null, hashes: {}, mirrorKey: { source: "thunderstore", projectId: `${v.namespace}-${v.name}`, versionId: v.version_number } },
        placement: "bepinex",
        requires,
        incompatible: [],
        root: isRoot,
      });
      return null;
    };
    const err = await visit(ns, rest[0], null, true, 0);
    if (err) return { error: err };
    if (!order.length) return { error: `${mod.name} is the mod loader itself — your server already provides BepInEx.` };
    notes.push("Thunderstore doesn't publish checksums; downloads are size-capped and archive-checked.");
    return { packages: order, notes };
  },

  async place(pkg, bytes, ctx) {
    let entries;
    try {
      entries = readZip(bytes);
    } catch (e) {
      return { error: `${pkg.name} isn't a valid Thunderstore package (${e instanceof ArchiveError ? e.message : "unreadable"}).` };
    }
    const folder = pkg.key.replace(/^thunderstore:/, "");
    const r = bepinexPlacement(entries, ctx.layout.dirs.plugins, folder);
    if ("error" in r) return { error: `${pkg.name}: ${r.error}.` };
    return r;
  },

  legacyPaths(mod, layout) {
    // Pre-engine installer: whole package unzipped into plugins/nxeon-<slug>/.
    if (!/^[a-z0-9][a-z0-9._-]*$/i.test(mod.slug)) return [];
    return [`${layout.dirs.plugins}/nxeon-${mod.slug}`];
  },
};

