/**
 * Rust — uMod (Oxide) / Carbon C# plugins.
 *
 * Server: didstopia/rust-server, `-v /opt/rust:/steamcmd/rust`. Oxide keeps
 * plugins in `<server>/oxide/plugins`, Carbon in `<server>/carbon/plugins`;
 * both compile and HOT-LOAD a `.cs` dropped there (and unload it when it's
 * removed), so no restart is needed — which is why this installer says so.
 *
 * The framework must already be on the server: we look for the folder rather
 * than trusting the server-type label. A vanilla server is told plainly that
 * plugins need Oxide or Carbon.
 *
 * Source: umod.org's public JSON (`/plugins/<slug>.json` → `download_url`).
 * Dependencies are what uMod plugins actually declare: a `// Requires: Name`
 * comment at the top of the .cs, which Oxide itself enforces at load time.
 * We read it from the downloaded source and install those plugins too.
 * uMod publishes no checksum; downloads are size-capped and must look like C#.
 */
import { fetchJson } from "../safe-fetch";
import { joinUnder, safeFileName } from "../paths";
import type { FamilyInstaller, ResolvedPackage, ServerFacts, CatalogFacts, Compat } from "../types";

type UmodPlugin = { name: string; title: string; slug: string; download_url: string; latest_release_version?: string; latest_release_version_formatted?: string; games_detail?: { slug: string }[] };

/** `// Requires: Economics, ImageLibrary` → ["Economics","ImageLibrary"]. Only the file header. */
export function parseRequires(cs: string): string[] {
  const head = cs.split(/\r?\n/).slice(0, 60);
  const out: string[] = [];
  for (const line of head) {
    const m = /^\s*\/\/\s*Requires\s*:\s*(.+)$/i.exec(line);
    if (!m) continue;
    for (const n of m[1].split(/[,\s]+/)) if (/^[A-Za-z][A-Za-z0-9_]{1,63}$/.test(n)) out.push(n);
  }
  return [...new Set(out)];
}

export function looksLikeCSharpPlugin(text: string): boolean {
  return /namespace\s+(Oxide|Carbon)\.Plugins/.test(text) && /\[Info\s*\(/.test(text);
}

/** uMod slugs are the kebab-case of the class name ("ImageLibrary" → "image-library"). */
export function umodSlugFor(className: string): string {
  return className.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/([A-Z])([A-Z][a-z])/g, "$1-$2").toLowerCase();
}

export const rustInstaller: FamilyInstaller = {
  family: "rust",
  sources: ["umod"],
  mechanism: "uMod .cs plugins into oxide/plugins (or carbon/plugins) — compiled and hot-loaded by the framework, no restart.",
  restartRequired: false,

  compat(_mod: CatalogFacts, server: ServerFacts): Compat {
    const v = (server.variant ?? "vanilla").toLowerCase();
    if (v === "vanilla") return { verdict: "mismatch", detail: "Plugins need Oxide (uMod) or Carbon on the server — a vanilla Rust server can't load them." };
    return { verdict: "unknown", reason: "no-list", detail: "uMod doesn't publish a game-version list; Oxide reports compile errors in the console." };
  },

  async detect(fs) {
    for (const [flavour, dir] of [["oxide", "/opt/rust/oxide"], ["carbon", "/opt/rust/carbon"]] as const) {
      if ((await fs.stat(dir))?.type === "dir") {
        await fs.mkdirp(`${dir}/plugins`);
        return { base: "/opt/rust", dirs: { plugins: `${dir}/plugins` }, gameVersion: null, flavour };
      }
    }
    if ((await fs.stat("/opt/rust"))?.type !== "dir") return { error: "Couldn't find this server's Rust folder — is the server fully set up?" };
    return { error: "This Rust server doesn't have Oxide (uMod) or Carbon installed, so it can't load plugins. A vanilla server needs the framework first." };
  },

  async resolve(mod, ctx) {
    const out: ResolvedPackage[] = [];
    const seen = new Set<string>();
    const notes = ["uMod doesn't publish checksums; downloads are size-capped and checked to be an Oxide plugin."];
    const visit = async (slug: string, isRoot: boolean, depth: number): Promise<string | null> => {
      if (seen.has(slug)) return null;
      seen.add(slug);
      if (seen.size > 20) return "Too many plugin dependencies to install in one click.";
      let p: UmodPlugin;
      try {
        p = await fetchJson<UmodPlugin>(ctx.fetcher, `https://umod.org/plugins/${encodeURIComponent(slug)}.json`);
      } catch {
        return isRoot ? `Couldn't find ${mod.name} on uMod.` : `${mod.name} requires the ${slug} plugin, which couldn't be found on uMod — nothing was installed.`;
      }
      if (p.games_detail && !p.games_detail.some((g) => g.slug === "rust")) return `${p.title} isn't a Rust plugin.`;
      const file = safeFileName(p.download_url, [".cs"]);
      if (!file || !/^[A-Za-z0-9_]+\.cs$/.test(file)) return `${p.title} isn't a single .cs plugin — install it by hand in Files.`;
      const r = await ctx.fetcher(p.download_url, { maxBytes: 4 * 1024 * 1024 });
      const text = r.bytes.toString("utf8");
      if (!looksLikeCSharpPlugin(text)) return `The download for ${p.title} doesn't look like an Oxide plugin — refused.`;
      const requires: string[] = [];
      if (depth < 4) {
        for (const cls of parseRequires(text)) {
          const e = await visit(umodSlugFor(cls), false, depth + 1);
          if (e) return e;
          requires.push(`umod:${umodSlugFor(cls)}`);
        }
      }
      out.push({
        key: `umod:${p.slug}`,
        name: isRoot ? mod.name : p.title,
        version: p.latest_release_version_formatted || p.latest_release_version || "latest",
        versionId: p.latest_release_version ?? null,
        file: { url: p.download_url, filename: file, size: r.bytes.length, hashes: { sha256: r.sha256 } },
        placement: "oxide-cs",
        requires,
        incompatible: [],
        prefetched: r.bytes,
        root: isRoot,
      });
      return null;
    };
    const err = await visit(mod.sourceId || mod.slug, true, 0);
    if (err) return { error: err };
    return { packages: out, notes };
  },

  async place(pkg, bytes, ctx) {
    const name = safeFileName(pkg.file.filename, [".cs"]);
    if (!name) return { error: `${pkg.name} has an unsafe filename.` };
    return [{ path: joinUnder(ctx.layout.dirs.plugins, name), data: bytes }];
  },

  legacyPaths() {
    // The pre-engine installer wrote <PascalName>.cs — the same file uMod names
    // it, so the engine adopts or replaces it in place; nothing extra to clean.
    return [];
  },
};

