/**
 * Counter-Strike 2 — CounterStrikeSharp plugins from their authors' GitHub releases.
 *
 * Server: joedwards32/cs2, `-v /opt/cs2:/home/steam/cs2-dedicated`, so the
 * game directory is /opt/cs2/game/csgo. CounterStrikeSharp (CSS) runs on top
 * of Metamod:Source and loads each plugin from
 * `addons/counterstrikesharp/plugins/<PluginName>/<PluginName>.dll`.
 *
 * Both frameworks must ALREADY be on the server (we check the folders, not the
 * "Metamod" server-type label). Installing Metamod itself means editing
 * gameinfo.gi, which a CS2 update rewrites; that is not done here until it can
 * be verified on a live server — such a server gets a plain "needs
 * CounterStrikeSharp" answer instead of a half-working install.
 *
 * Release archives come in a few real shapes, all handled by `cssPlacement`:
 *   addons/counterstrikesharp/plugins/X/…   (most common — the zip mirrors csgo/)
 *   counterstrikesharp/plugins/X/…
 *   plugins/X/…
 *   X/X.dll + friends                       (a single plugin folder)
 *   X.dll + X.deps.json at the root          (loose build output)
 * plus optional `cfg/` and `addons/counterstrikesharp/{configs,shared,gamedata}/`.
 * Anything that would land outside csgo/addons/counterstrikesharp or csgo/cfg
 * (e.g. a bundled metamod/ folder) is refused rather than written.
 *
 * GitHub publishes a sha256 digest for release assets; when present it is
 * verified. CSS hot-reloads plugins, but a restart is what makes config and
 * shared-library changes take effect reliably, so we ask for one.
 */
import { readArchive, ArchiveError } from "../archive";
import { fetchJson } from "../safe-fetch";
import { joinUnder, isSafeSegment } from "../paths";
import type { CatalogFacts, Compat, FamilyInstaller, PlacedFile, ServerFacts } from "../types";

const CSGO = "/opt/cs2/game/csgo";
const CSS_DIR = `${CSGO}/addons/counterstrikesharp`;

type GhAsset = { name: string; size: number; browser_download_url: string; digest?: string | null; content_type?: string };
type GhRelease = { tag_name: string; name?: string; draft?: boolean; prerelease?: boolean; assets: GhAsset[] };

/** Pick the asset to install: an archive, Linux-or-generic, not source/debug/Windows-only. */
export function pickCssAsset(assets: GhAsset[]): GhAsset | null {
  const arch = assets.filter((a) => /\.(zip|tar\.gz|tgz)$/i.test(a.name) && !/source|src|debug|symbols|pdb/i.test(a.name));
  const notWin = arch.filter((a) => !/windows|win64|win-x64|-win\b/i.test(a.name));
  const linux = notWin.find((a) => /linux/i.test(a.name));
  return linux ?? notWin[0] ?? null;
}

const CSS_SUBDIRS = new Set(["plugins", "shared", "configs", "gamedata", "translations"]);

/**
 * Map archive entries to files under csgo/. Pure; exported for fixture tests.
 * `fallbackName` names the plugin folder for loose root-level builds.
 */
export function cssPlacement(entries: { path: string[]; dir: boolean; data: Buffer }[], fallbackName: string): PlacedFile[] | { error: string } {
  const files = entries.filter((e) => !e.dir);
  if (!files.length) return { error: "the archive is empty" };
  // Strip one wrapping folder (e.g. "MyPlugin-v1.2/addons/…") when everything shares it and it isn't itself meaningful.
  let list = files.map((e) => ({ segs: e.path, data: e.data }));
  const first = list[0].segs[0];
  const shared = list.every((f) => f.segs.length > 1 && f.segs[0] === first);
  const meaningful = (s: string) => ["addons", "counterstrikesharp", "plugins", "cfg", "shared"].includes(s.toLowerCase());
  if (shared && !meaningful(first)) {
    const inner = list.map((f) => ({ segs: f.segs.slice(1), data: f.data }));
    // Keep the wrapper as the plugin folder if the inner files are a loose build.
    const innerHasStructure = inner.some((f) => f.segs.length > 1 && meaningful(f.segs[0]));
    if (innerHasStructure) list = inner;
  }
  const META = /^(readme|license|changelog)(\.(md|txt))?$/i;
  const out: PlacedFile[] = [];
  for (const f of list) {
    const s = f.segs;
    const l = s.map((x) => x.toLowerCase());
    let rel: string[] | null = null;
    if (l[0] === "addons" && l[1] === "counterstrikesharp" && CSS_SUBDIRS.has(l[2] ?? "")) rel = ["addons", "counterstrikesharp", ...s.slice(2)];
    else if (l[0] === "addons") return { error: `it ships files for addons/${s[1] ?? ""} (another framework) — install it by hand` };
    else if (l[0] === "counterstrikesharp" && CSS_SUBDIRS.has(l[1] ?? "")) rel = ["addons", "counterstrikesharp", ...s.slice(1)];
    else if (CSS_SUBDIRS.has(l[0]) && s.length > 2) rel = ["addons", "counterstrikesharp", ...s];
    else if (l[0] === "cfg" && s.length > 1) rel = s;
    else if (s.length === 1 && META.test(s[0])) continue;
    else if (s.length === 1) rel = ["addons", "counterstrikesharp", "plugins", fallbackName, s[0]];
    else if (s.length >= 2 && files.some((x) => x.path.length === 2 && x.path[0] === s[0] && /\.dll$/i.test(x.path[1]))) rel = ["addons", "counterstrikesharp", "plugins", ...s];
    else return { error: `unexpected file layout (${s.join("/").slice(0, 80)})` };
    if (!rel.every(isSafeSegment)) return { error: "unsafe path" };
    out.push({ path: joinUnder(CSGO, rel), data: f.data, overwrite: l[0] === "cfg" || l.includes("configs") ? "backup" : undefined });
  }
  if (!out.some((f) => /\/plugins\/[^/]+\/[^/]+\.dll$/i.test(f.path) || /\/shared\/[^/]+\/[^/]+\.dll$/i.test(f.path))) {
    return { error: "it contains no CounterStrikeSharp plugin .dll" };
  }
  return out;
}

export const cs2Installer: FamilyInstaller = {
  family: "cs2",
  sources: ["github"],
  mechanism: "CounterStrikeSharp plugins from GitHub releases into csgo/addons/counterstrikesharp/plugins/<Name>/ (needs Metamod + CounterStrikeSharp on the server).",
  restartRequired: true,

  compat(mod: CatalogFacts, server: ServerFacts): Compat {
    if ((server.variant ?? "vanilla") !== "metamod") return { verdict: "mismatch", detail: "Plugins need the Metamod:Source server type with CounterStrikeSharp." };
    if (mod.loaders.length && !mod.loaders.some((l) => ["counterstrikesharp", "metamod"].includes(l.toLowerCase()))) {
      return { verdict: "mismatch", detail: `Built for ${mod.loaders.join(", ")} — Nxeon installs CounterStrikeSharp plugins.` };
    }
    return { verdict: "unknown", reason: "no-list", detail: "GitHub releases don't carry a CS2 version list; CSS logs load errors in the console." };
  },

  async detect(fs) {
    if ((await fs.stat(CSGO))?.type !== "dir") return { error: "Couldn't find this server's csgo folder — is the server fully set up?" };
    if ((await fs.stat(`${CSGO}/addons/metamod`))?.type !== "dir") return { error: "This server doesn't have Metamod:Source installed, which CS2 plugins need. One-click Metamod setup isn't available yet." };
    if ((await fs.stat(CSS_DIR))?.type !== "dir") return { error: "This server has Metamod but not CounterStrikeSharp, which these plugins need. One-click CounterStrikeSharp setup isn't available yet." };
    return { base: CSGO, dirs: { plugins: `${CSS_DIR}/plugins`, css: CSS_DIR, cfg: `${CSGO}/cfg` }, gameVersion: null };
  },

  async resolve(mod, ctx) {
    const repo = (mod.sourceId ?? "").trim();
    if (!/^[A-Za-z0-9_.-]{1,100}\/[A-Za-z0-9_.-]{1,100}$/.test(repo)) return { error: "This GitHub entry has no valid owner/repo." };
    if (/^(roflmuffin\/CounterStrikeSharp|alliedmodders\/metamod-source)$/i.test(repo)) {
      return { error: `${mod.name} is a framework, not a plugin — one-click framework setup isn't available yet.` };
    }
    const headers: Record<string, string> = { Accept: "application/vnd.github+json" };
    if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
    let rel: GhRelease;
    try {
      rel = await fetchJson<GhRelease>(ctx.fetcher, `https://api.github.com/repos/${repo}/releases/latest`, { headers });
    } catch {
      return { error: `${mod.name} has no published GitHub release to install (or GitHub is rate-limiting us) — try again later.` };
    }
    const asset = pickCssAsset(rel.assets ?? []);
    if (!asset) return { error: `${mod.name}'s latest release (${rel.tag_name}) has no installable archive.` };
    const digest = asset.digest && /^sha256:[0-9a-f]{64}$/i.test(asset.digest) ? asset.digest.slice(7) : null;
    const name = repo.split("/")[1].replace(/[^A-Za-z0-9_.-]/g, "");
    return {
      packages: [{
        key: `github:${repo.toLowerCase()}`,
        name: mod.name,
        version: rel.tag_name,
        versionId: rel.tag_name,
        file: { url: asset.browser_download_url, filename: asset.name, size: asset.size, hashes: digest ? { sha256: digest } : {}, mirrorKey: { source: "github", projectId: repo, versionId: rel.tag_name } },
        placement: name,
        requires: [],
        incompatible: [],
        root: true,
      }],
      notes: digest ? [] : ["This release has no published checksum; the download is size-capped and archive-checked."],
    };
  },

  async place(pkg, bytes) {
    let entries;
    try {
      entries = readArchive(bytes);
    } catch (e) {
      return { error: `${pkg.name}'s release isn't a readable archive (${e instanceof ArchiveError ? e.message : "unknown format"}).` };
    }
    const r = cssPlacement(entries, pkg.placement);
    return "error" in r ? { error: `${pkg.name}: ${r.error}.` } : r;
  },
};

