    const layout: Layout = { base: ROOT, dirs: { mods: MODS }, gameVersion };
    const cred = await credentials(layout, fs);
    if (!cred) {
      return {
        error:
          "Factorio's mod portal only lets a factorio.com account download mods. Add your factorio.com username and token (factorio.com → Profile → token) to config/server-settings.json in Files, then try again.",
      };
    }
    // Carried only in memory for this one operation's download URLs.
    (layout as Layout & { _cred?: typeof cred })._cred = cred;
    return layout;
  },

  async resolve(mod: CatalogFacts, ctx) {
    const gv = ctx.layout.gameVersion;
    if (!gv) return { error: "Couldn't read this server's Factorio version." };
    const cred = (ctx.layout as Layout & { _cred?: { username: string; token: string } })._cred ?? null;
    const out: ResolvedPackage[] = [];
    const seen = new Set<string>();
    const notes: string[] = [];
    const visit = async (name: string, op: string | null, want: string | null, isRoot: boolean, depth: number): Promise<string | null> => {
      if (BUILTIN.has(name)) return null;
      if (seen.has(name)) return null;
      seen.add(name);
      if (seen.size > 40) return "This mod pulls in more than 40 dependencies — too many for one click.";
      let m: FMod;
      try {
        m = await fetchJson<FMod>(ctx.fetcher, `${PORTAL}/api/mods/${encodeURIComponent(name)}/full`);
      } catch {
        return isRoot ? `Couldn't find ${name} on the Factorio mod portal.` : `${mod.name} needs ${name}, which isn't on the Factorio mod portal.`;
      }
      const rel = pickFactorioRelease(m.releases ?? [], gv, op, want);
      if (!rel) return `${m.title} has no release for Factorio ${gv.split(".").slice(0, 2).join(".")}${op ? ` matching ${op} ${want}` : ""} — nothing was installed.`;
      const requires: string[] = [];
      const incompatible: { key: string; name: string }[] = [];
      for (const ds of rel.info_json.dependencies ?? []) {
        const d = parseFactorioDep(ds);
        if (!d) continue;
        if (d.kind === "incompatible") { incompatible.push({ key: `factorio:${d.name}`, name: d.name }); continue; }
        if (d.kind === "optional") continue;
        if (BUILTIN.has(d.name)) {
          if (d.name === "base" && !satisfies(gv, d.op, d.version)) return `${m.title} needs Factorio ${d.op} ${d.version}; your server runs ${gv}.`;
          if (d.name !== "base" && d.name !== "core") notes.push(`${m.title} uses ${d.name} content from the Space Age expansion.`);
          continue;
        }
        if (depth < 6) {
          const e = await visit(d.name, d.op, d.version, false, depth + 1);
          if (e) return e;
          requires.push(`factorio:${d.name}`);
        }
      }
      const file = safeFileName(rel.file_name, [".zip"]);
      if (!file || !/^\/download\/[A-Za-z0-9_\-. %]+\/[0-9a-f]{24}$/.test(rel.download_url)) return `Unexpected download details for ${m.title} — refused.`;
