      if (j.name !== pkg.placement) return { error: `${pkg.name}'s info.json names a different mod (${String(j.name).slice(0, 40)}) — refused.` };
    } catch (e) {
      return { error: `${pkg.name} isn't a valid Factorio mod zip (${e instanceof ArchiveError ? e.message : "unreadable"}).` };
    }
    const placed: PlacedFile[] = [{ path: joinUnder(ctx.layout.dirs.mods, name), data: bytes }];
    return placed;
  },

  async configure(fs, layout, enabled, all) {
    const path = `${layout.dirs.mods}/mod-list.json`;
    const cur = await fs.readFile(path, 4 * 1024 * 1024);
    const on = new Set(enabled.map((e) => e.key));
    const ours = all.map((a) => ({ name: nameOfKey(a.key), enabled: on.has(a.key) }));
    // Names we ever managed (including just-removed ones) are dropped when absent from `all`.
    const managed = new Set(all.map((a) => nameOfKey(a.key)));
    const prevState = await fs.readFile("/root/.nxeon-mods/state.json", 8 * 1024 * 1024);
    if (prevState) {
      try {
        for (const k of Object.keys((JSON.parse(prevState.toString("utf8")) as { packages: Record<string, unknown> }).packages)) managed.add(nameOfKey(k));
      } catch { /* ignore */ }
    }
    return [{ path, data: Buffer.from(syncModList(cur ? cur.toString("utf8") : null, ours, [...managed])), overwrite: "backup" }];
  },
};

