/**
 * Per-family one-click mod coverage — the single table the worker, the portal
 * and docs/MODS-COVERAGE.md agree on.
 *
 *  engine      — lib/mods/engine.ts + an installer in this folder (resolve →
 *                verified download → safe placement → state/rollback). Supports
 *                install, update, enable/disable, uninstall.
 *  legacy      — a family-specific path in worker/game-mods.ts that predates
 *                the engine and was verified on a live server (Steam Workshop
 *                config-writes, TShock restart-and-verify, Vintage Story,
 *                Satisfactory, Arma Reforger). Install + uninstall; the
 *                game itself owns updates for Workshop families.
 *  unavailable — no honest one-click path yet; `reason` says why, in words a
 *                customer can act on. The panel shows the catalogue with
 *                manual-install guidance, never an Install button.
 */
import type { FamilyInstaller } from "../types";
import { minecraftInstaller } from "./minecraft";
import { valheimInstaller } from "./valheim";
import { rustInstaller } from "./rust";
import { cs2Installer } from "./cs2";
import { factorioInstaller } from "./factorio";

export const ENGINE_INSTALLERS: Record<string, FamilyInstaller> = {
  minecraft: minecraftInstaller,
  valheim: valheimInstaller,
  rust: rustInstaller,
  cs2: cs2Installer,
  factorio: factorioInstaller,
};

export function engineInstallerFor(family: string, source: string): FamilyInstaller | null {
  const i = ENGINE_INSTALLERS[family];
  return i && i.sources.includes(source) ? i : null;
}

export type Coverage =
  | { mode: "engine"; sources: readonly string[]; mechanism: string }
  | { mode: "legacy"; sources: readonly string[]; mechanism: string }
  | { mode: "unavailable"; reason: string };

/** Families with a pre-engine worker path (see worker/game-mods.ts). */
const LEGACY: Record<string, { sources: string[]; mechanism: string }> = {
  terraria: { sources: ["github"], mechanism: "TShock plugin .dll → restart → confirmed from TShock's own load log, rolled back otherwise." },
  ark: { sources: ["steam_workshop"], mechanism: "Workshop ids → GAME_MOD_IDS on the container; the server downloads them itself." },
  unturned: { sources: ["steam_workshop"], mechanism: "Workshop ids → WorkshopDownloadConfig.json; the server downloads them itself." },
  dst: { sources: ["steam_workshop"], mechanism: "Workshop ids → MODS env (dedicated_server_mods_setup.lua); the server downloads them." },
  squad: { sources: ["steam_workshop"], mechanism: "Workshop ids → MODS env; the image fetches them." },
  soulmask: { sources: ["steam_workshop"], mechanism: "Workshop ids → MOD_IDS env." },
  projectzomboid: { sources: ["steam_workshop"], mechanism: "WorkshopItems= + Mods= in servertest.ini (mod ids read from mod.info)." },
  tf2: { sources: ["steam_workshop"], mechanism: "tf_workshop_map_sync lines in server.cfg (needs a Workshop auth key)." },
  l4d2: { sources: ["steam_workshop"], mechanism: "steamcmd fetch in the container → addons/*.vpk + addonlist.txt." },
  empyrion: { sources: ["steam_workshop"], mechanism: "One Workshop scenario → Content/Scenarios + dedicated.yaml CustomScenario." },
  kf2: { sources: ["steam_workshop"], mechanism: "ServerSubscribedWorkshopItems in LinuxServer-KFEngine.ini." },
  gmod: { sources: ["steam_workshop"], mechanism: "steamcmd fetch → gmad extract into addons/ + resource.AddWorkshop." },
  necesse: { sources: ["steam_workshop"], mechanism: "steamcmd fetch → mod .jar into mods/." },
  vintagestory: { sources: ["vintagestory_moddb"], mechanism: "ModDB release for the server's version → data/Mods, dependencies from modinfo.json, load confirmed from the log." },
  armareforger: { sources: ["reforger_workshop"], mechanism: "MODS_JSON_B64 → game.mods; the server downloads from Bohemia's workshop." },
  satisfactory: { sources: ["ficsit"], mechanism: "ficsit.app LinuxServer builds (+ SML) into FactoryGame/Mods/<ref>." },
};

/** Why each remaining family has no one-click install (customer-facing). */
const UNAVAILABLE: Record<string, string> = {
  palworld: "Palworld's Workshop mods only load on Windows dedicated servers, and pak/UE4SS mods on Linux aren't something we can verify loading yet. Upload pak mods to Pal/Content/Paks/~mods in Files.",
  sdtd: "7 Days to Die mods are distributed outside any API we can install from (mostly Nexus). Upload them to serverfiles/Mods in Files.",
  vrising: "V Rising server mods (BepInEx) aren't wired yet — the server image doesn't ship BepInEx.",
  enshrouded: "Enshrouded has no server-side mod system yet.",
  conan: "Conan Exiles' Workshop mods need the Windows server's mod list, which the Linux image we run hasn't been verified with yet.",
  dayz: "DayZ Workshop downloads need a logged-in Steam account plus launch parameters — not wired yet.",
  theforest: "The Forest dedicated server has no supported server-side mod loader on Linux.",
  sonsoftheforest: "Sons of the Forest server mods (BepInEx/RedLoader) aren't wired — the server image doesn't ship a mod loader.",
  bedrock: "Bedrock add-ons (.mcpack) aren't in the catalogue yet. Upload behavior packs into the world folder in Files.",
  schedule1: "Schedule I has no official dedicated server.",
  dragonwilds: "RuneScape: Dragonwilds has no server-side mod system yet.",
  sunkenland: "Sunkenland server mods (BepInEx) aren't wired — the server image doesn't ship BepInEx.",
  abioticfactor: "Abiotic Factor has no server-side mod pipeline we can install from yet.",
  corekeeper: "Core Keeper's mods are on mod.io, which requires an API key per game — not wired yet.",
  icarus: "Icarus has no Workshop integration for dedicated servers.",
  arkasa: "ARK: Survival Ascended mods are on CurseForge, which requires an API key — not wired yet.",
  nightingale: "Nightingale has no server-side mod system yet.",
  spaceengineers: "Space Engineers Workshop/mod.io mods aren't wired for the Linux server yet.",
  barotrauma: "Barotrauma content packages aren't wired yet (needs a verified config_player.xml edit).",
  sandstorm: "Insurgency: Sandstorm mods are on mod.io, which needs an API key — not wired yet.",
  mordhau: "Mordhau mods are on mod.io, which needs an API key — not wired yet.",
  theisle: "The Isle (Evrima) has no mod ecosystem yet.",
  stationeers: "Stationeers Workshop content isn't wired yet.",
  eco: "Eco mods are on mod.io, which needs an API key — not wired yet.",
  plutoniumt4: "Plutonium servers load usermaps/scripts you upload in Files — there's no catalogue to install from.",
  plutoniumt5: "Plutonium servers load usermaps/scripts you upload in Files — there's no catalogue to install from.",
  plutoniumt6: "Plutonium servers load usermaps/scripts you upload in Files — there's no catalogue to install from.",
  plutoniumiw5: "Plutonium servers load usermaps/scripts you upload in Files — there's no catalogue to install from.",
  cs16: "CS 1.6 AMX Mod X plugins need compiling per server — not wired yet. Upload .amxx files in Files.",
  ets2: "Euro Truck Simulator 2 servers mirror your own game profile's mods — export server_packages and upload them in Files.",
  ats: "American Truck Simulator servers mirror your own game profile's mods — export server_packages and upload them in Files.",
};

export function familyCoverage(family: string): Coverage {
  const e = ENGINE_INSTALLERS[family];
  if (e) return { mode: "engine", sources: e.sources, mechanism: e.mechanism };
  const l = LEGACY[family];
  if (l) return { mode: "legacy", sources: l.sources, mechanism: l.mechanism };
  return { mode: "unavailable", reason: UNAVAILABLE[family] ?? "One-click mods aren't available for this game yet. Upload files in Files and restart from Console." };
}

export const COVERAGE_LEGACY = LEGACY;
export const COVERAGE_UNAVAILABLE = UNAVAILABLE;

