cd /opt/nxeon-wt-modinstall && python3 - <<'EOF'
p='worker/game-mods.ts'
s=open(p).read()

# imports
s=s.replace('''import type { Job } from "@prisma/client";''','''import type { Job } from "@prisma/client";
import { engineInstallerFor } from "../lib/mods/installers";
import { installOrUpdate, uninstall as engineUninstall, setDisabled as engineSetDisabled, type EngineDeps } from "../lib/mods/engine";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../lib/mods/guest-fs";
import { safeFetch } from "../lib/mods/safe-fetch";
import { dbMirrorLookup } from "../lib/mods/mirror";
import { catalogFacts, serverFacts, ENGINE_PENDING_STATUSES } from "../lib/mods/facts";
import type { OpResult } from "../lib/mods/types";
import { SshGuestFs } from "./mods-guest-ssh";''')

old_start = s.index("export async function gameModSync(job: Job): Promise<void> {")
old_end = s.index("// ===========================================================================\n// Real install/remove — per-source adapters over SSH.")
new_fn = r'''export async function gameModSync(job: Job): Promise<void> {
  const serverId = job.serverId;
  if (!serverId) throw new Error("game mod sync: job has no serverId");

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
  });
  if (!server) throw new Error(`Server ${serverId} not found`);

  const pending = await db.serverMod.findMany({
    where: { serverId, status: { in: [...ENGINE_PENDING_STATUSES] } },
    include: { mod: true },
    orderBy: { updatedAt: "asc" },
  });
  if (pending.length === 0) return;

  const installedNames: string[] = [];
  const removedNames: string[] = [];
  const failedNames: string[] = [];
  const changed: string[] = [];
  let restartRequired = false;

  // ── engine families (lib/mods/installers/*) — one guest connection per job ──
  let guest: GuestFs | null = null;
  let sshGuest: SshGuestFs | null = null;
  const engineRows = pending.filter((sm) => engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const legacyRows = pending.filter((sm) => !engineInstallerFor(sm.mod.gameFamily, sm.mod.source));
  const step = async (text: string, pct: number) => {
    await db.job.update({ where: { id: job.id }, data: { step: text.slice(0, 180), progress: Math.max(0, Math.min(99, pct)) } }).catch(() => {});
  };

  try {
    for (const [n, sm] of engineRows.entries()) {
      const installer = engineInstallerFor(sm.mod.gameFamily, sm.mod.source)!;
      const op = sm.status;
      let result: OpResult;
      if (!SANDBOX && !REAL_ENABLED) {
        result = { ok: false, error: "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified." };
      } else {
        try {
          if (!guest) {
            if (SANDBOX) {
              const local = new LocalGuestFs(sandboxGuestRoot(server.id));
              await seedSandboxGuest(local, sm.mod.gameFamily, server.gameVariant ?? null);
              guest = local;
            } else {
              sshGuest = await SshGuestFs.open(server);
              guest = sshGuest;
            }
          }
          const deps: EngineDeps = {
            fs: guest,
            fetcher: safeFetch,
            mirror: dbMirrorLookup((sql, ...args) => db.$queryRawUnsafe(sql, ...args)),
            progress: (text, pct) => step(`${sm.mod.name}: ${text}`, Math.round(((n + pct / 100) / engineRows.length) * 100)),
          };
          const facts = serverFacts(server);
          const cf = catalogFacts(sm.mod);
          result =
            op === "REMOVING" ? await engineUninstall(installer, cf, facts, deps)
            : op === "DISABLING" ? await engineSetDisabled(installer, cf, facts, deps, true)
            : op === "ENABLING" ? await engineSetDisabled(installer, cf, facts, deps, false)
            : await installOrUpdate(installer, cf, facts, deps, op === "UPDATING" ? "update" : "install");
        } catch (e) {
          result = { ok: false, error: e instanceof Error ? e.message : String(e) };
        }
      }

      const label = `${op.toLowerCase()} ${sm.mod.slug}`;
      if (result.ok) {
        restartRequired ||= result.restartRequired;
        changed.push(...result.changed);
        if (op === "REMOVING") {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({
            where: { id: sm.id },
            data: { status: op === "DISABLING" ? "DISABLED" : "INSTALLED", version: result.version ?? sm.version ?? null, error: null },
          });
          installedNames.push(sm.mod.name);
        }
        await db.auditLog.create({ data: { userId: server.userId, action: "gameserver.mod.applied", detail: `${serverId} ${label} ${result.version ?? ""} ${result.changed.join("; ")}`.slice(0, 900) } }).catch(() => {});
      } else {
        // A change that was NOT applied is a failure, and the row says what it still is.
        const restingStatus =
          op === "INSTALLING" ? "FAILED"
          : op === "ENABLING" ? "DISABLED"
          : "INSTALLED"; // failed remove/update/disable: whatever was there is still there
        await db.serverMod.update({ where: { id: sm.id }, data: { status: restingStatus, error: result.error.slice(0, 1000) } });
        failedNames.push(sm.mod.name);
        await db.auditLog.create({ data: { userId: server.userId, action: "gameserver.mod.failed", detail: `${serverId} ${label}: ${result.error}`.slice(0, 900) } }).catch(() => {});
      }
    }
  } finally {
    sshGuest?.close();
  }

  for (const sm of legacyRows) {
    const removing = sm.status === "REMOVING";
    try {
      if (sm.status !== "INSTALLING" && sm.status !== "REMOVING") {
        // Update/enable/disable are engine-only; the portal never queues them
        // for these families. Put the row back rather than leave it stuck.
        await db.serverMod.update({ where: { id: sm.id }, data: { status: sm.status === "ENABLING" ? "DISABLED" : "INSTALLED", error: "That action isn't available for this game." } });
        failedNames.push(sm.mod.name);
        continue;
      }
      if (SANDBOX) {
        // Dev simulation for the pre-engine families only — no VM mutation.
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({ where: { id: sm.id }, data: { status: "INSTALLED", error: null } });
          installedNames.push(sm.mod.name);
        }
        continue;
      }

      if (!REAL_ENABLED) {
        // Honest failure: nothing was applied. Do NOT report success.
        await db.serverMod.update({
          where: { id: sm.id },
          data: {
            status: removing ? "INSTALLED" : "FAILED",
            error:
              "Mod installation is being enabled for this game — your change was not applied yet. Our team has been notified.",
          },
        });
        failedNames.push(sm.mod.name);
        continue;
      }

      // REAL path — install/remove over SSH via the per-source adapter.
      const modRow: ModRowFull = {
        gameFamily: sm.mod.gameFamily,
        source: sm.mod.source,
        sourceId: sm.mod.sourceId,
        slug: sm.mod.slug,
        name: sm.mod.name,
        url: sm.mod.url,
        variant: server.gameVariant ?? null,
        appliesTo: sm.mod.appliesToVariant ?? null,
      };
      const extra = EXTRA_SOURCE_SYNC[sm.mod.source];
      const result =
        sm.mod.source === "steam_workshop"
          ? await workshopSync(server, sm.mod.gameFamily, serverId)
          : extra
          ? await extra(server, modRow, removing, serverId)
          : removing
          ? await removeModReal(server, modRow)
          : await installModReal(server, modRow);

      if (result.ok) {
        restartRequired = true;
        if (removing) {
          await db.serverMod.delete({ where: { id: sm.id } });
          removedNames.push(sm.mod.name);
        } else {
          await db.serverMod.update({
            where: { id: sm.id },
            data: { status: "INSTALLED", version: result.version ?? null, error: null },
          });
          installedNames.push(sm.mod.name);
        }
      } else {
        await db.serverMod.update({
          where: { id: sm.id },
          data: { status: removing ? "INSTALLED" : "FAILED", error: result.error ?? "install failed" },
        });
        failedNames.push(sm.mod.name);
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error(`[game-mods] ${removing ? "remove" : "install"} failed for ${sm.mod.slug}:`, e);
      await db.serverMod.update({
        where: { id: sm.id },
        // A failed removal stays INSTALLED (it's still there); a failed install is FAILED.
        data: { status: removing ? "INSTALLED" : "FAILED", error: msg },
      });
      failedNames.push(sm.mod.name);
    }
  }

  // Result for the portal: restart prompt + what changed (read by lib/actions-mods.ts).
  const prevPayload = (job.payload && typeof job.payload === "object" ? job.payload : {}) as Record<string, unknown>;
  await db.job
    .update({
      where: { id: job.id },
      data: {
        progress: 100,
        step: failedNames.length && !installedNames.length && !removedNames.length ? "Mod changes failed" : "Mod changes applied",
        payload: { ...prevPayload, result: { restartRequired: restartRequired && (installedNames.length + removedNames.length) > 0, changed: changed.slice(0, 40), failed: failedNames } },
      },
    })
    .catch(() => {});

  // One summary notification for the batch.
  const parts: string[] = [];
  if (installedNames.length) parts.push(`updated ${installedNames.join(", ")}`);
  if (removedNames.length) parts.push(`removed ${removedNames.join(", ")}`);
  if (failedNames.length) parts.push(`could not apply ${failedNames.join(", ")}`);
  const anyOk = installedNames.length > 0 || removedNames.length > 0;
  const allFailed = !anyOk && failedNames.length > 0;
  const restartHint = restartRequired && anyOk ? " Restart the server to load the changes." : "";

  await notify(
    server.userId,
    allFailed ? `Mod changes failed on ${server.hostname}` : `Mods updated on ${server.hostname}`,
    parts.length ? `${parts.join("; ")}.${restartHint}` : "No changes were made.",
    `/dashboard/servers/${server.id}?tab=mods`
  );
}

