# workshop desired set: include ENABLING
s=s.replace('''    where: { serverId, status: { in: ["INSTALLED", "INSTALLING"] }, mod: { gameFamily, source: "steam_workshop" } },''','''    where: { serverId, status: { in: ["INSTALLED", "INSTALLING", "UPDATING", "ENABLING"] }, mod: { gameFamily, source: "steam_workshop" } },''')
open(p,'w').write(s)
