// ─── engine end-to-end against a fake guest + fake upstream ────────────────

/** A tiny Modrinth: two projects, a dependency, a client-only project, version bumps. */
function fakeModrinth(jars: Record<string, Buffer>, opts: { pluginVersion?: string } = {}) {
  const sha = (b: Buffer) => ({ sha1: createHash("sha1").update(b).digest("hex"), sha512: createHash("sha512").update(b).digest("hex") });
  const pv = opts.pluginVersion ?? "1.0.0";
  const projects: Record<string, unknown> = {
    myplugin: { id: "P1", slug: "myplugin", title: "My Plugin", project_type: "mod", server_side: "required", client_side: "unsupported" },
    P1: { id: "P1", slug: "myplugin", title: "My Plugin", project_type: "mod", server_side: "required", client_side: "unsupported" },
    LIB: { id: "LIB", slug: "corelib", title: "Core Lib", project_type: "mod", server_side: "required", client_side: "unsupported" },
  };
  const versions: Record<string, unknown[]> = {
    P1: [{ id: "V" + pv, project_id: "P1", name: pv, version_number: pv, version_type: "release", loaders: ["paper"], game_versions: ["1.21.1"],
      files: [{ url: `https://cdn.modrinth.com/data/P1/versions/V${pv}/myplugin-${pv}.jar`, filename: `myplugin-${pv}.jar`, primary: true, size: jars[`myplugin-${pv}.jar`].length, hashes: sha(jars[`myplugin-${pv}.jar`]) }],
      dependencies: [{ project_id: "LIB", version_id: null, dependency_type: "required" }, { project_id: "BAD", version_id: null, dependency_type: "incompatible" }] }],
    LIB: [{ id: "L1", project_id: "LIB", name: "2.0", version_number: "2.0", version_type: "release", loaders: ["paper"], game_versions: ["1.21.1"],
      files: [{ url: "https://cdn.modrinth.com/data/LIB/versions/L1/corelib-2.0.jar", filename: "corelib-2.0.jar", primary: true, size: jars["corelib-2.0.jar"].length, hashes: sha(jars["corelib-2.0.jar"]) }], dependencies: [] }],
  };
  const calls: string[] = [];
  const fetcher: Fetcher = async (url, o) => {
    calls.push(url);
    validateUrl(url, o.allow);
    const u = new URL(url);
    let body: Buffer | null = null;
    let m: RegExpExecArray | null;
    if ((m = /^\/v2\/project\/([^/]+)$/.exec(u.pathname))) body = projects[decodeURIComponent(m[1])] ? Buffer.from(JSON.stringify(projects[decodeURIComponent(m[1])])) : null;
    else if ((m = /^\/v2\/project\/([^/]+)\/version$/.exec(u.pathname))) body = Buffer.from(JSON.stringify(versions[decodeURIComponent(m[1])] ?? []));
    else if (u.hostname === "cdn.modrinth.com") body = jars[u.pathname.split("/").pop()!] ?? null;
    if (!body) throw new FetchError("upstream answered HTTP 404", "status");
    const h = hashAll(body);
    checkHashes(h, o.expect);
    return { bytes: body, finalUrl: url, status: 200, ...h };
  };
  return { fetcher, calls };
}

const jar = (cls: string) => makeZip([{ name: "plugin.yml", data: `name: ${cls}\nmain: x.${cls}\n` }, { name: `x/${cls}.class`, data: Buffer.from([0xca, 0xfe, 0xba, 0xbe, 1, 2, 3]) }]);

function fakeGuest() {
  const root = mkdtempSync(path.join(tmpdir(), "nxeon-mods-test-"));
  mkdirSync(path.join(root, "opt/mc/plugins"), { recursive: true });
  writeFileSync(path.join(root, "opt/mc/server.properties"), "level-name=world\n");
  return { root, fs: new LocalGuestFs(root), at: (p: string) => path.join(root, p) };
}

test("engine: install with dependency → idempotent re-run → disable/enable → update → uninstall", async () => {
  const g = fakeGuest();
  try {
    const jars = { "myplugin-1.0.0.jar": jar("MyPlugin"), "myplugin-1.1.0.jar": jar("MyPluginV2"), "corelib-2.0.jar": jar("CoreLib") };
    const server = mcServer("paper");
    const mod = mcMod({ id: "gm_my", slug: "myplugin", name: "My Plugin", sourceId: "myplugin" });

    let up = fakeModrinth(jars);
    const r1 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(r1.ok, JSON.stringify(r1));
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(existsSync(g.at("opt/mc/plugins/corelib-2.0.jar")));
    assert.equal(r1.ok && r1.restartRequired, true);
    assert.deepEqual(r1.ok && r1.changed, ["added dependency Core Lib 2.0", "installed My Plugin 1.0.0"]);
    const st = await loadState(g.fs, "minecraft");
    assert.deepEqual(Object.keys(st.packages).sort(), ["modrinth:LIB", "modrinth:P1"]);
    assert.deepEqual(st.packages["modrinth:LIB"].roots, ["gm_my"]);

    // idempotent: second run downloads nothing and changes nothing
    up = fakeModrinth(jars);
    const r2 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(r2.ok && r2.changed.length === 0 && r2.restartRequired === false, JSON.stringify(r2));
    assert.ok(!up.calls.some((c) => c.includes("cdn.modrinth.com")), "no jar re-download");

    // disable moves it aside; enable puts it back
    const d = await setDisabled(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, true);
    assert.ok(d.ok, JSON.stringify(d));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
    assert.ok(existsSync(g.at("opt/mc/plugins/corelib-2.0.jar")), "dependency stays");
    const again = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(!again.ok && /disabled/.test(again.error));
    const e = await setDisabled(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, false);
    assert.ok(e.ok);
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));

    // update: new version replaces the old file, backup kept
    up = fakeModrinth(jars, { pluginVersion: "1.1.0" });
    const u = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher }, "update");
    assert.ok(u.ok, JSON.stringify(u));
    assert.deepEqual(u.ok && u.changed, ["updated My Plugin 1.0.0 → 1.1.0"]);
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.1.0.jar")));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));

    // uninstall removes the mod AND the dependency nothing else needs
    const x = await uninstall(minecraftInstaller, mod, server, { fs: g.fs, fetcher: up.fetcher });
    assert.ok(x.ok, JSON.stringify(x));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.1.0.jar")));
    assert.ok(!existsSync(g.at("opt/mc/plugins/corelib-2.0.jar")));
    assert.deepEqual(Object.keys((await loadState(g.fs, "minecraft")).packages), []);
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

test("engine: refuses to overwrite a hand-installed file, honours declared incompatibility, replaces legacy nxeon-<slug>.jar", async () => {
  const g = fakeGuest();
  try {
    const jars = { "myplugin-1.0.0.jar": jar("MyPlugin"), "corelib-2.0.jar": jar("CoreLib") };
