    writeFileSync(g.at("opt/mc/plugins/corelib-2.0.jar"), "someone else's file");
    const r = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: fakeModrinth(jars).fetcher });
    assert.ok(!r.ok && /wasn't installed by Nxeon/.test(r.error), JSON.stringify(r));
    assert.ok(!existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")), "nothing written on conflict");
    assert.equal(readFileSync(g.at("opt/mc/plugins/corelib-2.0.jar"), "utf8"), "someone else's file");
    rmSync(g.at("opt/mc/plugins/corelib-2.0.jar"));

    // incompatible package already installed
    const state = { v: 1, family: "minecraft", roots: { gm_bad: { key: "modrinth:BAD", name: "Bad Mod" } }, packages: { "modrinth:BAD": { key: "modrinth:BAD", name: "Bad Mod", version: "1", versionId: null, files: [], roots: ["gm_bad"], requires: [], incompatible: [], disabled: false, installedAt: "", updatedAt: "" } } };
    mkdirSync(path.dirname(g.at(STATE_PATH)), { recursive: true });
