    const r2 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: fakeModrinth(jars).fetcher });
    assert.ok(!r2.ok && /incompatible/.test(r2.error), JSON.stringify(r2));
    rmSync(g.at(STATE_PATH));

    // legacy file from the pre-engine installer is replaced (with backup)
    writeFileSync(g.at("opt/mc/plugins/nxeon-myplugin.jar"), "old");
    const r3 = await installOrUpdate(minecraftInstaller, mod, server, { fs: g.fs, fetcher: fakeModrinth(jars).fetcher });
