    assert.ok(!existsSync(g.at("opt/mc/plugins/nxeon-myplugin.jar")));
    assert.ok(existsSync(g.at("opt/mc/plugins/myplugin-1.0.0.jar")));
  } finally {
    rmSync(g.root, { recursive: true, force: true });
  }
});

