test("safe-fetch: https-only allowlist, no raw IPs, no creds, no odd ports", () => {
  assert.ok(hostAllowed("cdn.modrinth.com"));
  assert.ok(hostAllowed("gcdn.thunderstore.io"));
  assert.ok(!hostAllowed("evilthunderstore.io"));
  assert.ok(!hostAllowed("cdn.modrinth.com.evil.com"));
  assert.throws(() => validateUrl("http://cdn.modrinth.com/x.jar"), FetchError);
  assert.throws(() => validateUrl("https://127.0.0.1/x"), /raw IP/);
  assert.throws(() => validateUrl("https://[::1]/x"), FetchError);
  assert.throws(() => validateUrl("https://user:pw@cdn.modrinth.com/x"), /credentials/);
  assert.throws(() => validateUrl("https://cdn.modrinth.com:8443/x"), /port/);
  assert.throws(() => validateUrl("https://169.254.169.254/latest/meta-data"), FetchError);
  assert.throws(() => validateUrl("https://example.com/x"), /allowlist/);
  assert.ok(validateUrl("https://cdn.modrinth.com/data/x/versions/y/a.jar"));
});

test("safe-fetch: private address classifier", () => {
  for (const ip of ["10.20.3.4", "127.0.0.1", "169.254.169.254", "172.16.0.1", "192.168.1.1", "100.64.0.1", "0.0.0.0", "::1", "fd00::1", "fe80::1", "::ffff:10.0.0.1", "224.0.0.1"]) assert.ok(isPrivateAddress(ip), ip);
  for (const ip of ["104.16.1.1", "8.8.8.8", "2606:4700::1111"]) assert.ok(!isPrivateAddress(ip), ip);
});

test("checksums: a mismatch is a failure", () => {
  const h = hashAll(Buffer.from("abc"));
  assert.doesNotThrow(() => checkHashes(h, { sha1: h.sha1, sha512: h.sha512 }));
  assert.throws(() => checkHashes(h, { sha1: "0".repeat(40) }), /checksum mismatch/);
});

test("mirror: path must stay inside the mirror dir and hashes must agree", () => {
