"use server";

/**
 * Server actions behind the per-server Mods tab (components/customer/gamepanel/v2/ModsPanel.tsx).
 *
 * The catalogue is searched IN THE DATABASE, paged — Minecraft alone has
 * 30,000+ rows, and the old panel loaded the top 400 and filtered those in the
 * browser, which is why it looked like a "tiny curated set". Compatibility is
 * judged per row by the family's installer (lib/mods/installers/*) against
 * THIS server's loader and version.
 *
 * Every change is a ServerMod status flip + one GAME_MOD_SYNC job queued under
 * the per-server lock (lib/mods/queue.ts); the worker does the work and the
 * panel follows the job's step/progress. Ownership is checked on every call.
 */
import { revalidatePath } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { modCompat, modLoad, type ModLoad } from "./mod-load";
import { installSupport } from "./mod-install-support";
import { ENGINE_INSTALLERS, engineInstallerFor, familyCoverage } from "./mods/installers";
import { acceptedLoaders } from "./mods/installers/minecraft";
import { catalogFacts, serverFacts } from "./mods/facts";
import { enqueueModOp, type ModOp } from "./mods/queue";
import { previewResolve } from "./mods/engine";
import { safeFetch } from "./mods/safe-fetch";
import type { Compat } from "./mods/types";

async function ownedServer(serverId: string) {
  const user = await requireUser();
  if (typeof serverId !== "string" || serverId.length > 64) throw new Error("Not found");
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  const family = familyFor(server);
  return { user, server, family };
}

/* Per-user throttle for calls that hit upstream APIs (preview / update check). */
const hits = new Map<string, number[]>();
function throttled(userId: string, key: string, max: number, windowMs = 60_000): boolean {
  const k = `${userId}:${key}`;
  const now = Date.now();
  const arr = (hits.get(k) ?? []).filter((t) => now - t < windowMs);
  if (arr.length >= max) return true;
  arr.push(now);
  hits.set(k, arr);
  return false;
}

export type PanelMod = {
  id: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  url: string | null;
  description: string | null;
  iconUrl: string | null;
  authorName: string | null;
  downloads: number | null;
  fileBytes: number | null;
  dependencyCount: number;
  impact: string;
  impactNote: string | null;
  paid: boolean;
  featured: boolean;
  gameVersions: string[];
  loaders: string[];
  latestUpdated: string | null;
  compat: Compat;
  /** null = one-click works; otherwise the plain reason it doesn't. */
  manualInstall: string | null;
  /** install state on THIS server */
  status: string | null;
  version: string | null;
  error: string | null;
};

export type ModsOverview = {
  family: string;
  familyName: string;
  variant: string | null;
  gameVersion: string | null;
  coverage: { mode: "engine" | "legacy" | "unavailable"; text: string; canUpdate: boolean; canToggle: boolean };
  installed: PanelMod[];
  categories: { category: string; count: number }[];
  catalogTotal: number;
  job: { id: string; status: string; step: string | null; progress: number } | null;
  restart: { required: boolean; changed: string[]; since: string | null };
  load: ModLoad;
  serverRunning: boolean;
};

type ModRow = Prisma.GameModGetPayload<object>;

function compatFor(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>): Compat {
  const inst = engineInstallerFor(family, m.source) ?? ENGINE_INSTALLERS[family];
  if (inst) return inst.compat(catalogFacts(m), facts);
  const c = modCompat({ gameVersions: m.gameVersions, loaders: m.loaders, serverSide: m.serverSide }, { gameVersion: facts.pinnedVersion, variant: facts.variant });
  return c.verdict === "unknown" ? { verdict: "unknown", detail: c.detail, reason: c.reason } : (c as Compat);
}

function toPanel(family: string, m: ModRow, facts: ReturnType<typeof serverFacts>, st?: { status: string; version: string | null; error: string | null } | null): PanelMod {
  const sup = installSupport(family, m.source);
  const cov = familyCoverage(family);
  const compat = compatFor(family, m, facts);
  return {
    id: m.id,
    name: m.name,
    slug: m.slug,
    category: m.category,
    source: m.source,
    url: m.url,
    description: m.description,
    iconUrl: m.iconUrl,
    authorName: m.authorName,
    downloads: m.downloads,
    fileBytes: m.fileBytes,
    dependencyCount: m.dependencyCount,
    impact: m.impact,
    impactNote: m.impactNote,
    paid: m.paid,
    featured: m.featured,
    gameVersions: m.gameVersions.slice(-8),
    loaders: m.loaders.slice(0, 6),
    latestUpdated: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
    compat,
    manualInstall: cov.mode === "unavailable" ? cov.reason : !sup.ok ? sup.message : compat.verdict === "unsupported" ? compat.detail : null,
    status: st?.status ?? null,
    version: st?.version ?? null,
    error: st?.error ?? null,
  };
}

function gameVersionOf(server: { gameConfig: unknown }): string | null {
  return serverFacts({ id: "", gameVariant: null, gameConfig: server.gameConfig }).pinnedVersion;
}

/** Everything the panel needs except the catalogue page itself. */
export async function getModsOverview(serverId: string): Promise<{ error?: string; view?: ModsOverview }> {
  const { server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  const facts = serverFacts(server, family);
  const cov = familyCoverage(family);

  const [rows, cats, total, job, lastSync, lastPower] = await Promise.all([
    db.serverMod.findMany({ where: { serverId }, include: { mod: true }, orderBy: { installedAt: "asc" } }),
    db.gameMod.groupBy({ by: ["category"], where: { gameFamily: family, active: true, upstreamOk: true }, _count: { _all: true } }),
    db.gameMod.count({ where: { gameFamily: family, active: true, upstreamOk: true } }),
    db.job.findFirst({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } }, orderBy: { createdAt: "desc" }, select: { id: true, type: true, status: true, step: true, progress: true } }),
    db.job.findFirst({ where: { serverId, type: "GAME_MOD_SYNC", status: "DONE" }, orderBy: { updatedAt: "desc" }, select: { updatedAt: true, payload: true } }),
    db.job.findFirst({ where: { serverId, type: { in: ["GAME_POWER", "GAME_REINSTALL"] as never }, status: "DONE" }, orderBy: { updatedAt: "desc" }, select: { updatedAt: true, payload: true } }),
  ]);

  const result = (lastSync?.payload as { result?: { restartRequired?: boolean; changed?: string[] } } | null)?.result;
  const powerAction = (lastPower?.payload as { action?: string } | null)?.action;
  const restartedSince = !!lastPower && !!lastSync && lastPower.updatedAt > lastSync.updatedAt && powerAction !== "stop";
  const restart = {
    required: !!result?.restartRequired && !restartedSince,
    changed: result?.changed ?? [],
    since: lastSync?.updatedAt.toISOString() ?? null,
  };

  const installed = rows.filter((r) => r.mod.gameFamily === family).map((r) => toPanel(family, r.mod, facts, r));
  const live = rows.filter((r) => ["INSTALLED", "INSTALLING", "UPDATING", "ENABLING"].includes(r.status));
  return {
    view: {
      family,
      familyName: GAME_DISPLAY[family as GameFamily]?.name ?? family,
      variant: server.gameVariant ?? null,
      gameVersion: gameVersionOf(server),
      coverage: {
        mode: cov.mode,
        text: cov.mode === "unavailable" ? cov.reason : cov.mechanism,
        canUpdate: cov.mode === "engine",
        canToggle: cov.mode === "engine",
      },
      installed,
      categories: cats.map((c) => ({ category: c.category, count: c._count._all })).sort((a, b) => b.count - a.count),
      catalogTotal: total,
      job: job && job.type === "GAME_MOD_SYNC" ? { id: job.id, status: job.status, step: job.step, progress: job.progress } : job ? { id: job.id, status: job.status, step: "Another operation is running on this server", progress: job.progress } : null,
      restart,
      load: modLoad({
        ramMB: server.gamePlan?.ramMB ?? 0,
        installed: live.map((r) => ({ name: r.mod.name, fileBytes: r.mod.fileBytes, impact: r.mod.impact })),
      }),
      serverRunning: server.status === "RUNNING",
    },
  };
}

export type CatalogQuery = {
  q?: string;
  category?: string;
  sort?: "popular" | "name" | "updated" | "light";
  compatibleOnly?: boolean;
  page?: number;
};

const PAGE_SIZE = 24;
const CLIENT_ONLY = ["Resource Packs", "Shaders"];

/** One page of the catalogue for this server, searched and filtered in the DB. */
export async function searchModCatalog(serverId: string, query: CatalogQuery): Promise<{ error?: string; items?: PanelMod[]; total?: number; page?: number; pageSize?: number }> {
  const { server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  const facts = serverFacts(server, family);
  const q = (query.q ?? "").trim().slice(0, 80);
  const page = Math.max(1, Math.min(500, Math.floor(query.page ?? 1)));

  const and: Prisma.GameModWhereInput[] = [{ gameFamily: family, active: true, upstreamOk: true }];
  if (q) {
    and.push({ OR: [{ name: { contains: q, mode: "insensitive" } }, { slug: { contains: q.toLowerCase().replace(/\s+/g, "-") } }, { description: { contains: q, mode: "insensitive" } }, { authorName: { contains: q, mode: "insensitive" } }] });
  }
  if (query.category && query.category !== "all") and.push({ category: query.category.slice(0, 60) });
  if (query.compatibleOnly) {
    const inst = ENGINE_INSTALLERS[family];
    if (inst) and.push({ source: { in: [...inst.sources] } });
    and.push({ NOT: { serverSide: "unsupported" } });
    if (family === "minecraft") {
      const acc = acceptedLoaders(server.gameVariant ?? "vanilla");
      and.push({ category: { notIn: CLIENT_ONLY } });
      and.push({ OR: [{ loaders: { hasSome: [...acc, "datapack"] } }, { category: "Datapacks" }, { loaders: { isEmpty: true } }] });
      if (facts.pinnedVersion) and.push({ OR: [{ gameVersions: { has: facts.pinnedVersion } }, { gameVersions: { isEmpty: true } }] });
      if (!acc.length) and.push({ OR: [{ category: "Datapacks" }, { loaders: { has: "datapack" } }] });
    }
  }
  const where: Prisma.GameModWhereInput = { AND: and };
  const orderBy: Prisma.GameModOrderByWithRelationInput[] =
    query.sort === "name" ? [{ name: "asc" }]
    : query.sort === "updated" ? [{ upstreamUpdatedAt: { sort: "desc", nulls: "last" } }, { name: "asc" }]
    : query.sort === "light" ? [{ fileBytes: { sort: "asc", nulls: "last" } }, { downloads: { sort: "desc", nulls: "last" } }]
    : [{ featured: "desc" }, { downloads: { sort: "desc", nulls: "last" } }, { popularity: "desc" }, { name: "asc" }];

  const [total, rows, states] = await Promise.all([
    db.gameMod.count({ where }),
    db.gameMod.findMany({ where, orderBy, skip: (page - 1) * PAGE_SIZE, take: PAGE_SIZE }),
    db.serverMod.findMany({ where: { serverId }, select: { modId: true, status: true, version: true, error: true } }),
  ]);
  const st = new Map(states.map((s) => [s.modId, s]));
  return { items: rows.map((m) => toPanel(family, m, facts, st.get(m.id))), total, page, pageSize: PAGE_SIZE };
}

/** What installing this mod would pull in — resolved live against its source. */
export async function previewModInstall(serverId: string, modId: string): Promise<
  { ok: true; packages: { name: string; version: string; root: boolean; size: number | null }[]; notes: string[]; restartRequired: boolean; exact: boolean } | { ok: false; error: string }
> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { ok: false, error: "This server doesn't support mods." };
  const mod = await db.gameMod.findUnique({ where: { id: modId } });
  if (!mod || mod.gameFamily !== family) return { ok: false, error: "That mod isn't for this game." };
  const inst = engineInstallerFor(family, mod.source);
  if (!inst) {
    return { ok: true, packages: [{ name: mod.name, version: "latest", root: true, size: mod.fileBytes }], notes: [familyCoverage(family).mode === "legacy" ? "Dependencies for this game are handled by the game itself or checked on the server." : ""].filter(Boolean), restartRequired: true, exact: false };
  }
  if (throttled(user.id, "mod-preview", 30)) return { ok: false, error: "Too many previews in a minute — try again shortly." };
  const facts = serverFacts(server, family);
  // Without the guest we only know the pinned version; installers that need the
  // live version (Factorio) say so and the real check happens on the server.
  const guess = { base: "/opt/preview", dirs: { plugins: "/opt/preview/p", mods: "/opt/preview/m", datapacks: "/opt/preview/d" }, gameVersion: facts.pinnedVersion };
  const r = await previewResolve(inst, catalogFacts(mod), facts, safeFetch, guess);
  if (!r.ok) return { ok: false, error: r.error };
  return { ...r, exact: !!facts.pinnedVersion };
}

async function act(serverId: string, modId: string, op: ModOp): Promise<{ ok?: true; error?: string; jobId?: string }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (server.status !== "RUNNING") return { error: "Start the server's VM first — mods are installed onto the running server." };
  const mod = await db.gameMod.findUnique({ where: { id: modId } });
  if (!mod) return { error: "That mod is unavailable." };
  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
  if (op === "install") {
    if (!mod.active || !mod.upstreamOk) return { error: "That mod is no longer available upstream." };
    const sup = installSupport(family, mod.source);
    if (!sup.ok) return { error: sup.message };
    const c = compatFor(family, mod, serverFacts(server, family));
    if (c.verdict === "unsupported") return { error: c.detail };
  }
  if ((op === "update" || op === "disable" || op === "enable") && !engineInstallerFor(family, mod.source)) {
    return { error: "That action isn't available for this game yet." };
  }
  const r = await enqueueModOp(serverId, modId, op, { userId: user.id, slug: mod.slug });
  if (!r.ok) return { error: r.error };
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true, jobId: r.jobId };
}

export async function panelInstallMod(serverId: string, modId: string) { return act(serverId, modId, "install"); }
export async function panelRemoveMod(serverId: string, modId: string) { return act(serverId, modId, "remove"); }
export async function panelUpdateMod(serverId: string, modId: string) { return act(serverId, modId, "update"); }
export async function panelDisableMod(serverId: string, modId: string) { return act(serverId, modId, "disable"); }
export async function panelEnableMod(serverId: string, modId: string) { return act(serverId, modId, "enable"); }

/** Latest upstream version for each installed engine mod (on demand, capped). */
export async function checkModUpdates(serverId: string): Promise<{ error?: string; updates?: Record<string, string | null> }> {
  const { user, server, family } = await ownedServer(serverId);
  if (!family) return { error: "This server doesn't support mods." };
  if (throttled(user.id, "mod-updates", 4)) return { error: "Checked very recently — try again in a minute." };
  const rows = await db.serverMod.findMany({ where: { serverId, status: { in: ["INSTALLED", "DISABLED"] } }, include: { mod: true }, take: 15 });
  const facts = serverFacts(server, family);
  const out: Record<string, string | null> = {};
  const guess = { base: "/opt/preview", dirs: { plugins: "/opt/preview/p", mods: "/opt/preview/m", datapacks: "/opt/preview/d" }, gameVersion: facts.pinnedVersion };
  let i = 0;
  const work = rows.filter((r) => engineInstallerFor(family, r.mod.source));
  await Promise.all(
    Array.from({ length: 3 }, async () => {
      while (i < work.length) {
        const r = work[i++];
        const inst = engineInstallerFor(family, r.mod.source)!;
        const p = await previewResolve(inst, catalogFacts(r.mod), facts, safeFetch, guess).catch(() => null);
        const root = p && p.ok ? p.packages.find((x) => x.root) : null;
        out[r.modId] = root ? root.version : null;
      }
    }),
  );
  return { updates: out };
}

