  modId: string
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);
  const family = familyFor(server);
  if (!family) return { error: "This server doesn't support mods." };

  const mod = await db.gameMod.findUnique({ where: { id: modId } });
  if (!mod || !mod.active) return { error: "That mod is unavailable." };
  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
  }

  /* Refuse here rather than queue a GAME_MOD_SYNC that can only come back
     "auto-install isn't wired for this game". The panel already hides the
     button for these, so reaching this is a stale page or a direct call — but
     an unrunnable job would still take the server's one in-flight slot. */
  const support = installSupport(family, mod.source);
  if (!support.ok) return { error: support.message };

  // Check-then-enqueue under the per-server lock, shared with the Mods tab
  // (lib/mods/queue.ts) — one in-flight job per server, audit-logged.
  const queued = await enqueueModOp(serverId, modId, "install", { userId: user.id, slug: mod.slug });
  if (!queued.ok) return { error: queued.error };

