"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import {
  checkModUpdates,
  getModsOverview,
  panelDisableMod,
  panelEnableMod,
  panelInstallMod,
  panelRemoveMod,
  panelUpdateMod,
  previewModInstall,
  searchModCatalog,
  type CatalogQuery,
  type InstallPreview,
  type ModsOverview,
  type PanelMod,
} from "@/lib/actions-mod-installs";
import { gamePower } from "@/lib/actions-game-control";
import type { ModLoad } from "@/lib/mod-load";

/**
 * Mods & Plugins — the real catalogue, searched server-side, installed by the
 * per-game installers in lib/mods/installers/*.
 *
 * What's on this tab and where each fact comes from:
 *  - the catalogue: GameMod rows for this game, searched/filtered/paged in the
 *    DB (all of them — Minecraft alone is 30k+), with a compatibility badge
 *    computed by the game's installer for THIS server's loader + version;
 *  - "what will be installed": a live dependency resolve against the mod's own
 *    source (Modrinth/Thunderstore/uMod/GitHub/Factorio portal) before the
 *    customer confirms;
 *  - progress: the GAME_MOD_SYNC job's own step/progress columns;
 *  - restart prompt: the last mod job's result vs. the last power job;
 *  - every number (downloads, size, dependencies) is the source's own, or
 *    absent — never estimated.
 *
 * A change the worker could not apply comes back as a failure with its reason.
 * There is no path on this tab that shows success the worker didn't report.
 */

const SOURCE_LABEL: Record<string, string> = {
  modrinth: "Modrinth", spigotmc: "SpigotMC", hangar: "Hangar", curseforge: "CurseForge", steam_workshop: "Steam Workshop",
  umod: "uMod", github: "GitHub", nexus: "Nexus Mods", thunderstore: "Thunderstore", codefling: "Codefling", mod_io: "mod.io",
  vintagestory_moddb: "Vintage Story ModDB", factorio_portal: "Factorio Mod Portal", ficsit: "ficsit.app", reforger_workshop: "Arma Reforger Workshop",
};

const PLUGIN_CATS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport", "plugins"];

function fileSize(bytes: number | null): string | null {
  if (!bytes || bytes <= 0) return null;
  return bytes >= 1024 ** 3 ? `${(bytes / 1024 ** 3).toFixed(1)} GB` : bytes >= 1024 * 1024 ? `${Math.round(bytes / 1024 / 1024)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`;
}
function downloadCount(n: number | null): string | null {
  if (!n || n < 1) return null;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M downloads`;
  if (n >= 1_000) return `${Math.round(n / 1000)}k downloads`;
  return `${n} downloads`;
}

const STATE: Record<string, { label: string; cls: string }> = {
  INSTALLED: { label: "Installed", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
  DISABLED: { label: "Disabled", cls: "border-white/20 bg-white/[0.06] text-tx-dim" },
  INSTALLING: { label: "Installing", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  UPDATING: { label: "Updating", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  ENABLING: { label: "Enabling", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  DISABLING: { label: "Disabling", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  REMOVING: { label: "Removing", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  FAILED: { label: "Failed", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
};
const PENDING = new Set(["INSTALLING", "UPDATING", "ENABLING", "DISABLING", "REMOVING"]);

const COMPAT: Record<string, { icon: string; cls: string; label: string }> = {
  ok: { icon: "checkcircle", cls: "border-emerald-500/35 bg-emerald-500/10 text-emerald-300", label: "Compatible" },
  mismatch: { icon: "warntriangle", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300", label: "Not for this server" },
  unknown: { icon: "warncircle", cls: "border-white/15 bg-white/[0.05] text-tx-dim", label: "Checked at install" },
  unsupported: { icon: "xcircle", cls: "border-red-500/35 bg-red-500/10 text-red-300", label: "Can't run on a server" },
};

const LOAD_STYLE: Record<string, { ring: string; ink: string; icon: string; label: string }> = {
  fine: { ring: "border-rim-hi bg-well", ink: "text-tx-dim", icon: "checkcircle", label: "Load looks fine" },
  watch: { ring: "border-sky-500/35 bg-sky-500/[0.07]", ink: "text-sky-300", icon: "warncircle", label: "Worth watching" },
  high: { ring: "border-amber-500/45 bg-amber-500/[0.09]", ink: "text-amber-300", icon: "warntriangle", label: "Heavy for this tier" },
};

function LoadBanner({ load }: { load: ModLoad }) {
  if (load.count === 0) return null;
  const st = LOAD_STYLE[load.level];
  return (
    <div className={"flex flex-wrap items-start gap-3.5 rounded-[14px] border px-4 py-3.5 " + st.ring}>
      <span className={"grid h-[32px] w-[32px] flex-none place-items-center rounded-[10px] border border-white/10 bg-white/[0.05] " + st.ink}>
        <Icon name={st.icon} size={15} tone="inherit" />
      </span>
      <div className="min-w-0 flex-1">
        <p className={"text-[13px] font-bold " + st.ink}>{st.label}</p>
        <p className="mt-0.5 text-[12.5px] leading-relaxed text-tx-dim">{load.headline}</p>
        {load.advice && <p className="mt-1.5 max-w-[74ch] text-[12px] leading-relaxed text-tx-faint">{load.advice}</p>}
      </div>
      {load.percentOfRam !== null && (
        <div className="flex flex-none flex-col items-end">
          <span className={"num text-[19px] font-extrabold leading-none " + st.ink}>{load.percentOfRam}%</span>
          <span className="mt-1 text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">of RAM, on disk</span>
        </div>
      )}
    </div>
  );
}

function ModIcon({ m, size = 40 }: { m: PanelMod; size?: number }) {
  return (
    <span className="grid flex-none place-items-center overflow-hidden rounded-[11px] border border-rim-hi bg-well" style={{ width: size, height: size }}>
      {m.iconUrl
        /* eslint-disable-next-line @next/next/no-img-element -- upstream mod icon */
        ? <img src={m.iconUrl} alt="" loading="lazy" className="h-full w-full object-cover" />
        : <Icon name="cube" size={Math.round(size * 0.42)} />}
    </span>
  );
}

function Chip({ cls, icon, children, title }: { cls: string; icon?: string; children: React.ReactNode; title?: string }) {
  return (
    <span title={title} className={"inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide " + cls}>
      {icon && <Icon name={icon} size={10} tone="inherit" />}
      {children}
    </span>
  );
}

const btnGhost = "rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50";

export function ModsPanel({ serverId, scope }: { serverId: string; scope: "mods" | "plugins" }) {
  const [ov, setOv] = useState<ModsOverview | null>(null);
  const [fatal, setFatal] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<"browse" | "installed">("browse");
  const [q, setQ] = useState("");
  const [debQ, setDebQ] = useState("");
  const [category, setCategory] = useState("all");
  const [sort, setSort] = useState<NonNullable<CatalogQuery["sort"]>>("popular");
  const [compatibleOnly, setCompatibleOnly] = useState(true);
  const [items, setItems] = useState<PanelMod[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [searching, setSearching] = useState(false);
  const [confirm, setConfirm] = useState<PanelMod | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [updates, setUpdates] = useState<Record<string, string | null> | null>(null);
  const [checking, setChecking] = useState(false);
  const [restarting, setRestarting] = useState(false);
  const [, start] = useTransition();
  const searchSeq = useRef(0);

  const loadOverview = useCallback(async () => {
    const r = await getModsOverview(serverId).catch(() => ({ error: "Couldn't load your mods." }) as { error: string });
    if ("view" in r && r.view) {
      setOv(r.view);
      setFatal(null);
    } else if ("error" in r && r.error) setFatal(r.error);
  }, [serverId]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);

  // Debounce typing.
  useEffect(() => {
    const t = setTimeout(() => setDebQ(q), 300);
    return () => clearTimeout(t);
  }, [q]);

  // Plugins view = the catalogue's admin-ish categories (a filter, said plainly).
  const pluginCategory = useMemo(() => {
    if (scope !== "plugins" || !ov) return null;
    return ov.categories.find((c) => PLUGIN_CATS.some((k) => c.category.toLowerCase().includes(k)))?.category ?? null;
  }, [scope, ov]);
  useEffect(() => {
    if (pluginCategory) setCategory(pluginCategory);
  }, [pluginCategory]);

  const runSearch = useCallback(
    async (p: number, append: boolean) => {
      const seq = ++searchSeq.current;
      setSearching(true);
      const r = await searchModCatalog(serverId, { q: debQ, category, sort, compatibleOnly, page: p }).catch(() => ({ error: "Search failed — try again." }) as { error: string });
      if (seq !== searchSeq.current) return;
      setSearching(false);
      if ("items" in r && r.items) {
        setItems((prev) => (append ? [...prev, ...r.items!] : r.items!));
        setTotal(r.total ?? 0);
        setPage(p);
      } else if ("error" in r && r.error) setError(r.error);
    },
    [serverId, debQ, category, sort, compatibleOnly],
  );

  useEffect(() => {
    if (ov && ov.coverage.mode !== "unavailable") void runSearch(1, false);
    else if (ov) void runSearch(1, false);
  }, [ov?.family, runSearch]); // eslint-disable-line react-hooks/exhaustive-deps -- re-run on query change, not every overview poll

  // Follow the job while one is queued/running, then refresh the page of results once.
  const active = !!ov?.job || (ov?.installed ?? []).some((m) => m.status && PENDING.has(m.status));
  const wasActive = useRef(false);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) {
        wasActive.current = false;
        void runSearch(1, false);
      }
      return;
    }
    wasActive.current = true;
    const t = setInterval(() => void loadOverview(), 3000);
    return () => clearInterval(t);
  }, [active, loadOverview, runSearch]);

  const act = (m: PanelMod, op: "install" | "remove" | "update" | "disable" | "enable") =>
    start(async () => {
      setBusyId(m.id);
      setConfirm(null);
      setError(null);
      const fn = { install: panelInstallMod, remove: panelRemoveMod, update: panelUpdateMod, disable: panelDisableMod, enable: panelEnableMod }[op];
      const r = await fn(serverId, m.id).catch(() => ({ error: "Couldn't reach the server." }) as { error: string });
      if (r && "error" in r && r.error) setError(r.error);
      await loadOverview();
      setBusyId(null);
    });

  const restartNow = () =>
    start(async () => {
      setRestarting(true);
      setError(null);
      const r = await gamePower(serverId, "restart").catch(() => ({ ok: false as const, error: "Couldn't reach the server." }));
      if (!r.ok) setError(r.error);
      await loadOverview();
      setRestarting(false);
    });

  const doCheckUpdates = () =>
    start(async () => {
      setChecking(true);
      const r = await checkModUpdates(serverId).catch(() => ({ error: "Couldn't check for updates." }) as { error: string });
      if ("updates" in r && r.updates) setUpdates(r.updates);
      else if ("error" in r && r.error) setError(r.error);
      setChecking(false);
    });

  if (!ov && !fatal) {
    return <div className="rounded-[16px] border border-rim-hi bg-well px-6 py-16 text-center text-[13px] text-tx-dim">Loading mods…</div>;
  }
  if (!ov) {
    return (
      <div className="rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-14 text-center">
        <Icon name="cube" size={28} className="mx-auto" />
        <p className="mt-3 text-[14.5px] font-bold text-white">Mods aren&apos;t available for this game</p>
        <p className="mx-auto mt-1.5 max-w-[52ch] text-[12.5px] leading-relaxed text-tx-dim">{fatal}</p>
      </div>
    );
  }

  const unavailable = ov.coverage.mode === "unavailable";
  const installedVisible = ov.installed.filter((m) => m.status !== "REMOVED");

  return (
    <div className="flex flex-col gap-4">
      {/* ── banner ───────────────────────────────────────────────────── */}
      <div className="nx-dark-island overflow-hidden rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(140deg,rgba(90,40,200,.35),rgba(20,36,110,.28)_58%,rgba(4,12,34,.5))] p-4 sm:p-5">
        <div className="flex flex-wrap items-start gap-4 sm:gap-5">
          <span className="grid h-[48px] w-[48px] flex-none place-items-center rounded-[14px] border border-white/15 bg-white/10">
            <Icon name="cube" size={21} tone="inherit" className="text-fuchsia-300" />
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-2">
              <h2 className="text-[19px] font-extrabold tracking-[-0.02em] text-white">Mods &amp; Plugins</h2>
              {unavailable ? (
                <Chip cls="border-white/20 bg-white/[0.07] text-white/70">Manual install</Chip>
              ) : (
                <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200" icon="bolt">One-click</Chip>
              )}
            </div>
            <p className="mt-1.5 max-w-[68ch] text-[12.5px] leading-relaxed text-white/75">
              {unavailable
                ? ov.coverage.text
                : <>Search the full {ov.familyName} catalogue and install in one click. We fetch the right build for your server from the mod&apos;s own source, check it, pull in its dependencies and back up anything it changes. <span className="text-white/55">{ov.coverage.text}</span></>}
            </p>
            <p className="mt-2 flex flex-wrap items-center gap-2 text-[11.5px] text-white/60">
              <span className="rounded-[6px] border border-white/15 bg-white/[0.07] px-2 py-0.5 font-semibold text-white/85">
                {ov.variant ?? "server"}{ov.gameVersion ? ` · ${ov.gameVersion}` : ""}
              </span>
              compatibility is checked against this
            </p>
          </div>
          <dl className="flex flex-none gap-6">
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Installed</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{installedVisible.length}</dd>
            </div>
            <div className="flex flex-col">
              <dt className="text-[10px] font-bold uppercase tracking-[0.14em] text-white/50">Catalogue</dt>
              <dd className="num text-[22px] font-extrabold leading-none text-white">{ov.catalogTotal.toLocaleString()}</dd>
            </div>
          </dl>
        </div>
      </div>

      {/* ── job progress ─────────────────────────────────────────────── */}
      {ov.job && (
        <div className="rounded-[14px] border border-sky-500/35 bg-sky-500/[0.07] px-4 py-3" role="status" aria-live="polite">
          <div className="flex items-center gap-2.5">
            <Icon name="refresh" size={14} tone="inherit" className="animate-spin text-sky-300" />
            <p className="min-w-0 flex-1 truncate text-[12.5px] font-semibold text-sky-200">
              {ov.job.status === "QUEUED" ? "Queued — waiting for the server to be free" : ov.job.step ?? "Working…"}
            </p>
            <span className="num text-[12px] font-bold text-sky-300">{ov.job.progress}%</span>
          </div>
          <div className="mt-2 h-[5px] overflow-hidden rounded-full bg-white/[0.08]">
            <div className="h-full rounded-full bg-[linear-gradient(90deg,#3b6be8,#7b3fef)] transition-all duration-700" style={{ width: `${Math.max(4, ov.job.progress)}%` }} />
          </div>
        </div>
      )}

      {/* ── restart prompt ───────────────────────────────────────────── */}
      {!ov.job && ov.restart.required && (
        <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/45 bg-amber-500/[0.09] px-4 py-3.5">
          <Icon name="warntriangle" size={16} tone="inherit" className="text-amber-300" />
          <div className="min-w-0 flex-1">
            <p className="text-[13px] font-bold text-amber-200">Restart to load your mod changes</p>
            {ov.restart.changed.length > 0 && (
              <p className="mt-0.5 line-clamp-2 text-[12px] text-amber-200/75">{ov.restart.changed.slice(0, 6).join(" · ")}</p>
            )}
          </div>
          <button type="button" onClick={restartNow} disabled={restarting || !ov.serverRunning} className="nx-cta px-4 py-2 text-[12.5px] disabled:opacity-50">
            {restarting ? "Restarting…" : "Restart now"}
          </button>
        </div>
      )}

      <LoadBanner load={ov.load} />

      {error && (
        <p className="rounded-[11px] border border-red-500/35 bg-red-500/10 px-3.5 py-2.5 text-[12.5px] text-red-300" role="alert">{error}</p>
      )}

      {/* ── tabs ─────────────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center gap-2.5">
        <div className="flex gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
          {([["browse", `Browse (${total.toLocaleString()})`], ["installed", `Installed (${installedVisible.length})`]] as const).map(([k, label]) => (
            <button key={k} type="button" onClick={() => setTab(k)} aria-pressed={tab === k}
              className={"rounded-[8px] px-3.5 py-1.5 text-[12.5px] font-semibold transition " + (tab === k ? "bg-[#7b3fef]/25 text-white" : "text-tx-dim hover:text-white")}>
              {label}
            </button>
          ))}
        </div>
        {tab === "installed" && ov.coverage.canUpdate && installedVisible.length > 0 && (
          <button type="button" onClick={doCheckUpdates} disabled={checking} className={btnGhost + " ml-auto flex items-center gap-1.5"}>
            <Icon name="refresh2" size={12} tone="inherit" /> {checking ? "Checking…" : "Check for updates"}
          </button>
        )}
      </div>

      {tab === "browse" ? (
        <>
          <div className="flex flex-wrap items-center gap-2.5">
            <span className="flex h-[40px] min-w-[200px] flex-[2_1_260px] items-center gap-2.5 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5">
              <Icon name="search" size={14} tone="inherit" className="flex-none text-tx-faint" />
              <input value={q} onChange={(e) => setQ(e.target.value)} placeholder={`Search ${ov.catalogTotal.toLocaleString()} ${scope}…`} aria-label="Search the catalogue"
                className="min-w-0 flex-1 bg-transparent text-[12.5px] text-white outline-none placeholder:text-tx-faint" />
              {searching && <Icon name="refresh" size={12} tone="inherit" className="animate-spin text-tx-faint" />}
            </span>
            {ov.categories.length > 1 && (
              <span className="flex h-[40px] flex-[1_1_150px] items-center rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3">
                <select value={category} onChange={(e) => setCategory(e.target.value)} aria-label="Filter by category" className="w-full cursor-pointer bg-transparent text-[12.5px] font-semibold text-tx-dim outline-none">
                  <option value="all">All categories</option>
                  {ov.categories.slice(0, 60).map((c) => <option key={c.category} value={c.category}>{c.category} ({c.count.toLocaleString()})</option>)}
                </select>
              </span>
            )}
            <span className="flex h-[40px] flex-[1_1_140px] items-center rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3">
              <select value={sort} onChange={(e) => setSort(e.target.value as typeof sort)} aria-label="Sort" className="w-full cursor-pointer bg-transparent text-[12.5px] font-semibold text-tx-dim outline-none">
                <option value="popular">Most downloaded</option>
                <option value="updated">Recently updated</option>
                <option value="light">Smallest first</option>
                <option value="name">Name</option>
              </select>
            </span>
            {!unavailable && (
              <label className="flex h-[40px] cursor-pointer items-center gap-2 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3 text-[12px] font-semibold text-tx-dim">
                <input type="checkbox" checked={compatibleOnly} onChange={(e) => setCompatibleOnly(e.target.checked)} className="accent-[#7b3fef]" />
                Works on this server
              </label>
            )}
          </div>

          {items.length === 0 && !searching ? (
            <p className="rounded-[14px] border border-rim-hi bg-well px-5 py-10 text-center text-[12.5px] text-tx-faint">
              {debQ || category !== "all" ? `No ${scope} match that search${compatibleOnly && !unavailable ? " for this server — try turning off “Works on this server”" : ""}.` : `Nothing in the catalogue for ${ov.familyName} yet.`}
            </p>
          ) : (
            <div className="grid gap-2.5 lg:grid-cols-2">
              {items.map((m) => (
                <CatalogCard key={m.id} m={m} unavailable={unavailable} busy={busyId === m.id || !!ov.job} onInstall={() => setConfirm(m)} />
              ))}
            </div>
          )}

          {items.length < total && (
            <button type="button" onClick={() => void runSearch(page + 1, true)} disabled={searching}
              className="mx-auto rounded-[11px] border border-rim-hi bg-well px-5 py-2.5 text-[12.5px] font-semibold text-tx-dim transition hover:border-brand-400/45 hover:text-white disabled:opacity-50">
              {searching ? "Loading…" : `Show more — ${(total - items.length).toLocaleString()} left`}
            </button>
          )}
        </>
      ) : installedVisible.length === 0 ? (
        <p className="rounded-[14px] border border-rim-hi bg-well px-5 py-10 text-center text-[12.5px] text-tx-faint">Nothing installed yet — find something in Browse.</p>
      ) : (
        <div className="flex flex-col gap-2">
          {installedVisible.map((m) => (
            <InstalledRow key={m.id} m={m} ov={ov} busy={busyId === m.id || !!ov.job} latest={updates?.[m.id]}
              onAct={(op) => act(m, op)} />
          ))}
        </div>
      )}

      <p className="text-[11.5px] leading-relaxed text-tx-faint">
        Anything not in the catalogue can still be installed by hand: upload it in the <strong className="text-tx-dim">Files</strong> tab and restart from <strong className="text-tx-dim">Console</strong>. Before changing files we keep a backup on your server in <span className="font-mono text-tx-dim">/root/.nxeon-mods/backups</span>.
      </p>

      {confirm && <InstallDialog serverId={serverId} mod={confirm} load={ov.load} onCancel={() => setConfirm(null)} onConfirm={() => act(confirm, "install")} />}
    </div>
  );
}

function CatalogCard({ m, unavailable, busy, onInstall }: { m: PanelMod; unavailable: boolean; busy: boolean; onInstall: () => void }) {
  const st = m.status ? STATE[m.status] : null;
  const cmp = COMPAT[m.compat.verdict];
  const size = fileSize(m.fileBytes);
  const dl = downloadCount(m.downloads);
  const installed = m.status === "INSTALLED" || m.status === "DISABLED" || (m.status && PENDING.has(m.status));
  return (
    <div className="flex flex-col gap-2.5 rounded-[14px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-3.5 transition hover:border-brand-400/40">
      <div className="flex items-start gap-3">
        <ModIcon m={m} />
        <div className="flex min-w-0 flex-1 flex-col">
          <div className="flex flex-wrap items-center gap-1.5">
            <span className="truncate text-[13.5px] font-bold text-white">{m.name}</span>
            {m.featured && <Chip cls="border-[#a86bff]/45 bg-[#a86bff]/12 text-[#c4a6ff]">Featured</Chip>}
            {st && <Chip cls={st.cls}>{st.label}</Chip>}
          </div>
          <span className="mt-0.5 truncate text-[11.5px] text-tx-faint">
            {m.authorName ? `${m.authorName} · ` : ""}{m.category} ·{" "}
            {m.url ? <a href={m.url} target="_blank" rel="noreferrer noopener" className="transition hover:text-white">{SOURCE_LABEL[m.source] ?? m.source} ↗</a> : (SOURCE_LABEL[m.source] ?? m.source)}
          </span>
        </div>
      </div>
      {m.description && <p className="line-clamp-2 text-[12px] leading-relaxed text-tx-dim">{m.description}</p>}
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 text-[11.5px] text-tx-faint">
        {dl && <span className="num">{dl}</span>}
        {size && <span className="num">{size}</span>}
        {m.dependencyCount > 0 && <span>+{m.dependencyCount} dependenc{m.dependencyCount === 1 ? "y" : "ies"}</span>}
        {m.impact === "heavy" && <Chip cls="border-amber-500/45 bg-amber-500/12 text-amber-300">Heavy</Chip>}
        {!unavailable && <Chip cls={cmp.cls} icon={cmp.icon} title={m.compat.detail}>{cmp.label}</Chip>}
      </div>
      {!unavailable && m.compat.verdict !== "ok" && m.compat.verdict !== "unknown" && (
        <p className="rounded-[9px] border border-amber-500/30 bg-amber-500/[0.07] px-2.5 py-1.5 text-[11.5px] leading-snug text-amber-300">{m.compat.detail}</p>
      )}
      {m.status === "FAILED" && m.error && (
        <p className="rounded-[9px] border border-red-500/30 bg-red-500/[0.07] px-2.5 py-1.5 text-[11.5px] leading-snug text-red-300">{m.error}</p>
      )}
      <div className="mt-auto flex flex-wrap items-center gap-2 pt-0.5">
        {installed ? (
          <span className="text-[11.5px] text-tx-faint">Manage it under Installed.</span>
        ) : m.manualInstall ? (
          <>
            {m.url && <a href={m.url} target="_blank" rel="noreferrer noopener" className={btnGhost}>Download ↗</a>}
            <span className="min-w-0 flex-1 text-[11.5px] leading-snug text-tx-faint">{m.manualInstall}</span>
          </>
        ) : (
          <button type="button" disabled={busy} onClick={onInstall} className="nx-cta px-4 py-1.5 text-[12.5px] disabled:opacity-50">
            {m.status === "FAILED" ? "Try again" : "Install"}
          </button>
        )}
        {m.paid && <span className="text-[11.5px] text-amber-300">Paid upstream — you supply the licence</span>}
      </div>
    </div>
  );
}

function InstalledRow({ m, ov, busy, latest, onAct }: { m: PanelMod; ov: ModsOverview; busy: boolean; latest: string | null | undefined; onAct: (op: "remove" | "update" | "disable" | "enable") => void }) {
  const st = m.status ? STATE[m.status] : null;
  const pending = !!m.status && PENDING.has(m.status);
  const hasUpdate = !!latest && !!m.version && latest !== m.version;
  return (
    <div className="flex flex-col gap-2 rounded-[14px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))] p-3.5 sm:flex-row sm:items-center">
      <div className="flex min-w-0 flex-1 items-center gap-3">
        <ModIcon m={m} size={36} />
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-1.5">
            <span className="truncate text-[13.5px] font-bold text-white">{m.name}</span>
            {st && <Chip cls={st.cls}>{st.label}</Chip>}
            {hasUpdate && <Chip cls="border-cyan-400/40 bg-cyan-400/10 text-cyan-200">Update: {latest}</Chip>}
          </div>
          <p className="mt-0.5 truncate text-[11.5px] text-tx-faint">
            {m.version ? `v${m.version} · ` : ""}{SOURCE_LABEL[m.source] ?? m.source}
            {latest === null && m.version ? " · couldn't check for updates" : latest && !hasUpdate ? " · up to date" : ""}
          </p>
          {m.error && <p className="mt-1 text-[11.5px] leading-snug text-red-300">{m.error}</p>}
        </div>
      </div>
      <div className="flex flex-none flex-wrap items-center gap-2">
        {ov.coverage.canUpdate && m.status === "INSTALLED" && (
          <button type="button" disabled={busy || pending} onClick={() => onAct("update")} className={btnGhost}>Update</button>
        )}
        {ov.coverage.canToggle && m.status === "INSTALLED" && (
          <button type="button" disabled={busy || pending} onClick={() => onAct("disable")} className={btnGhost}>Disable</button>
        )}
        {ov.coverage.canToggle && m.status === "DISABLED" && (
          <button type="button" disabled={busy || pending} onClick={() => onAct("enable")} className={btnGhost}>Enable</button>
        )}
        {(m.status === "INSTALLED" || m.status === "DISABLED" || m.status === "FAILED") && (
          <button type="button" disabled={busy || pending} onClick={() => onAct("remove")}
            className="rounded-[10px] border border-rim-hi px-3 py-1.5 text-[12px] font-semibold text-tx-dim transition hover:border-red-500/50 hover:text-red-300 disabled:opacity-50">
            {m.status === "FAILED" ? "Clear" : "Remove"}
          </button>
        )}
        {pending && <span className="text-[11.5px] text-sky-300">{st?.label}…</span>}
      </div>
    </div>
  );
}

/**
 * Confirm an install after showing exactly what will be pulled in, resolved
 * live against the mod's own source for this server. If that resolve says it
 * can't work (no build for this version), Install is not offered.
 */
function InstallDialog({ serverId, mod, load, onCancel, onConfirm }: { serverId: string; mod: PanelMod; load: ModLoad; onCancel: () => void; onConfirm: () => void }) {
  const [pv, setPv] = useState<InstallPreview | null>(null);
  useEffect(() => {
    let live = true;
    previewModInstall(serverId, mod.id)
      .then((r) => live && setPv(r))
      .catch(() => live && setPv({ ok: false, error: "Couldn't reach the mod's source to preview dependencies." }));
    return () => { live = false; };
  }, [serverId, mod.id]);
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onCancel();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onCancel]);

  const mismatch = mod.compat.verdict === "mismatch";
  const blocked = pv && !pv.ok && /no build|has no|isn't|needs|client-side|Switch|switch/i.test(pv.error);
  const deps = pv && pv.ok ? pv.packages.filter((p) => !p.root) : [];
  const root = pv && pv.ok ? pv.packages.find((p) => p.root) : null;
  const totalBytes = pv && pv.ok ? pv.packages.reduce((s, p) => s + (p.size ?? 0), 0) : 0;

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/65 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={`Install ${mod.name}`} onClick={(e) => e.target === e.currentTarget && onCancel()}>
      <div className="nx-dark-island max-h-[88vh] w-full max-w-[480px] overflow-y-auto rounded-[17px] border border-[#7b3fef]/40 bg-[linear-gradient(180deg,rgba(14,26,56,.97),rgba(3,9,24,.98))] p-5">
        <div className="flex items-start gap-3">
          <ModIcon m={mod} size={42} />
          <div className="min-w-0">
            <h3 className="text-[15.5px] font-extrabold text-white">Install {mod.name}</h3>
            <p className="mt-0.5 text-[12px] text-tx-faint">{SOURCE_LABEL[mod.source] ?? mod.source}{root ? ` · ${root.version}` : ""}</p>
          </div>
        </div>

        <div className="mt-4 flex flex-col gap-2.5">
          {!pv && (
            <p className="flex items-center gap-2 rounded-[10px] border border-rim-hi bg-well px-3 py-2.5 text-[12.5px] text-tx-dim">
              <Icon name="refresh" size={12} tone="inherit" className="animate-spin" /> Checking which build and dependencies your server needs…
            </p>
          )}
          {pv && pv.ok && (
            <div className="rounded-[11px] border border-rim-hi bg-well px-3 py-2.5">
              <p className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Will be installed</p>
              <ul className="mt-1.5 flex flex-col gap-1">
                {[...(root ? [root] : []), ...deps].map((p) => (
                  <li key={p.name + p.version} className="flex items-center justify-between gap-3 text-[12.5px]">
                    <span className="min-w-0 truncate text-white">{p.name}{!p.root && <span className="ml-1.5 text-[10.5px] font-semibold uppercase tracking-wide text-tx-faint">dependency</span>}</span>
                    <span className="num flex-none text-tx-faint">{p.version}{fileSize(p.size) ? ` · ${fileSize(p.size)}` : ""}</span>
                  </li>
                ))}
              </ul>
              {totalBytes > 0 && <p className="mt-1.5 text-[11.5px] text-tx-faint">Total download {fileSize(totalBytes)}.</p>}
              {!pv.exact && <p className="mt-1.5 text-[11.5px] text-tx-faint">Your server isn&apos;t pinned to a version, so the exact build is chosen on the server at install time.</p>}
            </div>
          )}
          {pv && pv.ok && pv.notes.filter(Boolean).map((n) => <p key={n} className="text-[11.5px] leading-relaxed text-tx-faint">{n}</p>)}
          {pv && !pv.ok && (
            <p className={"rounded-[10px] border px-3 py-2 text-[12.5px] leading-relaxed " + (blocked ? "border-red-500/35 bg-red-500/[0.08] text-red-300" : "border-amber-500/30 bg-amber-500/[0.07] text-amber-300")}>
              {pv.error}{!blocked && " It will be checked again on your server when you install."}
            </p>
