input.content:
/**
 * Real-artifact check for lib/mods/installers/*: resolves and installs REAL
 * public mods from their real sources (Modrinth, Thunderstore, uMod, GitHub)
 * into a throwaway fake guest under the OS temp dir, through the exact engine
 * the worker runs, then uninstalls them. Touches no server and no database.
 *
 *   npx tsx scripts/verify-mod-installers.ts            # all cases
 *   npx tsx scripts/verify-mod-installers.ts minecraft  # one family
 *
 * Prints every file each install placed, so the path logic can be eyeballed
 * against what the game expects.
 */
import { mkdtempSync, rmSync, readdirSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { LocalGuestFs, seedSandboxGuest } from "../lib/mods/guest-fs";
import { installOrUpdate, uninstall, loadState } from "../lib/mods/engine";
import { safeFetch } from "../lib/mods/safe-fetch";
import { ENGINE_INSTALLERS } from "../lib/mods/installers";
import type { CatalogFacts, ServerFacts } from "../lib/mods/types";

type Case = { family: string; variant: string; pinned: string | null; mod: Partial<CatalogFacts> & { source: string; sourceId: string; name: string } };

const CASES: Case[] = [
  { family: "minecraft", variant: "paper", pinned: "1.21.1", mod: { source: "modrinth", sourceId: "luckperms", name: "LuckPerms", category: "Plugins" } },
  { family: "minecraft", variant: "fabric", pinned: "1.21.1", mod: { source: "modrinth", sourceId: "ledger", name: "Ledger", category: "Mods" } },
  { family: "minecraft", variant: "vanilla", pinned: "1.21.1", mod: { source: "modrinth", sourceId: "terralith", name: "Terralith", category: "Datapacks" } },
  { family: "valheim", variant: "bepinex", pinned: null, mod: { source: "thunderstore", sourceId: "Tekla-AutoRepair", name: "AutoRepair" } },
  { family: "valheim", variant: "bepinex", pinned: null, mod: { source: "thunderstore", sourceId: "ValheimModding-Jotunn", name: "Jotunn" } },
  { family: "rust", variant: "oxide", pinned: null, mod: { source: "umod", sourceId: "vanish", name: "Vanish" } },
  { family: "cs2", variant: "metamod", pinned: null, mod: { source: "github", sourceId: "daffyyyy/CS2-SimpleAdmin", name: "CS2-SimpleAdmin" } },
];

function walk(dir: string, base = dir): string[] {
  const out: string[] = [];
  for (const n of readdirSync(dir)) {
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) out.push(...walk(p, base));
    else out.push("/" + path.relative(base, p));
  }
  return out;
}

(async () => {
  const only = process.argv[2];
  let failed = 0;
  for (const c of CASES.filter((x) => !only || x.family === only)) {
    const root = mkdtempSync(path.join(tmpdir(), "nxeon-verify-mods-"));
    const fs = new LocalGuestFs(root);
    await seedSandboxGuest(fs, c.family, c.variant);
    const inst = ENGINE_INSTALLERS[c.family];
    const mod: CatalogFacts = { id: `verify_${c.mod.sourceId}`, gameFamily: c.family, slug: c.mod.sourceId.toLowerCase().replace(/[^a-z0-9]+/g, "-"), url: null, category: "Mods", appliesToVariant: null, loaders: [], gameVersions: [], serverSide: null, ...c.mod };
    const server: ServerFacts = { id: "verify", family: c.family, variant: c.variant, pinnedVersion: c.pinned, config: null };
    console.log(`\n=== ${c.family}/${c.variant} — ${c.mod.name} (${c.mod.source}:${c.mod.sourceId})`);
    try {
      const r = await installOrUpdate(inst, mod, server, { fs, fetcher: safeFetch });
      if (!r.ok) {
        console.log(`  REFUSED: ${r.error}`);
      } else {
        console.log(`  ok ${r.version} restart=${r.restartRequired}`);
        for (const x of r.changed) console.log(`  - ${x}`);
        for (const n of r.notes) console.log(`  note: ${n}`);
        const placed = walk(root).filter((p) => !p.startsWith("/root/.nxeon-mods/") && !/server\.properties|latest\.log|mod-list\.json|server-settings\.json|factorio-current\.log/.test(p));
        for (const p of placed) console.log(`  + ${p}`);
        const again = await installOrUpdate(inst, mod, server, { fs, fetcher: safeFetch });
        console.log(`  re-run: ${again.ok ? `ok, changed=${again.changed.length}` : `FAILED ${again.error}`}`);
        const st = await loadState(fs, c.family);
        const un = await uninstall(inst, mod, server, { fs, fetcher: safeFetch });
        const left = walk(root).filter((p) => !p.startsWith("/root/.nxeon-mods/") && placed.includes(p));
        console.log(`  uninstall: ${un.ok ? "ok" : un.error}; packages before=${Object.keys(st.packages).length}; files left=${left.length}`);
        if (!again.ok || again.changed.length || !un.ok || left.length) failed++;
      }
    } catch (e) {
      failed++;
      console.log(`  ERROR ${(e as Error).message}`);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  }
  process.exit(failed ? 1 : 0);
})();

