  const ctx = await b.newContext({ viewport: vp, colorScheme: "dark" });
  await ctx.addCookies([{ name: "nxeon_session", value: token, domain: "localhost", path: "/" }]);
  const p = await ctx.newPage();
  const errs = [];
  p.on("pageerror", (e) => errs.push(e.message));
  for (const [tag, id] of [["mc", mc], ["vh", vh], ["pw", pw]]) {
    await p.goto(`http://localhost:3113/dashboard/servers/${id}?tab=mods`, { waitUntil: "domcontentloaded", timeout: 180000 });
    await p.waitForSelector("text=Mods & Plugins", { timeout: 180000 }).catch(() => {});
    await p.waitForTimeout(6000);
    await p.screenshot({ path: `${OUT}/${tag}-${name}.png`, fullPage: false });
    if (tag === "mc") {
      await p.fill('input[aria-label="Search the catalogue"]', "essentials");
      await p.waitForTimeout(4000);
      await p.screenshot({ path: `${OUT}/mc-search-${name}.png` });
      const btn = p.locator("button.nx-cta", { hasText: "Install" }).first();
      if (await btn.count()) { await btn.click(); await p.waitForTimeout(6000); await p.screenshot({ path: `${OUT}/mc-dialog-${name}.png` }); await p.keyboard.press("Escape"); }
      await p.locator("button", { hasText: /^Installed \(/ }).click();
      await p.waitForTimeout(1500);
      await p.screenshot({ path: `${OUT}/mc-installed-${name}.png` });
      const ow = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      console.log(name, "horizontal overflow px:", ow);
    }
  }
  console.log(name, "page errors:", errs.slice(0, 5));
  await ctx.close();
}
await b.close();
